INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21770, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以挪动地方。", "primary_collocate": null, "pronunciation": "yí dòng", "ipa": "i˧˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这是一个移动书架，下面有轮子。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的移动厨房开到了公园。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口有一个移动图书馆。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个舞台是移动的，很容易搬。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边开了一家移动咖啡店。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "移动桌子下面有四个小轮子。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种床是移动的，不是固定的。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生开着移动医院去了山里。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了一个移动的小衣柜。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的移动厕所很干净。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "移动电话", "label": "复合"}, {"form": "移動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "可以挪动地方的，不固定的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd80353b5-d2e7-47f6-bbab-ea2024328f7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21770, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "移动", "is_correct": true, "explanation": "正确答案：移动（yí dòng），可以挪动地方的。"}, {"text": "易懂", "is_correct": false, "explanation": "易懂（yì dǒng）：yì 与 yí 声调不同，dǒng 与 dòng 声调不同，意思是容易理解。"}, {"text": "一共", "is_correct": false, "explanation": "一共（yí gòng）：gòng 与 dòng 只有声母不同（g 与 d），意思是总共。"}, {"text": "异动", "is_correct": false, "explanation": "异动（yì dòng）：yì 与 yí 声调不同，意思是异常的变动。"}, {"text": "移送", "is_correct": false, "explanation": "移送（yí sòng）：sòng 与 dòng 只有声母不同（s 与 d），意思是转交给有关机关。"}], "explanations": {"移动": "正确答案：移动（yí dòng），可以挪动地方的。", "易懂": "易懂（yì dǒng）：yì 与 yí 声调不同，dǒng 与 dòng 声调不同，意思是容易理解。", "一共": "一共（yí gòng）：gòng 与 dòng 只有声母不同（g 与 d），意思是总共。", "异动": "异动（yì dòng）：yì 与 yí 声调不同，意思是异常的变动。", "移送": "移送（yí sòng）：sòng 与 dòng 只有声母不同（s 与 d），意思是转交给有关机关。"}, "sentence_index": null, "correct_answer": "移动"}, "level_3": {"options": [{"text": "移动", "is_correct": true, "explanation": "正确：移动，修饰书架，表示可以挪动，与「下面有轮子」相符。"}, {"text": "固定", "is_correct": false, "explanation": "语义：「固定」表示不能挪动，与「下面有轮子」矛盾。"}, {"text": "悬挂式", "is_correct": false, "explanation": "语义：「悬挂式」指挂在墙上的书架，与「下面有轮子」矛盾。"}, {"text": "精装", "is_correct": false, "explanation": "搭配：「精装」多用于书籍，不说精装书架。"}], "explanations": {"移动": "正确：移动，修饰书架，表示可以挪动，与「下面有轮子」相符。", "固定": "语义：「固定」表示不能挪动，与「下面有轮子」矛盾。", "悬挂式": "语义：「悬挂式」指挂在墙上的书架，与「下面有轮子」矛盾。", "精装": "搭配：「精装」多用于书籍，不说精装书架。"}, "sentence_index": 0, "correct_answer": "移动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个大橱是移动的，它被砌在墙里。", "explanation": "这里应该用〈嵌入〉。移动表示可以挪动，砌进墙里的应说嵌入。"}, {"text": "他的心情移动得很快，一会儿高兴一会儿难过。", "explanation": "这里应该用〈变化〉。移动指物体位置的改变，心情的起伏要说变化。"}, {"text": "这次考试他的移动很高，全班第一。", "explanation": "这里应该用〈成绩〉。移动指物体位置的改变，考试的分数要说成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12c70ff4-bc45-420f-aa00-0997336be39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移动", "is_correct": true, "explanation": "正确：移动，说床可以挪动，与「不是固定的」相符。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：「安静」形容人或场所，不说床是安静的。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：「高兴」形容人的心情，不用于形容床。"}, {"text": "肥胖", "is_correct": false, "explanation": "体貌：「肥胖」形容人或动物的体态，不用于形容床。"}], "explanations": {"移动": "正确：移动，说床可以挪动，与「不是固定的」相符。", "安静": "搭配：「安静」形容人或场所，不说床是安静的。", "高兴": "搭配：「高兴」形容人的心情，不用于形容床。", "肥胖": "体貌：「肥胖」形容人或动物的体态，不用于形容床。"}, "sentence_index": 6, "correct_answer": "移动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的心情移动了很多，今天很难过。", "explanation": "这里应该用〈变化〉。移动指物体位置的改变，心情的起伏要说变化或波动。"}, {"text": "他的体温这一个小时移动了很多。", "explanation": "这里应该用〈升高〉或〈波动〉。移动指物体位置的改变，体温的变化要说升高或波动。"}, {"text": "他的能力这半年移动了很多，进步很快。", "explanation": "这里应该用〈提高〉。移动指物体位置的改变，能力的增长要说提高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12c70ff4-bc45-420f-aa00-0997336be39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个柜子是移动，很方便。", "corrected_sentence": "这个柜子是移动的，很方便。", "error_description": "错误：「是移动」；正确：「是移动的」。「是」字句中作谓语的形容词后面要带「的」，「这个柜子是移动」缺少「的」，应补上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12c70ff4-bc45-420f-aa00-0997336be39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家买了一张移动的的小床，很方便。", "corrected_sentence": "我家买了一张移动的小床，很方便。", "error_description": "错误：「移动的的」；正确：「移动的」。「的」重复，「移动的」后面不能再加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12c70ff4-bc45-420f-aa00-0997336be39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
