INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21778, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一直看一个东西有没有变化。", "primary_collocate": null, "pronunciation": "jiān cè", "ipa": "tɕjɛn˥ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "他一直监测着河水有没有变化。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每小时监测一次我的体温。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们监测豆苗每天长多高。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们监测着云的变化。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小机器会一直监测房间的温度。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天监测自己的体重。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士正在监测病人的血压。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用仪器监测土地里的水。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能监测手机用了多少电。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边有人监测着海水的高低。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "监测着", "label": "体标"}, {"form": "监测了", "label": "体标"}, {"form": "监测过", "label": "体标"}, {"form": "監測", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一直观察某物是否有变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd80353b5-d2e7-47f6-bbab-ea2024328f7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21778, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”与“一直看”的意思相反，句子不通。"}, {"text": "监督", "is_correct": false, "explanation": "搭配：“监督”的对象多是人或工作，不说“监督河水”。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：“挑选”需要可供选择的对象，不能挑选河水的变化。"}, {"text": "监测", "is_correct": true, "explanation": "“监测”指一直观察某物是否有变化，与句意相符。"}], "explanations": {"逃避": "语义：“逃避”与“一直看”的意思相反，句子不通。", "监督": "搭配：“监督”的对象多是人或工作，不说“监督河水”。", "挑选": "搭配：“挑选”需要可供选择的对象，不能挑选河水的变化。", "监测": "“监测”指一直观察某物是否有变化，与句意相符。"}, "sentence_index": 0, "correct_answer": "监测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他出门前监测了一下门窗。", "explanation": "这里应该用〈检查〉。监测指一直观察有无变化，只看一下门窗要用〈检查〉。"}, {"text": "妈妈每天监测我的衣服。", "explanation": "这里应该用〈挑选〉。监测是一直看有没有变化，选衣服要用〈挑选〉。"}, {"text": "我们坐在山顶监测日出。", "explanation": "这里应该用〈观看〉。监测是一直观察有无变化，看日出要用〈观看〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12c70ff4-bc45-420f-aa00-0997336be39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与护士测量病人血压的职责相反。"}, {"text": "欺负", "is_correct": false, "explanation": "搭配：“欺负”的对象是人，不能说欺负血压。"}, {"text": "推销", "is_correct": false, "explanation": "搭配：“推销”的对象是商品，不能用于病人的血压。"}, {"text": "监测", "is_correct": true, "explanation": "“监测”指持续检测病人的生理指标，与“护士”和“病人的血压”搭配。"}], "explanations": {"拒绝": "语义：“拒绝”与护士测量病人血压的职责相反。", "欺负": "搭配：“欺负”的对象是人，不能说欺负血压。", "推销": "搭配：“推销”的对象是商品，不能用于病人的血压。", "监测": "“监测”指持续检测病人的生理指标，与“护士”和“病人的血压”搭配。"}, "sentence_index": 6, "correct_answer": "监测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们在礼堂里监测演讲。", "explanation": "这里应该用〈聆听〉。监测是跟踪状况的变化，听演讲要用〈聆听〉。"}, {"text": "他每晚在家监测新闻联播。", "explanation": "这里应该用〈收看〉。监测是一直观察有无变化，看电视节目要用〈收看〉。"}, {"text": "他站在窗前监测雪景。", "explanation": "这里应该用〈欣赏〉。监测是一直看有没有变化，欣赏雪景要用〈欣赏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12c70ff4-bc45-420f-aa00-0997336be39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她每天监测了院子里的湿度。", "corrected_sentence": "她每天监测院子里的湿度。", "error_description": "错误：「每天监测了」；正确：「每天监测」。「每天」表示经常性的动作，与表示完成的「了」矛盾，应去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12c70ff4-bc45-420f-aa00-0997336be39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他监测的很仔细。", "corrected_sentence": "他监测得很仔细。", "error_description": "错误：“的”；正确：“得”。“监测得很仔细”中“得”连接动词与补语，“的”用在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12c70ff4-bc45-420f-aa00-0997336be39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
