INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你看东西时，眼睛看的方向和位置。", "primary_collocate": null, "pronunciation": "shì jiǎo", "ipa": "ʂʅ˥˩ tɕjau˨˩˦", "syllable_count": 2, "sentences": [{"text": "从飞机窗口往下看，视角很特别。", "target_word": "视角", "complexity_tier": "T3", "furigana": "cóng fēi jī chuāng kǒu wǎng xià kàn, shì jiǎo hěn tè bié.", "sentence_source": "generated"}, {"text": "这张照片的视角很特别。", "target_word": "视角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把相机放低，换了个视角拍这只小猫。", "target_word": "视角", "complexity_tier": "T3", "furigana": "wǒ bǎ xiàng jī fàng dī, huàn le ge shì jiǎo pāi zhè zhī xiǎo māo.", "sentence_source": "generated"}, {"text": "摄影师选了一个很低的视角。", "target_word": "视角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在桥上，视角正好能看到整条河。", "target_word": "视角", "complexity_tier": "T3", "furigana": "tā zhàn zài qiáo shàng, shì jiǎo zhèng hǎo néng kàn dào zhěng tiáo hé.", "sentence_source": "generated"}, {"text": "从树上往下看，视角很高，能看到整个公园。", "target_word": "视角", "complexity_tier": "T3", "furigana": "cóng shù shàng wǎng xià kàn, shì jiǎo hěn gāo, néng kàn dào zhěng gè gōng yuán.", "sentence_source": "generated"}, {"text": "站得高，视角就更大。", "target_word": "视角", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "坐在前排，视角比较好。", "target_word": "视角", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们从上面的视角看这座城市。", "target_word": "视角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的视角可以自己换。", "target_word": "视角", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "视角", "label": "词根"}], "register": "中性", "sense_fingerprint": "看东西或想问题时所站的位置和角度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa75729c-4fdb-4353-ab48-5298e7732270') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "视角", "is_correct": true, "explanation": "正确：“视角”指观察事物的位置和方向，与“从飞机窗口往下看”相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“往下看”只能看到东西，看不到味道，句子说不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“往下看”是视觉行为，不能用它来感知声音。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“特别”通常形容事物的特点，不说“年龄很特别”。"}], "explanations": {"视角": "正确：“视角”指观察事物的位置和方向，与“从飞机窗口往下看”相符。", "味道": "语义：“往下看”只能看到东西，看不到味道，句子说不通。", "声音": "语义：“往下看”是视觉行为，不能用它来感知声音。", "年龄": "搭配：“特别”通常形容事物的特点，不说“年龄很特别”。"}, "sentence_index": 0, "correct_answer": "视角"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的视角很温柔，让人很舒服。", "explanation": "这里应该用〈目光〉。目光可以温柔，视角指观察的位置和方向，不能用“温柔”形容。"}, {"text": "他的视角很坚定，从不动摇。", "explanation": "这里应该用〈立场〉。立场可以坚定，视角只是观察的角度，不能用“坚定”来形容。"}, {"text": "我家和学校之间的视角很远，要坐一个小时车。", "explanation": "这里应该用〈距离〉。视角指观察的位置和方向，两地之间的远近要用“距离”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视角", "is_correct": true, "explanation": "正确：“视角”指观察的角度，与“站得高”的语境相符，站得高视野更开阔。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“站得高”不会改变人的身高，“身高就更大”说不通。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“大”不用来形容“温度”，应说“高”或“低”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“站得高”不会使人的体重变大，句子逻辑不成立。"}], "explanations": {"视角": "正确：“视角”指观察的角度，与“站得高”的语境相符，站得高视野更开阔。", "身高": "语义：“站得高”不会改变人的身高，“身高就更大”说不通。", "温度": "搭配：“大”不用来形容“温度”，应说“高”或“低”。", "体重": "语义：“站得高”不会使人的体重变大，句子逻辑不成立。"}, "sentence_index": 6, "correct_answer": "视角"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个三角形有一个很大的视角。", "explanation": "这里应该用〈角度〉。视角指观察事物的位置和方向，不用来指几何图形中的角。"}, {"text": "他对工作的视角很认真。", "explanation": "这里应该用〈态度〉。视角不能用“认真”来形容，人对工作的看法和行为倾向应说“态度”。"}, {"text": "他的视角落在窗外的树上。", "explanation": "这里应该用〈视线〉。视线可以“落在”某处，视角是观察的角度，不能用“落”来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们换只视角看这个问题，会更清楚。", "corrected_sentence": "我们换个视角看这个问题，会更清楚。", "error_description": "错误：“只视角”。“只”多用于动物等，“视角”应用量词“个”，说“换个视角”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部电影用孩子地视角讲故事。", "corrected_sentence": "这部电影用孩子的视角讲故事。", "error_description": "错误：“孩子地视角”。修饰名词应用结构助词“的”，不能用“地”，应说“孩子的视角”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21784, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21784, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21784, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "遥感就是用机器在远处看东西，不用碰到它。", "primary_collocate": null, "pronunciation": "yáo gǎn", "ipa": "jaʊ˧˥ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "遥感能在很远的地方看清地面。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，遥感不用走到山上就能看山。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们用遥感看这座城市有多大。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机和卫星可以用遥感拍到大海。", "target_word": "遥感", "complexity_tier": "T3", "furigana": "fēi jī hé wèixīng kěyǐ yòng yáogǎn pāi dào dà hǎi", "sentence_source": "generated"}, {"text": "有了遥感，农民不用下地就能看到庄稼。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遥感不用碰到东西，就能知道它的样子。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作是用遥感找地下的水。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的地理课上，我们学了遥感。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨前，气象站用遥感看天上的云。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遥感让人在远处看见森林里的火。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "遥感技术", "label": "复合"}, {"form": "遥感卫星", "label": "复合"}], "register": "中性", "sense_fingerprint": "遥感：用机器在远处看东西，不用碰到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f2b21f7-48af-4f3b-85cd-c9621453e519') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遥感", "is_correct": true, "explanation": "“遥感”是远距离探测的技术，可以作主语，说明它能在远处看清地面。"}, {"text": "乐趣", "is_correct": false, "explanation": "语义：“乐趣”是愉快的感受，不能在远处看清地面。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指人的外貌，不能做看清地面的主语。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性格，与“看清地面”的功能无关。"}], "explanations": {"遥感": "“遥感”是远距离探测的技术，可以作主语，说明它能在远处看清地面。", "乐趣": "语义：“乐趣”是愉快的感受，不能在远处看清地面。", "长相": "体貌：“长相”指人的外貌，不能做看清地面的主语。", "脾气": "语义：“脾气”指性格，与“看清地面”的功能无关。"}, "sentence_index": 0, "correct_answer": "遥感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用遥感听音乐。", "explanation": "这里应该用〈收音机〉。“遥感”是远距离探测物体信息的技术，不能用来听音乐；听广播要用收音机。"}, {"text": "我用遥感换了一个台。", "explanation": "这里应该用〈遥控〉。遥感是探测技术，不是换台的工具。"}, {"text": "我的遥感很懂事。", "explanation": "这里应该用〈孩子〉。“遥感”是技术名称，不能用来形容人；说人懂事要用“孩子”等人物名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遥感", "is_correct": true, "explanation": "“遥感”是用技术探测的手段，正好说明工作内容是找地下的水。"}, {"text": "好奇心", "is_correct": false, "explanation": "语义：“好奇心”是心理状态，不能用来找地下的水。"}, {"text": "风景", "is_correct": false, "explanation": "语义：“风景”指景色，不是找水的手段。"}, {"text": "酒量", "is_correct": false, "explanation": "搭配：“用……找水”的手段应是技术或工具，“酒量”不搭配。"}], "explanations": {"遥感": "“遥感”是用技术探测的手段，正好说明工作内容是找地下的水。", "好奇心": "语义：“好奇心”是心理状态，不能用来找地下的水。", "风景": "语义：“风景”指景色，不是找水的手段。", "酒量": "搭配：“用……找水”的手段应是技术或工具，“酒量”不搭配。"}, "sentence_index": 6, "correct_answer": "遥感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用遥感看家里有没有小偷。", "explanation": "这里应该用〈监控〉。“遥感”是远距离探测物体信息的技术，多用于大范围的地表观测，不用于家里防盗；防盗要用“监控”。"}, {"text": "她对远方的朋友有很强的遥感。", "explanation": "“遥感”是技术名词，指远距离探测，不指人对远方的感觉。"}, {"text": "这台遥感能帮我们做饭。", "explanation": "这里应该用〈炉灶〉。“遥感”是远距离探测的技术，不能用来做饭；做饭要用炉灶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把遥感观察远处的山。", "corrected_sentence": "我们用遥感观察远处的山。", "error_description": "错误：“把遥感”；正确：“用遥感”。“遥感”表示观察的手段，要用介词“用”引出，不能用“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的工作是用一台遥感技术找水。", "corrected_sentence": "他的工作是用一种遥感技术找水。", "error_description": "错误：“一台遥感技术”；正确：“一种遥感技术”。“遥感技术”是技术，应用量词“种”，不用“台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21786, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脆性", "is_correct": true, "explanation": "正确。“脆性”与“韧性”相对，指物体受力时容易破碎的性质。"}, {"text": "硬度", "is_correct": false, "explanation": "硬度指抵抗压入的能力，与“韧性”不构成反义关系。"}, {"text": "重量", "is_correct": false, "explanation": "重量是物体的质量程度，与“韧性”没有反义关系。"}, {"text": "颜色", "is_correct": false, "explanation": "颜色与“韧性”属于不同性质，没有反义关系。"}], "correct_answer": "脆性", "explanations": {"脆性": "正确。“脆性”与“韧性”相对，指物体受力时容易破碎的性质。", "硬度": "硬度指抵抗压入的能力，与“韧性”不构成反义关系。", "重量": "重量是物体的质量程度，与“韧性”没有反义关系。", "颜色": "颜色与“韧性”属于不同性质，没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21786, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脆性", "is_correct": true, "explanation": "正确。“脆性”与“韧性”相对，指物体容易破裂的性质。"}, {"text": "长度", "is_correct": false, "explanation": "长度是尺寸的度量，与“韧性”没有反义关系。"}, {"text": "色泽", "is_correct": false, "explanation": "色泽指物体表面的颜色和光泽，与“韧性”没有反义关系。"}, {"text": "温度", "is_correct": false, "explanation": "温度与“韧性”属于不同性质，没有反义关系。"}], "correct_answer": "脆性", "explanations": {"脆性": "正确。“脆性”与“韧性”相对，指物体容易破裂的性质。", "长度": "长度是尺寸的度量，与“韧性”没有反义关系。", "色泽": "色泽指物体表面的颜色和光泽，与“韧性”没有反义关系。", "温度": "温度与“韧性”属于不同性质，没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21786, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "不容易折断，比如橡皮筋拉长也不会断。", "primary_collocate": null, "pronunciation": "rèn xìng", "ipa": "ɻən˥˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种竹子韧性很好，不容易折断。", "target_word": "韧性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "橡皮筋的韧性很强，拉长也不会断。", "target_word": "韧性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根绳子韧性不够，一拉就断了。", "target_word": "韧性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钢的韧性比铁好。", "target_word": "韧性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "做这把弓需要有韧性的木头。", "target_word": "韧性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "柳树的枝条很有韧性，风吹不断。", "target_word": "韧性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种塑料袋很有韧性，能装很重的东西。", "target_word": "韧性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种面条很有韧性，用手拉也不容易断。", "target_word": "韧性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新买的皮带韧性很好，用不坏。", "target_word": "韧性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张纸有韧性，撕不开。", "target_word": "韧性", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "韌性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体受力弯曲拉长也不易折断的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524b76e-1a79-47e4-a085-bd4ad66e3a29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21786, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "韧性", "is_correct": true, "explanation": "正确。“韧性很好，不容易折断”，描述竹子不易折断的性质。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色本身不会折断，“不容易折断”不能用来形容颜色。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味与“折断”无关，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与“不容易折断”语义不符，句意不通。"}], "explanations": {"韧性": "正确。“韧性很好，不容易折断”，描述竹子不易折断的性质。", "颜色": "搭配：颜色本身不会折断，“不容易折断”不能用来形容颜色。", "香味": "语义：香味与“折断”无关，句意不通。", "价格": "语义：价格与“不容易折断”语义不符，句意不通。"}, "sentence_index": 0, "correct_answer": "韧性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块玻璃的韧性很高，能清楚地看到里面的东西。", "explanation": "〈透明度〉指光线透过的程度，“韧性”指不易折断，这里应该用〈透明度〉。"}, {"text": "钢的一块韧性比铁好。", "explanation": "〈块〉用于有形的块状物，“韧性”是抽象性质，不能当作块状物计量，这里应直接说“钢的韧性”。"}, {"text": "这块合金的韧性很高，划不出痕迹。", "explanation": "〈硬度〉指抵抗划痕、压入的能力，“韧性”指不易折断，这里应该用〈硬度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "韧性", "is_correct": true, "explanation": "正确。“有韧性，能装很重的东西”，塑料袋要有不易断裂的性质。"}, {"text": "图案", "is_correct": false, "explanation": "语义：“图案”是花纹样式，不是可以承重的性质，“能装很重的东西”句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”是听觉现象，与袋子能否承重无关，句意不通。"}, {"text": "手艺", "is_correct": false, "explanation": "搭配：“很有手艺”说人的技能，不能用来形容塑料袋的性能。"}], "explanations": {"韧性": "正确。“有韧性，能装很重的东西”，塑料袋要有不易断裂的性质。", "图案": "语义：“图案”是花纹样式，不是可以承重的性质，“能装很重的东西”句意不通。", "声音": "语义：“声音”是听觉现象，与袋子能否承重无关，句意不通。", "手艺": "搭配：“很有手艺”说人的技能，不能用来形容塑料袋的性能。"}, "sentence_index": 6, "correct_answer": "韧性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在韧性里工作。", "explanation": "这里应该用〈车间〉。“韧性”是抽象性质，不能当作工作场所。"}, {"text": "他把韧性喝进了肚子里。", "explanation": "这里应该用〈饮料〉。“韧性”是抽象性质，不能被喝。"}, {"text": "这张纸的韧性是一个朋友。", "explanation": "“韧性”指材料不易折断的性质，不能与〈人〉等同，这句说法不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根铁丝是韧性，弯了也不断。", "corrected_sentence": "这根铁丝有韧性，弯了也不断。", "error_description": "动词错误：表示“具有”某种性质应用“有”，不能用“是”，应改为“这根铁丝有韧性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块布的韧性的很好，洗多次也不坏。", "corrected_sentence": "这块布的韧性很好，洗多次也不坏。", "error_description": "“的”多余：“韧性很好”中“韧性”后不能再加“的”，应删去多余的“的”，说“这块布的韧性很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
