INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21792, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人生下来就有的本领。", "primary_collocate": null, "pronunciation": "bǐng fù", "ipa": "piŋ²¹⁴ fu⁵¹", "syllable_count": 2, "sentences": [{"text": "他天生就有唱歌的禀赋。", "target_word": "禀赋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明有画画的禀赋。", "target_word": "禀赋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个女孩有学外语的禀赋。", "target_word": "禀赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "禀赋再好，也要练习。", "target_word": "禀赋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "父母发现孩子有数学禀赋。", "target_word": "禀赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的运动禀赋很突出。", "target_word": "禀赋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说我没有写作的禀赋。", "target_word": "禀赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠禀赋和努力成了钢琴家。", "target_word": "禀赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个孩子都有自己的禀赋。", "target_word": "禀赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种禀赋很难得。", "target_word": "禀赋", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "稟賦", "label": "繁体"}, {"form": "资源禀赋", "label": "复合"}], "register": "书面", "sense_fingerprint": "人与生俱来的本领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd80353b5-d2e7-47f6-bbab-ea2024328f7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "禀赋", "is_correct": true, "explanation": "禀赋：指生来就有的本领，此处指唱歌方面天生的本领，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与唱歌无关，“唱歌的颜色”句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格不能用来修饰唱歌，“唱歌的价格”不成搭配。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的重量，不是唱歌方面的本领，句意不通。"}], "explanations": {"禀赋": "禀赋：指生来就有的本领，此处指唱歌方面天生的本领，符合句意。", "颜色": "语义：颜色与唱歌无关，“唱歌的颜色”句意不通。", "价格": "搭配：价格不能用来修饰唱歌，“唱歌的价格”不成搭配。", "体重": "语义：体重是身体的重量，不是唱歌方面的本领，句意不通。"}, "sentence_index": 0, "correct_answer": "禀赋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他学了一身好禀赋。", "explanation": "这里应该用〈本事〉。禀赋指生来就有的本领，学来的要说本事。"}, {"text": "他的禀赋是硕士，所以能在大学任教。", "explanation": "这里应该用〈学历〉。禀赋指生来的本领，受教育的程度要说学历，不能说禀赋。"}, {"text": "他的禀赋比我高一厘米。", "explanation": "这里应该用〈身高〉。禀赋不能用厘米计量，说高矮要用身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12c70ff4-bc45-420f-aa00-0997336be39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "禀赋", "is_correct": true, "explanation": "禀赋：指生来就有的本领，此处指写作方面的天生本领，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与写作的本领无关，“写作的天气”句意不通。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：外貌指容貌，不属于写作方面的本领，句意不通。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是事物的冷热程度，与写作的本领无关，句意不通。"}], "explanations": {"禀赋": "禀赋：指生来就有的本领，此处指写作方面的天生本领，符合句意。", "天气": "语义：天气与写作的本领无关，“写作的天气”句意不通。", "外貌": "语义：外貌指容貌，不属于写作方面的本领，句意不通。", "温度": "语义：温度是事物的冷热程度，与写作的本领无关，句意不通。"}, "sentence_index": 6, "correct_answer": "禀赋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天的禀赋很好，笑个不停。", "explanation": "这里应该用〈心情〉。禀赋是生来就有的，不指一时的心情，说今天的心情要用心情。"}, {"text": "他的禀赋很好，从小不愁吃穿。", "explanation": "这里应该用〈家境〉。禀赋指本领，不指家里的经济条件。"}, {"text": "这次禀赋很难得，你要好好把握。", "explanation": "这里应该用〈机会〉。禀赋指天生的本领，不能指一次难得的机会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12c70ff4-bc45-420f-aa00-0997336be39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的禀赋高很，老师很看好他。", "corrected_sentence": "他的禀赋很高，老师很看好他。", "error_description": "语序错误：程度副词「很」应放在形容词「高」前，应说「很高」，不能说「高很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12c70ff4-bc45-420f-aa00-0997336be39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在音乐方面有很好禀赋。", "corrected_sentence": "她在音乐方面有很好的禀赋。", "error_description": "漏了“的”：定语“很好”修饰名词“禀赋”时中间要加“的”，应说“很好的禀赋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12c70ff4-bc45-420f-aa00-0997336be39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
