INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21800, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以用来做事情的东西，比如水、木头、钱。", "primary_collocate": null, "pronunciation": "zī yuán", "ipa": "tsɹ̩˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "水是很重要的资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的资源很丰富。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要节约资源，不要浪费。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林是地球上的重要资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇缺少资源，生活不太方便。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把钱和人都当成重要的资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油是一种有限的资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的资源不多，大家要一起用。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用有限的资源盖了一座新房子。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头、水和煤都是资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "水、木头、钱等可供使用的物质和财力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b62a16e-8257-4aad-9b92-a998a7c9c5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21800, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "资源", "is_correct": true, "explanation": "正是词目「资源」zī yuán，指可供使用的物质或财力。"}, {"text": "支援", "is_correct": false, "explanation": "zhī 与 zī 声母不同（zh/z），意思是支持、援助。"}, {"text": "自愿", "is_correct": false, "explanation": "zì 与 zī 声调不同，yuàn 与 yuán 声调也不同，意思是自己愿意。"}, {"text": "志愿", "is_correct": false, "explanation": "zhì 与 zī 的声母和声调都不同（zh/z，第4声与第1声），意思是志向或自愿参加。"}], "explanations": {"资源": "正是词目「资源」zī yuán，指可供使用的物质或财力。", "支援": "zhī 与 zī 声母不同（zh/z），意思是支持、援助。", "自愿": "zì 与 zī 声调不同，yuàn 与 yuán 声调也不同，意思是自己愿意。", "志愿": "zhì 与 zī 的声母和声调都不同（zh/z，第4声与第1声），意思是志向或自愿参加。"}, "sentence_index": null, "correct_answer": "资源"}, "level_3": {"options": [{"text": "资源", "is_correct": true, "explanation": "资源：可供使用的物质财富，水属于此类，句意通顺。"}, {"text": "资金", "is_correct": false, "explanation": "语义：「资金」指钱款，水是物质，不是钱款，句意不通。"}, {"text": "资格", "is_correct": false, "explanation": "搭配：「很重要的资格」说的是人或条件，不能用来指水。"}, {"text": "人口", "is_correct": false, "explanation": "语义：「人口」指人的数量，水不是人口，句意不通。"}], "explanations": {"资源": "资源：可供使用的物质财富，水属于此类，句意通顺。", "资金": "语义：「资金」指钱款，水是物质，不是钱款，句意不通。", "资格": "搭配：「很重要的资格」说的是人或条件，不能用来指水。", "人口": "语义：「人口」指人的数量，水不是人口，句意不通。"}, "sentence_index": 0, "correct_answer": "资源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的资源很好，学什么都快。", "explanation": "这里应该用〈资质〉。「资源」指可供利用的物质或财力，不用来指人的天资。"}, {"text": "这座桥的资源很牢固，车辆都能通过。", "explanation": "这里应该用〈质量〉。「资源」指可供利用的物质或财力，不用来说桥的牢固程度。"}, {"text": "他对这次比赛的资源很有信心。", "explanation": "这里应该用〈信心〉。「资源」指可供利用的物质或财力，不用来表示对事情的信心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资源", "is_correct": true, "explanation": "资源：可供使用的物质财富，石油属于此类，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：石油是物质，「天气」不是可以「有限」的东西，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：「心情」是人的感受，石油不能是心情，句意不通。"}, {"text": "人才", "is_correct": false, "explanation": "搭配：「一种……的人才」指人，与「石油」搭配不通。"}], "explanations": {"资源": "资源：可供使用的物质财富，石油属于此类，句意通顺。", "天气": "语义：石油是物质，「天气」不是可以「有限」的东西，句意不通。", "心情": "语义：「心情」是人的感受，石油不能是心情，句意不通。", "人才": "搭配：「一种……的人才」指人，与「石油」搭配不通。"}, "sentence_index": 6, "correct_answer": "资源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电视的资源很清楚，画面很逼真。", "explanation": "这里应该用〈画质〉。「资源」不用来说电视的清晰程度，应说「画质」。"}, {"text": "他的演讲资源很精彩，大家都鼓掌。", "explanation": "这里应该用〈内容〉。「资源」不用来说演讲的内容好坏，应说「内容」。"}, {"text": "这位运动员的资源很棒，跑得很快。", "explanation": "这里应该用〈素质〉。「资源」不用来指运动员的身体条件，应说「素质」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座岛有丰富地资源。", "corrected_sentence": "这座岛有丰富的资源。", "error_description": "助词错误：形容词修饰名词要用「的」，不用「地」；「地」用于修饰动词。应说「丰富的资源」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把这些资源们都分给了各班。", "corrected_sentence": "学校把这些资源都分给了各班。", "error_description": "复数标记错误：「们」只用于人，「资源」是非人名词，不能加「们」，应说「这些资源」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21806, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "间断", "is_correct": true, "explanation": "正确：“间断”与“持续”相对，指中间有停顿，是“持续”（不间断）的反义词。"}, {"text": "出发", "is_correct": false, "explanation": "出发与“持续”没有反义关系，它表示动作的开始，不是“不间断”的对立面。"}, {"text": "参加", "is_correct": false, "explanation": "参加与“持续”没有反义关系，二者不在同一语义维度上对立。"}, {"text": "相信", "is_correct": false, "explanation": "相信与“持续”没有反义关系，它表示心理态度，与时间的连续性无关。"}], "correct_answer": "间断", "explanations": {"间断": "正确：“间断”与“持续”相对，指中间有停顿，是“持续”（不间断）的反义词。", "出发": "出发与“持续”没有反义关系，它表示动作的开始，不是“不间断”的对立面。", "参加": "参加与“持续”没有反义关系，二者不在同一语义维度上对立。", "相信": "相信与“持续”没有反义关系，它表示心理态度，与时间的连续性无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21806, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "间断", "is_correct": true, "explanation": "正确：“间断”与“持续”相对，指中间有停顿，是“持续”（不间断）的反义词。"}, {"text": "购买", "is_correct": false, "explanation": "购买与“持续”没有反义关系，它表示取得物品的行为。"}, {"text": "参观", "is_correct": false, "explanation": "参观与“持续”没有反义关系，它表示去某地看一看。"}, {"text": "批评", "is_correct": false, "explanation": "批评与“持续”没有反义关系，它表示指出缺点或错误。"}], "correct_answer": "间断", "explanations": {"间断": "正确：“间断”与“持续”相对，指中间有停顿，是“持续”（不间断）的反义词。", "购买": "购买与“持续”没有反义关系，它表示取得物品的行为。", "参观": "参观与“持续”没有反义关系，它表示去某地看一看。", "批评": "批评与“持续”没有反义关系，它表示指出缺点或错误。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21806, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一直做，不停。", "primary_collocate": null, "pronunciation": "chí xù", "ipa": "tʂʰʅ˧˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "大雨持续了三天。", "target_word": "持续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种好天气会持续一个星期。", "target_word": "持续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的头疼持续了很久。", "target_word": "持续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛持续了两个小时。", "target_word": "持续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议持续到晚上八点。", "target_word": "持续", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好天气不会持续太久，很快就会结束。", "target_word": "持续", "complexity_tier": "T3", "furigana": "hǎo tiān qì bú huì chí xù tài jiǔ, hěn kuài jiù huì jié shù.", "sentence_source": "generated"}, {"text": "你要持续学习，才能进步。", "target_word": "持续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题已经持续很多年了。", "target_word": "持续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他持续锻炼了半年，身体越来越好。", "target_word": "持续", "complexity_tier": "T3", "furigana": "tā chí xù duàn liàn le bàn nián, shēn tǐ yuè lái yuè hǎo.", "sentence_source": "generated"}, {"text": "音乐持续了半个小时，大家都没说话。", "target_word": "持续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "持续了", "label": "体标"}, {"form": "持续着", "label": "体标"}, {"form": "持续性", "label": "复合"}, {"form": "可持续", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情或动作一直进行、不间断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa75729c-4fdb-4353-ab48-5298e7732270') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "持续", "is_correct": true, "explanation": "正确：“持续”表示一直进行、不间断，与“了三天”这一时间段搭配。"}, {"text": "考虑", "is_correct": false, "explanation": "语义：“考虑”需要有思维的主语，“大雨”不能考虑，句子说不通。"}, {"text": "迟到", "is_correct": false, "explanation": "搭配：“迟到”的主语应是人或交通工具，不能说“大雨迟到了三天”。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”需要有意愿的主语，雨没有意愿，不能拒绝。"}], "explanations": {"持续": "正确：“持续”表示一直进行、不间断，与“了三天”这一时间段搭配。", "考虑": "语义：“考虑”需要有思维的主语，“大雨”不能考虑，句子说不通。", "迟到": "搭配：“迟到”的主语应是人或交通工具，不能说“大雨迟到了三天”。", "拒绝": "语义：“拒绝”需要有意愿的主语，雨没有意愿，不能拒绝。"}, "sentence_index": 0, "correct_answer": "持续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他休息了一会儿，又持续工作了。", "explanation": "这里应该用〈继续〉。持续指不间断地进行，句中“休息了一会儿”说明中间停过；中断后接着做应说“继续”。"}, {"text": "他每隔一个小时就持续喝一次水。", "explanation": "这里应该用〈定时〉。定时指按规定的时间进行，“每隔一个小时”说明动作是间隔重复的，不是不间断地进行。"}, {"text": "他持续着自己的看法，不肯改。", "explanation": "这里应该用〈坚持〉。坚持指始终不改变自己的看法，持续只说动作一直进行，不能带“看法”作宾语表示坚守。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "持续", "is_correct": true, "explanation": "正确：“持续”表示不间断地做，与“学习”搭配，符合“才能进步”的语境。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止学习”与句中“才能进步”的意思相悖，说不通。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃学习”与“才能进步”相矛盾，句子的逻辑不成立。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”不能与“学习”连用作动宾，“学习”不是“散步”的宾语。"}], "explanations": {"持续": "正确：“持续”表示不间断地做，与“学习”搭配，符合“才能进步”的语境。", "停止": "语义：“停止学习”与句中“才能进步”的意思相悖，说不通。", "放弃": "语义：“放弃学习”与“才能进步”相矛盾，句子的逻辑不成立。", "散步": "搭配：“散步”不能与“学习”连用作动宾，“学习”不是“散步”的宾语。"}, "sentence_index": 6, "correct_answer": "持续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了持续生活，他每天打三份工。", "explanation": "这里应该用〈维持〉。维持指保住生计或某种状态，持续只说某事一直进行，不能直接带“生活”作宾语。"}, {"text": "我们要持续安静，不要打扰别人。", "explanation": "这里应该用〈保持〉。保持后常接“安静”“健康”等状态词，持续强调时间上的不间断，不能与“安静”这类状态搭配。"}, {"text": "他努力持续公司的名誉。", "explanation": "这里应该用〈维护〉。维护指保护使之不受损害，持续不能带“名誉”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场演出很持续了一个多小时。", "corrected_sentence": "这场演出持续了一个多小时。", "error_description": "错误：“很持续”。“持续”是动词，不能受程度副词“很”修饰；应去掉“很”，说“持续了一个多小时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种情况还在持续了着。", "corrected_sentence": "这种情况还在持续着。", "error_description": "错误：“持续了着”。“了”和“着”不能同时用在同一动词后；表示动作正在进行只用“着”，应说“持续着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
