INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21824, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以放东西的地方，比如房间里能装东西的地方。", "primary_collocate": null, "pronunciation": "kōng jiān", "ipa": "kʰʊŋ˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "这个柜子的空间很大，能放很多衣服。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "床下面还有一点空间，可以放箱子。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个包里的空间不够放电脑。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱里没有空间放西瓜了。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这间小屋的空间不大，放不下新书柜。", "target_word": "空间", "complexity_tier": "T3", "furigana": "zhè jiān xiǎo wū de kōngjiān bù dà, fàng bu xià xīn shūguì.", "sentence_source": "generated"}, {"text": "车的后备箱空间够放两个行李箱。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书包里还有空间，再放一本书吧。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个盒子的空间太小，放不下鞋。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买一个空间更大的衣柜。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把旧东西扔掉，可以多出一点空间。", "target_word": "空间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "空間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "能放东西的空处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 不下 (Zipf 3.94), 新书 (Zipf 3.75), 柜 (Zipf 3.8)']::text[], '1880ae27-277a-4733-a3c1-9b641a61ba6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21824, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "空间", "is_correct": true, "explanation": "正确：空间（kōng jiān）指可以放东西的地方，与听到的读音一致。"}, {"text": "中间", "is_correct": false, "explanation": "zhōng 与 kōng 声母不同（zh 与 k），意思是位置上的中间，不是能放东西的地方。"}, {"text": "工间", "is_correct": false, "explanation": "gōng 与 kōng 送气与否不同（g 不送气，k 送气），意思是工作的间隙，多指工间操。"}, {"text": "中坚", "is_correct": false, "explanation": "声母不同：zhōng 与 kōng（zh 与 k），“中坚”指骨干力量，与能放东西的空间意思无关。"}], "explanations": {"空间": "正确：空间（kōng jiān）指可以放东西的地方，与听到的读音一致。", "中间": "zhōng 与 kōng 声母不同（zh 与 k），意思是位置上的中间，不是能放东西的地方。", "工间": "gōng 与 kōng 送气与否不同（g 不送气，k 送气），意思是工作的间隙，多指工间操。", "中坚": "声母不同：zhōng 与 kōng（zh 与 k），“中坚”指骨干力量，与能放东西的空间意思无关。"}, "sentence_index": null, "correct_answer": "空间"}, "level_3": {"options": [{"text": "空间", "is_correct": true, "explanation": "正确：空间指能放东西的地方，“很大”修饰它，“能放很多衣服”说明容量，句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用“很大”修饰，“柜子的颜色很大”不成立。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量说明轻重，与“能放很多衣服”的容纳意思无关。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”一般说高低，不说“很大”，且与能放多少衣服无关。"}], "explanations": {"空间": "正确：空间指能放东西的地方，“很大”修饰它，“能放很多衣服”说明容量，句意相符。", "颜色": "搭配：“颜色”不能用“很大”修饰，“柜子的颜色很大”不成立。", "重量": "语义：重量说明轻重，与“能放很多衣服”的容纳意思无关。", "价格": "搭配：“价格”一般说高低，不说“很大”，且与能放多少衣服无关。"}, "sentence_index": 0, "correct_answer": "空间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个柜子里有一只空间，能放很多衣服。", "explanation": "这里量词用错：空间前应用〈个〉，不用〈只〉。“只”多用于动物或单个的小东西，不用于空间。"}, {"text": "她的房间里有一扇空间，能放很多衣服。", "explanation": "这里量词用错：“扇”用于门窗等，不用于空间，应该用〈个〉。"}, {"text": "衣柜底下有一条空间，可以放箱子。", "explanation": "这里量词用错：“条”用于细长的东西，不用于空间，应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空间", "is_correct": true, "explanation": "正确：“书包里还有空间”指有可以放东西的地方，与“再放一本书”相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味，书包里还有味道与再放一本书的意思不符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”说冷热，与书包里还能放书无关。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“还有价格”不成立，“价格”不能指可以放书的地方。"}], "explanations": {"空间": "正确：“书包里还有空间”指有可以放东西的地方，与“再放一本书”相符。", "味道": "语义：“味道”指气味，书包里还有味道与再放一本书的意思不符。", "温度": "语义：“温度”说冷热，与书包里还能放书无关。", "价格": "搭配：“还有价格”不成立，“价格”不能指可以放书的地方。"}, "sentence_index": 6, "correct_answer": "空间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天没有空间看电视。", "explanation": "这里应该用〈时间〉。空间指能放东西的地方，“没有时间”表示没有空闲，不能说“没有空间”。"}, {"text": "房间里有一张空间，可以放沙发。", "explanation": "这里量词用错：“张”用于桌子、纸张等平面的东西，不用于空间，应该用〈个〉。"}, {"text": "老师的空间很严厉。", "explanation": "这里应该用〈态度〉。空间指能放东西的地方，不能用“严厉”来形容；“严厉”修饰的是“态度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "抽屉里还有一本空间，能再放一支笔。", "corrected_sentence": "抽屉里还有一个空间，能再放一支笔。", "error_description": "量词错误：“空间”前应用量词“个”，不能用“本”（“本”用于书本等）。正确说法是“抽屉里还有一个空间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "抽屉里有一副小空间，正好能放一副眼镜。", "corrected_sentence": "抽屉里有一个小空间，正好能放一副眼镜。", "error_description": "量词错误：“副”用于成对的东西，不能用于空间；“空间”前应用量词“个”。正确说法是“一个小空间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
