INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21826, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21826, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "全世界的人们和东西越来越连在一起。", "primary_collocate": null, "pronunciation": "quán qiú huà", "ipa": "tɕʰɥɛn˧˥ tɕʰiou˧˥ xua˥˩", "syllable_count": 3, "sentences": [{"text": "全球化让世界变小了。", "target_word": "全球化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全球化让各国的经济连在一起。", "target_word": "全球化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为全球化，我们能买到世界各地的东西。", "target_word": "全球化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全球化的时代，很多公司在不同国家都有工厂。", "target_word": "全球化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着全球化的发展，各国的文化来往越来越多。", "target_word": "全球化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全球化也有问题，比如小店的生意越来越难做。", "target_word": "全球化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了全球化对生活的影响。", "target_word": "全球化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在全球化的今天，人们坐飞机一天就能到另一个国家。", "target_word": "全球化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络是全球化的重要原因之一。", "target_word": "全球化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写了一篇关于全球化的文章。", "target_word": "全球化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "经济全球化", "label": "复合"}], "register": "书面", "sense_fingerprint": "世界各国在经济、文化上联系越来越紧密的趋势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '447b2f2c-611b-4adc-a6ed-b618209aaf2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21826, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贫困", "is_correct": false, "explanation": "语义：「贫困」指经济上缺钱，与世界变小没有关系。"}, {"text": "全球化", "is_correct": true, "explanation": "正确：「全球化」指世界各国的联系越来越紧密，所以能让世界变小。"}, {"text": "老铁", "is_correct": false, "explanation": "语域：「老铁」是网络口语，不能用在这种说明性的句子里。"}, {"text": "城市化", "is_correct": false, "explanation": "语义：「城市化」指城镇扩大、人口集中，不能让整个世界变小。"}], "explanations": {"贫困": "语义：「贫困」指经济上缺钱，与世界变小没有关系。", "全球化": "正确：「全球化」指世界各国的联系越来越紧密，所以能让世界变小。", "老铁": "语域：「老铁」是网络口语，不能用在这种说明性的句子里。", "城市化": "语义：「城市化」指城镇扩大、人口集中，不能让整个世界变小。"}, "sentence_index": 0, "correct_answer": "全球化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种手机在农村已经全球化了，几乎每家都有。", "explanation": "这里应该用〈普及〉。「全球化」指世界范围的联系，说某种东西在一地广泛流行要用〈普及〉。"}, {"text": "这张桌子全球化了。", "explanation": "这里不这么用：「全球化」指世界范围内联系越来越紧密的过程，不能用来形容桌子这样的具体物体；「桌子全球化了」是误把它当成了「（物品）走向国际、通行各地」的意思。"}, {"text": "这间小店全球化了，只卖本地的蔬菜。", "explanation": "这里应该用〈本地化〉。「全球化」指世界范围的联系；只卖本地蔬菜的小店是本地化，方向与全球化相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漂亮", "is_correct": false, "explanation": "语法：「漂亮」是形容词，不能直接作「讲了……」的宾语。"}, {"text": "全球化", "is_correct": true, "explanation": "正确：「全球化」的影响是老师讲课的内容，与「对生活的影响」搭配。"}, {"text": "跑", "is_correct": false, "explanation": "语法：「跑」是动词，不能直接作「讲了……」的宾语。"}, {"text": "非常", "is_correct": false, "explanation": "语法：「非常」是副词，不能作宾语。"}], "explanations": {"漂亮": "语法：「漂亮」是形容词，不能直接作「讲了……」的宾语。", "全球化": "正确：「全球化」的影响是老师讲课的内容，与「对生活的影响」搭配。", "跑": "语法：「跑」是动词，不能直接作「讲了……」的宾语。", "非常": "语法：「非常」是副词，不能作宾语。"}, "sentence_index": 6, "correct_answer": "全球化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的墙纸全球化得很漂亮。", "explanation": "这里应该用〈美化〉。「全球化」指世界范围的联系，不能用来说墙纸装饰得好看；装饰房间、墙面要用〈美化〉。"}, {"text": "他每天早上全球化两个小时，身体很好。", "explanation": "这里应该用〈锻炼〉。「全球化」指世界范围的联系，不能用来说做运动的时间；每天锻炼身体要用〈锻炼〉。"}, {"text": "这个县正在推进全球化，很多农民搬进了新楼房。", "explanation": "这里应该用〈城镇化〉。全球化指世界范围的联系，农民进城、城镇扩大要用〈城镇化〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "世界经济已经全球化着。", "corrected_sentence": "世界经济已经全球化了。", "error_description": "“已经”表示变化已经完成，要用“了”，不能用“着”；“全球化着”表示持续状态，与“已经”搭配不当，应说“已经全球化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "全球化得很快，各国的联系也越来越多。", "corrected_sentence": "全球化发展得很快，各国的联系也越来越多。", "error_description": "错误：「全球化得很快」；正确：「全球化发展得很快」。「全球化」是名词，要说它的速度，句子需要动词「发展」作谓语，漏掉后句子就不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
