INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21832, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把音乐用符号写下来。", "primary_collocate": null, "pronunciation": "jì pǔ", "ipa": "tɕi˥˩ pʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师教我们怎么记谱，把音符一个个写在纸上。", "target_word": "记谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会听着音乐记谱。", "target_word": "记谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人用特别的符号记谱。", "target_word": "记谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记谱要写清楚每个音的长短。", "target_word": "记谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她听了一遍就能记谱。", "target_word": "记谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天在音乐课上学记谱。", "target_word": "记谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边听一边记谱，写满了一页。", "target_word": "记谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手机也可以记谱，很方便。", "target_word": "记谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首民歌是一位老先生记谱留下来的。", "target_word": "记谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学音乐的人都要学会记谱。", "target_word": "记谱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "记谱法", "label": "复合"}, {"form": "記譜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用乐谱符号把音乐写下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd52fbb8a-e422-4bf9-afdc-b8bdbc3cafb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "记谱", "is_correct": true, "explanation": "“记谱”指用符号把音乐写下来，与“教我们怎么”的学习语境相符。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：“演奏”指用乐器奏出声音，不是用符号写下音乐。"}, {"text": "洗碗", "is_correct": false, "explanation": "语义：洗碗与音乐教学无关，不符合句子的语境。"}, {"text": "缝补", "is_correct": false, "explanation": "语义：“缝补”指缝衣服，与音乐课的语境不符。"}], "explanations": {"记谱": "“记谱”指用符号把音乐写下来，与“教我们怎么”的学习语境相符。", "演奏": "语义：“演奏”指用乐器奏出声音，不是用符号写下音乐。", "洗碗": "语义：洗碗与音乐教学无关，不符合句子的语境。", "缝补": "语义：“缝补”指缝衣服，与音乐课的语境不符。"}, "sentence_index": 0, "correct_answer": "记谱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在办公室记谱，记得很快，老板很满意。", "explanation": "这里应该用〈打字〉。“打字”指用键盘输入文字；“记谱”只用于把音乐写成符号，不能用于办公室的工作。"}, {"text": "他把老师的话记谱在本子上。", "explanation": "这里应该用〈抄写〉。“抄写”指照着文字写下来；“记谱”只用于音乐，不能用于老师的话。"}, {"text": "他用手机录音，把课堂内容记谱下来。", "explanation": "这里应该用〈记录〉。“记录”指把内容写下来或存下来；“记谱”只用于把音乐写成符号，不能用于课堂内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "记谱", "is_correct": true, "explanation": "“记谱”指用符号记录音乐，与“一边听一边”的动作相符。"}, {"text": "演唱", "is_correct": false, "explanation": "语义：“演唱”指唱歌，与“写满了一页”的结果不符。"}, {"text": "装订", "is_correct": false, "explanation": "语义：“装订”指把纸张装在一起，与“一边听”不搭配。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪与“一边听”的音乐语境不符，句子不通。"}], "explanations": {"记谱": "“记谱”指用符号记录音乐，与“一边听一边”的动作相符。", "演唱": "语义：“演唱”指唱歌，与“写满了一页”的结果不符。", "装订": "语义：“装订”指把纸张装在一起，与“一边听”不搭配。", "烹饪": "语义：烹饪与“一边听”的音乐语境不符，句子不通。"}, "sentence_index": 6, "correct_answer": "记谱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他学会了记谱，写出了很多好字。", "explanation": "这里应该用〈书写〉。“书写”指用笔写字；“记谱”只用于把音乐写成符号，不能用于写汉字。"}, {"text": "这个饭店的菜很好吃，大家都来记谱。", "explanation": "这里应该用〈点菜〉。“点菜”指在饭店选择要吃的菜；“记谱”只用于音乐，不能用于饭店。"}, {"text": "他每天练习记谱课文，效果很好。", "explanation": "这里应该用〈朗读〉。“朗读”指出声读文字；“记谱”只用于音乐，不能用于课文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天都认真记谱，得很快。", "corrected_sentence": "他每天都认真记谱，记得很快。", "error_description": "补语结构错误：“记谱”后用“得”引出程度补语时，要重复动词“记”，应说“记谱记得很快”，不能省略“记”而说“记谱得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她学了把记谱，现在能自己写谱。", "corrected_sentence": "她学了记谱，现在能自己写谱。", "error_description": "“把”字用错：“记谱”是动词，作“学”的宾语，前面不能加“把”。应说“她学了记谱”，去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
