INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21834, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用东西或话让别人明白你的想法。", "primary_collocate": null, "pronunciation": "biǎo shì", "ipa": "pjaʊ̯˨˩˦ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他点点头，表示同意。", "target_word": "表示", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她笑着向老师表示感谢。", "target_word": "表示", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我用手势表示我听不懂。", "target_word": "表示", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友们都表示愿意帮助我。", "target_word": "表示", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们举手表示赞成。", "target_word": "表示", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小王对这个办法表示满意。", "target_word": "表示", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家鼓掌表示欢迎新同学。", "target_word": "表示", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他笑了笑，表示自己不介意。", "target_word": "表示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子送花给妈妈，表示对她的爱。", "target_word": "表示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理表示明天会给我们答复。", "target_word": "表示", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "表示了", "label": "体标"}, {"form": "表示过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用言语、动作或东西把想法、态度告诉别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8732c7-e609-4f0d-a53d-cb81e17c8e1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表示", "is_correct": true, "explanation": "正确。“他点点头，表示同意”，表示用动作说出态度。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：点头表示赞同，“拒绝”与点头的意思矛盾，句子不通。"}, {"text": "摇", "is_correct": false, "explanation": "配价：“摇”的宾语是头、手等，不能带“同意”作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“同意”不能被“吃”，搭配不当。"}], "explanations": {"表示": "正确。“他点点头，表示同意”，表示用动作说出态度。", "拒绝": "语义：点头表示赞同，“拒绝”与点头的意思矛盾，句子不通。", "摇": "配价：“摇”的宾语是头、手等，不能带“同意”作宾语。", "吃": "搭配：“同意”不能被“吃”，搭配不当。"}, "sentence_index": 0, "correct_answer": "表示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中表示得很好。", "explanation": "这里应该用〈表现〉。表现指做事的状态或成绩，比赛中的状态要说表现，“表示”用于说出想法或态度。"}, {"text": "老师表示了那个学生。", "explanation": "这里应该用〈表扬〉。表扬指称赞人，“表示”不能带人作宾语。"}, {"text": "他在展览会上表示了新产品。", "explanation": "这里应该用〈展示〉。展示指让人看到，新产品要说展示，“表示”指说出想法或态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1813ad-4e9b-4dea-8c46-1fd73d6115f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表示", "is_correct": true, "explanation": "正确。“大家鼓掌表示欢迎新同学”，表示用动作表达欢迎。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：鼓掌是欢迎的动作，“驱赶”与欢迎的意思相反。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：禁止与欢迎相反，句子意思说不通。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”搭配东西，不能说扔欢迎新同学。"}], "explanations": {"表示": "正确。“大家鼓掌表示欢迎新同学”，表示用动作表达欢迎。", "驱赶": "语义：鼓掌是欢迎的动作，“驱赶”与欢迎的意思相反。", "禁止": "语义：禁止与欢迎相反，句子意思说不通。", "扔": "搭配：“扔”搭配东西，不能说扔欢迎新同学。"}, "sentence_index": 6, "correct_answer": "表示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司表示了优秀员工。", "explanation": "这里应该用〈表彰〉。表彰指公开赞扬，“表示”不能带人作宾语。"}, {"text": "这家餐厅表示了新菜。", "explanation": "这里应该用〈宣传〉。宣传指向大众介绍，“表示”指说出态度或意思，不能用于宣传新菜。"}, {"text": "他在舞台上表示了才华。", "explanation": "这里应该用〈展现〉。展现指显露出来，才华要说展现，“表示”用于表达态度或意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1813ad-4e9b-4dea-8c46-1fd73d6115f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他摇摇头，表示给反对。", "corrected_sentence": "他摇摇头，表示反对。", "error_description": "错误：“表示”后面直接接宾语“反对”，中间不能加“给”。正确：“他摇摇头，表示反对。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1813ad-4e9b-4dea-8c46-1fd73d6115f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她坚定地表示地反对。", "corrected_sentence": "她坚定地表示反对。", "error_description": "错误：多余的“地”插在动词“表示”与宾语“反对”之间，状语“地”只应放在“坚定”之后。正确：“她坚定地表示反对。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1813ad-4e9b-4dea-8c46-1fd73d6115f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
