INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21842, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "给人用的。", "primary_collocate": null, "pronunciation": "rén yòng", "ipa": "ɻən˧˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种药是人用的，不是兽用的。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶药是人用的，小狗不能吃。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个药膏是人用的，不能涂在马身上。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种牙膏是人用的，狗不能用。", "target_word": "人用", "complexity_tier": "T3", "furigana": "rén yòng", "sentence_source": "generated"}, {"text": "这种洗发水是人用的，不能给小狗洗澡。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请别把人用的药给宠物吃。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是人用的体温计，不是动物用的。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种消毒液是人用的，小猫不能碰。", "target_word": "人用", "complexity_tier": "T3", "furigana": "rén yòng", "sentence_source": "generated"}, {"text": "医生说这瓶是人用的，马不能用。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个是人用的药，动物用的药在那边。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "供人使用的，区别于兽用、动物用的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2b68117-69f0-4db3-8b42-afed4406c8c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21842, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食用", "is_correct": false, "explanation": "搭配：“食用”只说可以吃的东西，药品不能说“食用的”。"}, {"text": "人用", "is_correct": true, "explanation": "“人用”指供人使用，与后半句“不是兽用的”形成对照，填入正确。"}, {"text": "野生", "is_correct": false, "explanation": "语义：“野生”说明天然生长，不表示用途，与“兽用”的用途对照不合。"}, {"text": "易燃", "is_correct": false, "explanation": "语义：“易燃”说明物质性质，不能说明这种药供谁使用，与“兽用”对照不合。"}], "explanations": {"食用": "搭配：“食用”只说可以吃的东西，药品不能说“食用的”。", "人用": "“人用”指供人使用，与后半句“不是兽用的”形成对照，填入正确。", "野生": "语义：“野生”说明天然生长，不表示用途，与“兽用”的用途对照不合。", "易燃": "语义：“易燃”说明物质性质，不能说明这种药供谁使用，与“兽用”对照不合。"}, "sentence_index": 0, "correct_answer": "人用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只猫是人用的，每天陪主人玩。", "explanation": "这里应该用〈兽用〉。“人用”指供人使用的物品，给动物用的东西才说兽用，猫是动物，不能说它是人用的。"}, {"text": "这位医生是人用的，专门给病人看病。", "explanation": "这里不能用〈人用〉。“人用”只修饰供人使用的物品，不能用来形容医生这样的人。"}, {"text": "这匹马是人用的，今天在草地上吃草。", "explanation": "这里应该用〈兽用〉。“人用”指供人使用，马是动物，不能说它是人用的，给马用的东西要说兽用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e82f6a0-beb9-4f40-83b9-f068af0d5d6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "炎热", "is_correct": false, "explanation": "语义：“炎热”描述天气或温度，不能说明体温计供谁使用，与“不是动物用的”的用途对照不合。"}, {"text": "人用", "is_correct": true, "explanation": "“人用”指供人使用，与“不是动物用的”形成对照，填入正确。"}, {"text": "有毒", "is_correct": false, "explanation": "语义：“有毒”说明性质，不表示使用对象，句中要求的是用途对照，因此不合。"}, {"text": "兽用", "is_correct": false, "explanation": "语义：“兽用”与“不是动物用的”意思相反，句中自相矛盾。"}], "explanations": {"炎热": "语义：“炎热”描述天气或温度，不能说明体温计供谁使用，与“不是动物用的”的用途对照不合。", "人用": "“人用”指供人使用，与“不是动物用的”形成对照，填入正确。", "有毒": "语义：“有毒”说明性质，不表示使用对象，句中要求的是用途对照，因此不合。", "兽用": "语义：“兽用”与“不是动物用的”意思相反，句中自相矛盾。"}, "sentence_index": 6, "correct_answer": "人用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药是人用的，给猫吃。", "explanation": "这里应该用〈兽用〉。“人用”指供人使用，给猫吃的药要说兽用。"}, {"text": "这些饲料是人用的，给牛吃。", "explanation": "这里不能用〈人用〉。饲料供牛吃，“人用”的对象是人，应说〈兽用〉。"}, {"text": "这只羊是人用的，每天在山坡上吃草。", "explanation": "这里不能用〈人用〉。“人用”指供人使用的物品，羊是动物，不能说它是人用的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e82f6a0-beb9-4f40-83b9-f068af0d5d6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种药很人用的，狗不能吃。", "corrected_sentence": "这种药是人用的，狗不能吃。", "error_description": "错误：很人用的。正确：是人用的。“人用”不能被“很”修饰，应用“是……的”来表示。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e82f6a0-beb9-4f40-83b9-f068af0d5d6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种剪刀是人用了的，猫不能碰。", "corrected_sentence": "这种剪刀是人用的，猫不能碰。", "error_description": "助词错误：“人用”后面不能加“了”，正确的说法是“人用的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e82f6a0-beb9-4f40-83b9-f068af0d5d6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21844, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "学", "is_correct": true, "explanation": "反义：“教”是让人学会，“学”是跟着别人学，二者相对。"}, {"text": "吃", "is_correct": false, "explanation": "无关：“吃”与“教”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "无关：“跑”与“教”没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "无关：“睡”与“教”没有反义关系。"}], "correct_answer": "学", "explanations": {"学": "反义：“教”是让人学会，“学”是跟着别人学，二者相对。", "吃": "无关：“吃”与“教”没有反义关系。", "跑": "无关：“跑”与“教”没有反义关系。", "睡": "无关：“睡”与“教”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21844, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "学", "is_correct": true, "explanation": "反义：“教”是让人学会，“学”是跟着别人学，二者相对。"}, {"text": "写", "is_correct": false, "explanation": "无关：“写”与“教”没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "无关：“笑”与“教”没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "无关：“走”与“教”没有反义关系。"}], "correct_answer": "学", "explanations": {"学": "反义：“教”是让人学会，“学”是跟着别人学，二者相对。", "写": "无关：“写”与“教”没有反义关系。", "笑": "无关：“笑”与“教”没有反义关系。", "走": "无关：“走”与“教”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21844, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人跟着你的样子做事情。", "primary_collocate": null, "pronunciation": "jiāo", "ipa": "tɕiɑʊ̯˥", "syllable_count": 1, "sentences": [{"text": "爸爸教我骑自行车。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你教我怎么用这个手机。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶教孙女包饺子。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐教我做西红柿炒蛋。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他教了我一个简单的办法。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们写汉字。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想教小狗坐下。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友教我怎么泡茶。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈教我把衣服叠好。", "target_word": "教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁教你这样做的？", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "教了", "label": "体标（了）"}, {"form": "教过", "label": "体标（过）"}, {"form": "教教", "label": "重叠"}], "register": "中性", "sense_fingerprint": "教：做给别人看，让别人学会做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf20c0d-3c61-4a52-8a10-ec6c7498801e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21844, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "教", "is_correct": true, "explanation": "jiāo（第一声）意思是教，即让别人跟着你的样子学会做事。"}, {"text": "叫", "is_correct": false, "explanation": "jiào（第四声）与 jiāo（第一声）声调不同，意思是呼喊。"}, {"text": "脚", "is_correct": false, "explanation": "jiǎo（第三声）与 jiāo（第一声）声调不同，意思是脚。"}, {"text": "敲", "is_correct": false, "explanation": "qiāo 与 jiāo 声母不同，意思是敲打。"}, {"text": "消", "is_correct": false, "explanation": "xiāo 与 jiāo 声母不同，意思是消失或消除。"}, {"text": "江", "is_correct": false, "explanation": "jiāng 与 jiāo 韵母不同，意思是江河。"}], "explanations": {"教": "jiāo（第一声）意思是教，即让别人跟着你的样子学会做事。", "叫": "jiào（第四声）与 jiāo（第一声）声调不同，意思是呼喊。", "脚": "jiǎo（第三声）与 jiāo（第一声）声调不同，意思是脚。", "敲": "qiāo 与 jiāo 声母不同，意思是敲打。", "消": "xiāo 与 jiāo 声母不同，意思是消失或消除。", "江": "jiāng 与 jiāo 韵母不同，意思是江河。"}, "sentence_index": null, "correct_answer": "教"}, "level_3": {"options": [{"text": "教", "is_correct": true, "explanation": "教：让人学会骑车，与“爸爸教我”的句意相符。"}, {"text": "追", "is_correct": false, "explanation": "语义：追是追赶，“爸爸追我骑自行车”说的不是教人骑车。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：吃的宾语应是食物，不能与“骑自行车”搭配。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：擦的宾语是物件表面，“擦我骑自行车”不成立。"}], "explanations": {"教": "教：让人学会骑车，与“爸爸教我”的句意相符。", "追": "语义：追是追赶，“爸爸追我骑自行车”说的不是教人骑车。", "吃": "搭配：吃的宾语应是食物，不能与“骑自行车”搭配。", "擦": "搭配：擦的宾语是物件表面，“擦我骑自行车”不成立。"}, "sentence_index": 0, "correct_answer": "教"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他教我明天的会议取消了。", "explanation": "这里应该用〈告诉〉。“教”指让人学会某种做法，传达会议取消的消息要用〈告诉〉。"}, {"text": "学校教我们下周放假。", "explanation": "这里应该用〈通知〉。“教”是让人学会某事，宣布放假这类消息要用〈通知〉。"}, {"text": "周末我教朋友去公园散步。", "explanation": "这里应该用〈陪〉。“教”是让人学会做事，陪同朋友外出散步要用〈陪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21844, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "教", "is_correct": true, "explanation": "jiāo（第一声）意思是教，即让别人学会做某件事。"}, {"text": "角", "is_correct": false, "explanation": "jiǎo（第三声）与 jiāo（第一声）声调不同，意思是角落或角度。"}, {"text": "较", "is_correct": false, "explanation": "jiào（第四声）与 jiāo（第一声）声调不同，意思是比较。"}, {"text": "家", "is_correct": false, "explanation": "jiā 与 jiāo 韵母不同，意思是家庭。"}, {"text": "嚼", "is_correct": false, "explanation": "jiáo（第二声）与 jiāo（第一声）声调不同，意思是咀嚼。"}], "explanations": {"教": "jiāo（第一声）意思是教，即让别人学会做某件事。", "角": "jiǎo（第三声）与 jiāo（第一声）声调不同，意思是角落或角度。", "较": "jiào（第四声）与 jiāo（第一声）声调不同，意思是比较。", "家": "jiā 与 jiāo 韵母不同，意思是家庭。", "嚼": "jiáo（第二声）与 jiāo（第一声）声调不同，意思是咀嚼。"}, "sentence_index": null, "correct_answer": "教"}, "level_3": {"options": [{"text": "教", "is_correct": true, "explanation": "教：训练小狗听从指令坐下，与“我想教小狗坐下”的句意相符。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：喂的对象是吃的东西，“喂小狗坐下”不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：穿的宾语是衣物，不能用于让小狗坐下。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是抛掷，“扔小狗坐下”与句意不符。"}], "explanations": {"教": "教：训练小狗听从指令坐下，与“我想教小狗坐下”的句意相符。", "喂": "搭配：喂的对象是吃的东西，“喂小狗坐下”不通。", "穿": "搭配：穿的宾语是衣物，不能用于让小狗坐下。", "扔": "语义：扔是抛掷，“扔小狗坐下”与句意不符。"}, "sentence_index": 6, "correct_answer": "教"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全家人在门口教爷爷。", "explanation": "这里应该用〈迎接〉。“教”用于让人学会做事，在门口招呼来访的人要用〈迎接〉。"}, {"text": "爸爸教好了自行车。", "explanation": "这里应该用〈修〉。“教”不用于修理器物，把自行车修好要用〈修〉。"}, {"text": "我每天教房间。", "explanation": "这里应该用〈打扫〉。“教”的对象是人，清理房间要用〈打扫〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷明天教了我写毛笔字。", "corrected_sentence": "爷爷明天教我写毛笔字。", "error_description": "错误：“教了”，正确：“教”。“明天”指将来，动作还没有发生，动词后不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我教了会弟弟骑自行车。", "corrected_sentence": "我教会了弟弟骑自行车。", "error_description": "错误：“教了会”，正确：“教会了”。结果补语“会”要紧跟动词“教”，“了”放在“教会”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
