INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21852, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你想表达的内容或用意。例如说“高兴”，意思是心里觉得好。", "primary_collocate": null, "pronunciation": "yì si", "ipa": "i˥˩ sɨ", "syllable_count": 2, "sentences": [{"text": "我想表达的意思很简单。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你用简单的话说明你的意思。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的意思是我们下周再开会。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别误会，我没有别的意思。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太明白你说的意思。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还小，说不清楚自己的意思。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的意思是不想去吗？", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把我的意思写在纸上了。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说了很多，我才听懂他的意思。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用这个手势表达什么意思？", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "说话人想表达的想法或用意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d06d5c5-2367-404d-917b-166cece11c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意思", "is_correct": true, "explanation": "正确：「意思」指说话人想表达的内容，与「我想表达的意思很简单」相合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」只说人的体形，不能说想表达的身材。"}, {"text": "价格", "is_correct": false, "explanation": "语义：想表达的内容没有价格，「想表达的价格」说不通。"}, {"text": "重量", "is_correct": false, "explanation": "语义：想表达的内容没有重量，「想表达的重量」说不通。"}], "explanations": {"意思": "正确：「意思」指说话人想表达的内容，与「我想表达的意思很简单」相合。", "身材": "体貌：「身材」只说人的体形，不能说想表达的身材。", "价格": "语义：想表达的内容没有价格，「想表达的价格」说不通。", "重量": "语义：想表达的内容没有重量，「想表达的重量」说不通。"}, "sentence_index": 0, "correct_answer": "意思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这件事的意思很认真。", "explanation": "这里应该用〈态度〉。「态度认真」形容做事的心态；「意思」指想说的内容，不指人对事情的态度。"}, {"text": "他刚才对我发了好大的意思。", "explanation": "这里应该用〈脾气〉。「发脾气」是固定说法，「意思」不能与「发」搭配。"}, {"text": "他下定了意思。", "explanation": "这里应该用〈决心〉。「下定决心」是固定说法，「意思」不能与「下定」搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '129bcd71-d37e-4369-81ee-80399ce3f28a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21852, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "意思", "is_correct": true, "explanation": "正确答案：意思（yì si），指说话人想表达的内容或用意。"}, {"text": "议事", "is_correct": false, "explanation": "议事（yì shì）：第二字声母为 sh、声调为第四声，与「思」（si）不同；意思是商议事情。"}, {"text": "意识", "is_correct": false, "explanation": "意识（yì shí）：第二字声母为 sh、声调为第二声，与「思」（si）不同；意思是人对事物的觉察。"}, {"text": "一丝", "is_correct": false, "explanation": "一丝（yī sī）：第一字为第一声「一」，与「意」（yì，第四声）声调不同；第二字为第一声「丝」，与轻声的「思」不同。意思是极细的线或极少的量。"}], "explanations": {"意思": "正确答案：意思（yì si），指说话人想表达的内容或用意。", "议事": "议事（yì shì）：第二字声母为 sh、声调为第四声，与「思」（si）不同；意思是商议事情。", "意识": "意识（yì shí）：第二字声母为 sh、声调为第二声，与「思」（si）不同；意思是人对事物的觉察。", "一丝": "一丝（yī sī）：第一字为第一声「一」，与「意」（yì，第四声）声调不同；第二字为第一声「丝」，与轻声的「思」不同。意思是极细的线或极少的量。"}, "sentence_index": null, "correct_answer": "意思"}, "level_3": {"options": [{"text": "意思", "is_correct": true, "explanation": "正确：「意思」指说话人的用意，与「你的意思是不想去吗」相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」指岁数，与说话人是否想去无关，句意不通。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：「脸色」指面部气色，不能用来指说话人的想法。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」指身体的重量，不能用来问是否想去。"}], "explanations": {"意思": "正确：「意思」指说话人的用意，与「你的意思是不想去吗」相合。", "年龄": "语义：「年龄」指岁数，与说话人是否想去无关，句意不通。", "脸色": "体貌：「脸色」指面部气色，不能用来指说话人的想法。", "体重": "语义：「体重」指身体的重量，不能用来问是否想去。"}, "sentence_index": 6, "correct_answer": "意思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他脸上的意思很平静。", "explanation": "这里应该用〈表情〉。「脸上的表情」是常见说法，「意思」指用意，不会出现在脸上。"}, {"text": "这个方法的意思很贵。", "explanation": "这里应该用〈成本〉。“成本高”说的是花费；“意思”指想说的内容，不能用来说价钱。"}, {"text": "这碗汤的意思很咸。", "explanation": "这里应该用〈味道〉。「味道咸」形容食物的味觉；「意思」指想说的内容，不能用于汤的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '129bcd71-d37e-4369-81ee-80399ce3f28a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只意思想说。", "corrected_sentence": "他有一个意思想说。", "error_description": "量词错误：「意思」应用量词「个」，不能用「只」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '129bcd71-d37e-4369-81ee-80399ce3f28a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我终于弄懂了他的意思们。", "corrected_sentence": "我终于弄懂了他的意思。", "error_description": "错误：“们”表示复数，只用于指人的名词；“意思”后加“们”不通。正确：去掉“们”，说“他的意思”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '129bcd71-d37e-4369-81ee-80399ce3f28a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
