INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21856, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "高低就是东西上面和下面差多少。", "primary_collocate": null, "pronunciation": "gāo dī", "ipa": "kɑʊ˥ ti˥", "syllable_count": 2, "sentences": [{"text": "请看看这个书架的高低。", "target_word": "高低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张床的高低正好。", "target_word": "高低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明比较两个杯子的高低。", "target_word": "高低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凳子的高低不对，我坐着不舒服。", "target_word": "高低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的高低会影响船过去。", "target_word": "高低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这堵墙的高低不一样，两边差很多。", "target_word": "高低", "complexity_tier": "T3", "furigana": "zhè dǔ qiáng de gāodī bù yíyàng, liǎng biān chà hěn duō.", "sentence_source": "generated"}, {"text": "爸爸量了量门的高低。", "target_word": "高低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台阶的高低要适合小孩子。", "target_word": "高低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两把椅子的高低不一样。", "target_word": "高低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花的高低都不一样。", "target_word": "高低", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高高低低", "label": "重叠"}], "register": "中性", "sense_fingerprint": "东西上下之间的高度差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '248f5714-59ca-4c41-94f7-b47c7a28fb77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21856, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高低", "is_correct": true, "explanation": "高低 gāodī：东西上面和下面的高度差。"}, {"text": "高地", "is_correct": false, "explanation": "“低”（dī，第一声）与“地”（dì，第四声）声调不同，高地指地势较高的地方。"}, {"text": "高一", "is_correct": false, "explanation": "“低”（dī）与“一”（yī）声母不同，高一指高中一年级。"}, {"text": "高息", "is_correct": false, "explanation": "“低”（dī）与“息”（xī）声母不同，高息指较高的利息。"}, {"text": "高梯", "is_correct": false, "explanation": "“低”（dī）与“梯”（tī）声母不同，高梯指较高的梯子。"}], "explanations": {"高低": "高低 gāodī：东西上面和下面的高度差。", "高地": "“低”（dī，第一声）与“地”（dì，第四声）声调不同，高地指地势较高的地方。", "高一": "“低”（dī）与“一”（yī）声母不同，高一指高中一年级。", "高息": "“低”（dī）与“息”（xī）声母不同，高息指较高的利息。", "高梯": "“低”（dī）与“梯”（tī）声母不同，高梯指较高的梯子。"}, "sentence_index": null, "correct_answer": "高低"}, "level_3": {"options": [{"text": "高低", "is_correct": true, "explanation": "正确：书架上下之间的高度差可以用“看看高低”来表示。"}, {"text": "味道", "is_correct": false, "explanation": "配价：“看”后接可见的事物，“味道”不能用眼睛看。"}, {"text": "冷热", "is_correct": false, "explanation": "语义：书架不分冷热，与“看”的对象不相合。"}, {"text": "声音", "is_correct": false, "explanation": "配价：“看”不能接声音，声音要用耳朵听。"}], "explanations": {"高低": "正确：书架上下之间的高度差可以用“看看高低”来表示。", "味道": "配价：“看”后接可见的事物，“味道”不能用眼睛看。", "冷热": "语义：书架不分冷热，与“看”的对象不相合。", "声音": "配价：“看”不能接声音，声音要用耳朵听。"}, "sentence_index": 0, "correct_answer": "高低"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妹妹的高低已经超过了我。", "explanation": "这里应该用〈高矮〉。人的身高说高矮，高低多用于物体的上下高度。"}, {"text": "这口缸的高低很深。", "explanation": "这里应该用〈深浅〉。缸的深浅指从口到底的距离，高低指上下高度，不说“缸的高低很深”。"}, {"text": "这张床的高低是三百块钱。", "explanation": "这里应该用〈价格〉。床的价钱说价格，高低指上下差多少，不表示钱数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高低", "is_correct": true, "explanation": "正确：量门的高低，指量门从下到上的高度。"}, {"text": "颜色", "is_correct": false, "explanation": "配价：“量”后接可以度量的数值，颜色不能量。"}, {"text": "气味", "is_correct": false, "explanation": "语义：门的气味不能用“量”来测。"}, {"text": "滋味", "is_correct": false, "explanation": "语义：“滋味”指味道，门没有滋味可言。"}], "explanations": {"高低": "正确：量门的高低，指量门从下到上的高度。", "颜色": "配价：“量”后接可以度量的数值，颜色不能量。", "气味": "语义：门的气味不能用“量”来测。", "滋味": "语义：“滋味”指味道，门没有滋味可言。"}, "sentence_index": 6, "correct_answer": "高低"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "从门到窗的高低是两米。", "explanation": "这里应该用〈距离〉。水平方向的远近说距离，高低只指上下的高度。"}, {"text": "这箱子的高低是二十公斤。", "explanation": "这里应该用〈重量〉。物体的轻重说重量，高低不表示重量。"}, {"text": "这辆车的高低很快。", "explanation": "这里应该用〈速度〉。车行驶的快慢说速度，高低不表示速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个书架很高低合适。", "corrected_sentence": "这个书架的高低合适。", "error_description": "“很高低”应为“高低”前不加“很”。“高低”是名词，不能被“很”修饰，应说“这个书架的高低合适”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两排柜子的高低被很大。", "corrected_sentence": "这两排柜子的高低很大。", "error_description": "错误：“被”字句要求动词性谓语，不能直接接形容词“很大”，应去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
