INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21858, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手按或拨动琴上的弦或键，让琴发出声音。", "primary_collocate": null, "pronunciation": "tán qín", "ipa": "tʰan˧˥ tɕʰin˧˥", "syllable_count": 2, "sentences": [{"text": "他坐在钢琴前弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明每个周末都去学校弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶年轻时在家弹琴给我们听。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她弹琴的时候，手指很轻。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上十点以后请不要弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弹琴时，两只手要放松。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他弹琴弹得很好。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有人弹琴，很多人在听。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在音乐教室里练习弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷退休后，每天上午都弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "弹弹琴", "label": "重叠"}, {"form": "彈琴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用手指按键或拨弦使琴发声的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d06d5c5-2367-404d-917b-166cece11c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21858, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弹琴", "is_correct": true, "explanation": "正确：「弹琴」与「他坐在钢琴前」相合，指坐着演奏钢琴。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：坐着不能跑步，与「坐在钢琴前」矛盾。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：钢琴前不是洗澡的地方，“坐在钢琴前洗澡”说不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：坐在钢琴前不能游泳，句意不通。"}], "explanations": {"弹琴": "正确：「弹琴」与「他坐在钢琴前」相合，指坐着演奏钢琴。", "跑步": "语义：坐着不能跑步，与「坐在钢琴前」矛盾。", "洗澡": "语义：钢琴前不是洗澡的地方，“坐在钢琴前洗澡”说不通。", "游泳": "语义：坐在钢琴前不能游泳，句意不通。"}, "sentence_index": 0, "correct_answer": "弹琴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他弹口琴的时候很用力。", "explanation": "这里应该用〈吹〉。口琴要用「吹」，「弹」用于钢琴、古筝等弦乐器或按键乐器。"}, {"text": "她弹锣的时候很用力。", "explanation": "这里应该用〈敲〉。锣要用「敲」，不用「弹」。"}, {"text": "他弹唢呐的时候很用力。", "explanation": "这里应该用〈吹〉。唢呐要用「吹」，「弹」用于靠手按或拨动弦、键发声的乐器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '129bcd71-d37e-4369-81ee-80399ce3f28a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "弹琴", "is_correct": true, "explanation": "正确：「他弹琴弹得很好」中，前一个「弹琴」是主要动作，与句意相合。"}, {"text": "洗碗", "is_correct": false, "explanation": "语义：洗碗与「弹得很好」搭不上，句意不通。"}, {"text": "叫醒", "is_correct": false, "explanation": "配价：「叫醒」需要被叫醒的人作宾语，句中缺宾语。"}, {"text": "切菜", "is_correct": false, "explanation": "语义：切菜与「弹得很好」无关，句意不通。"}], "explanations": {"弹琴": "正确：「他弹琴弹得很好」中，前一个「弹琴」是主要动作，与句意相合。", "洗碗": "语义：洗碗与「弹得很好」搭不上，句意不通。", "叫醒": "配价：「叫醒」需要被叫醒的人作宾语，句中缺宾语。", "切菜": "语义：切菜与「弹得很好」无关，句意不通。"}, "sentence_index": 6, "correct_answer": "弹琴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天弹自行车。", "explanation": "这里应该用〈骑〉。自行车要用「骑」，「弹」不能用于交通工具。"}, {"text": "她每天弹毽子。", "explanation": "这里应该用〈踢〉。毽子要用「踢」，「弹」不能用于毽子。"}, {"text": "他弹象棋。", "explanation": "这里应该用〈下〉。象棋要用「下」，「弹」不能用于棋类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '129bcd71-d37e-4369-81ee-80399ce3f28a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他弹琴了一会儿。", "corrected_sentence": "他弹琴弹了一会儿。", "error_description": "离合词错误：「弹琴」中间插入时量成分时需重复动词「弹」，应说「弹琴弹了一会儿」，不能说「弹琴了一会儿」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '129bcd71-d37e-4369-81ee-80399ce3f28a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟弹琴得很慢。", "corrected_sentence": "我弟弟弹琴弹得很慢。", "error_description": "补语结构错误：「弹琴弹得很慢」中需重复动词「弹」，不能说「弹琴得很慢」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '129bcd71-d37e-4369-81ee-80399ce3f28a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
