INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21860, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉就是把事情说给别人听。", "primary_collocate": null, "pronunciation": "gào su", "ipa": "kɑʊ⁵¹ su", "syllable_count": 2, "sentences": [{"text": "请你告诉我他的名字。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈告诉我明天要下雨。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有告诉老师这件事。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我告诉过你,别忘了带书。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能告诉我车站在哪儿吗?", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉大家明天考试。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这个好消息告诉了朋友。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁告诉你她今天不来?", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他告诉我,他很喜欢这里。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生告诉他要多休息。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "告诉了", "label": "体标"}, {"form": "告诉过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把事情说给别人知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fef3691-c05f-4979-b766-4af9a742d3ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "告诉", "is_correct": true, "explanation": "“告诉”表示把事情说给对方知道，“告诉我他的名字”成立。"}, {"text": "问", "is_correct": false, "explanation": "语义：“问”是询问，句子要的是把名字告诉对方，意思相反。"}, {"text": "教", "is_correct": false, "explanation": "搭配：“教”教的是知识或技能，名字不能“教”。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”是把东西交给别人，名字不是可以送出的物品。"}], "explanations": {"告诉": "“告诉”表示把事情说给对方知道，“告诉我他的名字”成立。", "问": "语义：“问”是询问，句子要的是把名字告诉对方，意思相反。", "教": "搭配：“教”教的是知识或技能，名字不能“教”。", "送": "语义：“送”是把东西交给别人，名字不是可以送出的物品。"}, "sentence_index": 0, "correct_answer": "告诉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他告诉了老师一杯酒。", "explanation": "这里应该用〈敬〉。敬酒要用“敬”；“告诉”后接的是信息内容，不能接“一杯酒”。"}, {"text": "妈妈告诉了我的画。", "explanation": "这里应该用〈称赞〉。称赞别人的作品用“称赞”；“告诉”的宾语应是信息，不能接“画”。"}, {"text": "他告诉了一句谢谢。", "explanation": "这里应该用〈说〉。说谢谢用“说”；“告诉”要接受话人和具体的内容，不能接“谢谢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "告诉", "is_correct": true, "explanation": "“告诉”表示把好消息说给朋友知道，“把这个好消息告诉了朋友”成立。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”的对象是人或成就，不能说“把好消息祝贺了朋友”。"}, {"text": "消灭", "is_correct": false, "explanation": "搭配：“消灭”用于敌人、害虫等，不能用于好消息，句意不通。"}, {"text": "骗", "is_correct": false, "explanation": "语义：“骗”是欺骗，句中是如实告诉朋友好消息，不是欺骗，句意不符。"}], "explanations": {"告诉": "“告诉”表示把好消息说给朋友知道，“把这个好消息告诉了朋友”成立。", "祝贺": "搭配：“祝贺”的对象是人或成就，不能说“把好消息祝贺了朋友”。", "消灭": "搭配：“消灭”用于敌人、害虫等，不能用于好消息，句意不通。", "骗": "语义：“骗”是欺骗，句中是如实告诉朋友好消息，不是欺骗，句意不符。"}, "sentence_index": 6, "correct_answer": "告诉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他告诉了那辆旧自行车。", "explanation": "这里应该用〈修理〉。修理东西要用“修理”；“告诉”的宾语是信息，不能接“自行车”。"}, {"text": "他告诉了那件新衣服。", "explanation": "这里应该用〈穿〉。穿衣服要用“穿”；“告诉”的宾语是信息，不能接“衣服”。"}, {"text": "她告诉了我一束花。", "explanation": "这里应该用〈送〉。把花交给别人用“送”；“告诉”后接的是信息，不能接具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天告诉着朋友这件事。", "corrected_sentence": "我昨天告诉了朋友这件事。", "error_description": "错误：“着”表示动作持续，“告诉”是一次性完成的动作，且句子说“昨天”，应用表示动作完成的“了”。正确应为“告诉了朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把这件事告诉很清楚。", "corrected_sentence": "她把这件事告诉得很清楚。", "error_description": "错误：“告诉”后漏了“得”。带状态补语时要用“得”连接，正确应为“告诉得很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
