INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21868, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人有困难，你去帮助他。", "primary_collocate": null, "pronunciation": "bāng máng", "ipa": "paŋ˥ maŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我搬家的时候，朋友来帮忙了。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "需要帮忙的话，请告诉我。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你昨天帮忙。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学有困难，我们应该去帮忙。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做饭的时候，我去厨房帮忙。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很爱帮忙，大家都喜欢他。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事太难了，请你帮忙吧。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们来帮忙，一会儿就搬完了。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要不要我帮忙？", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人需要帮忙，你快去看看。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "帮帮忙", "label": "重叠"}, {"form": "帮了忙", "label": "体标"}, {"form": "幫忙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "别人有困难时去帮助他（离合词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405dfc4a-6ee0-42e9-8dd9-f58f27602e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "帮忙", "is_correct": true, "explanation": "正确：表示朋友来给搬家的人提供帮助，与“搬家”的语境相符。"}, {"text": "上课", "is_correct": false, "explanation": "语义：上课指在学校学习，与“搬家的时候”的场景不相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验，与搬家时朋友的行动无关。"}, {"text": "罚款", "is_correct": false, "explanation": "搭配：罚款一般由执法者施行，“朋友来罚款”与搬家语境不搭配。"}], "explanations": {"帮忙": "正确：表示朋友来给搬家的人提供帮助，与“搬家”的语境相符。", "上课": "语义：上课指在学校学习，与“搬家的时候”的场景不相符。", "考试": "语义：考试是测验，与搬家时朋友的行动无关。", "罚款": "搭配：罚款一般由执法者施行，“朋友来罚款”与搬家语境不搭配。"}, "sentence_index": 0, "correct_answer": "帮忙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班找到了一个帮忙。", "explanation": "这里应用〈帮手〉。“帮忙”是动词，不能表示能帮忙的人，应说〈帮手〉。"}, {"text": "这个问题很帮忙，大家都没听懂。", "explanation": "这里应用〈难〉。“帮忙”不能形容问题，说问题难应用〈难〉。"}, {"text": "他在饭店里是个帮忙，一直很忙。", "explanation": "这里应用〈服务员〉。“帮忙”是动词，不能表示职业身份，应说“服务员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "帮忙", "is_correct": true, "explanation": "正确：请求别人提供帮助，与“这件事太难了”的语境相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是休闲活动，与“这件事太难了”的请求语境不符。"}, {"text": "上学", "is_correct": false, "explanation": "语义：上学指去学校学习，与“请你……吧”的求助语境不符。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“请你游泳吧”与“这件事太难了”的语境不搭配，无法表示求助。"}], "explanations": {"帮忙": "正确：请求别人提供帮助，与“这件事太难了”的语境相符。", "散步": "语义：散步是休闲活动，与“这件事太难了”的请求语境不符。", "上学": "语义：上学指去学校学习，与“请你……吧”的求助语境不符。", "游泳": "搭配：“请你游泳吧”与“这件事太难了”的语境不搭配，无法表示求助。"}, "sentence_index": 6, "correct_answer": "帮忙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜很帮忙，我每天都想吃。", "explanation": "这里应用〈好吃〉。“帮忙”不能形容食物的味道，说味道好应用〈好吃〉。"}, {"text": "他的帮忙在银行上班，每天都很忙。", "explanation": "这里应用〈职员〉。“帮忙”不能表示职业身份，说在银行工作的人应用〈职员〉。"}, {"text": "这家店的帮忙在门口卖菜，我经常来买东西。", "explanation": "这里应用〈店员〉。“帮忙”是动词，不能指做事的人，也不能作主语卖菜，应说“店员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天去帮忙我吧。", "corrected_sentence": "我们明天去帮忙吧。", "error_description": "离合错误：“帮忙”是离合词，后面不能直接带宾语“我”。正确形式：我们明天去帮忙吧。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们快去帮忙他吧。", "corrected_sentence": "他们快去帮忙吧。", "error_description": "离合错误：“帮忙”是离合词，后面不能直接带宾语“他”。正确形式：他们快去帮忙吧。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21872, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "记得", "is_correct": true, "explanation": "正确：“记得”与“忘记”构成反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}, {"text": "旅行", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}], "correct_answer": "记得", "explanations": {"记得": "正确：“记得”与“忘记”构成反义关系。", "思考": "与“忘记”无反义关系，二者语义无对立。", "旅行": "与“忘记”无反义关系，二者语义无对立。", "唱歌": "与“忘记”无反义关系，二者语义无对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21872, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "记得", "is_correct": true, "explanation": "正确：“记得”与“忘记”构成反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}, {"text": "写字", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}, {"text": "吃饭", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}], "correct_answer": "记得", "explanations": {"记得": "正确：“记得”与“忘记”构成反义关系。", "游泳": "与“忘记”无反义关系，二者语义无对立。", "写字": "与“忘记”无反义关系，二者语义无对立。", "吃饭": "与“忘记”无反义关系，二者语义无对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21872, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不记得了。", "primary_collocate": null, "pronunciation": "wàng jì", "ipa": "wɑŋ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "我忘记今天是妈妈的生日。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对不起，我忘记带钱包了。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别忘记带伞，下午会下雨。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他忘记关灯就出门了。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘记了你昨天说的话。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的名字我忘记了，能再说一次吗？", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她忘记锁门，家里进了小偷。", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘记把作业放在哪儿了。", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要忘记明天的会。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一着急，就忘记了该说什么。", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忘记了", "label": "体标"}, {"form": "忘记过", "label": "体标"}], "register": "中性", "sense_fingerprint": "没有记得要做的事或该记的事，不记得了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e176a57-3f09-4b1b-b4b5-6e20e7f24a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忘记", "is_correct": true, "explanation": "正确：没有记得“今天是生日”这件事，可以填入空格。"}, {"text": "举办", "is_correct": false, "explanation": "语义：“今天是妈妈的生日”不能被举办，句子语义不通。"}, {"text": "进行", "is_correct": false, "explanation": "搭配：“进行”后接动作性名词，“今天是妈妈的生日”不是动作。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“今天是妈妈的生日”不能被唱，句子语义不通。"}], "explanations": {"忘记": "正确：没有记得“今天是生日”这件事，可以填入空格。", "举办": "语义：“今天是妈妈的生日”不能被举办，句子语义不通。", "进行": "搭配：“进行”后接动作性名词，“今天是妈妈的生日”不是动作。", "唱": "语义：“今天是妈妈的生日”不能被唱，句子语义不通。"}, "sentence_index": 0, "correct_answer": "忘记"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的左手忘记了，拿不住东西。", "explanation": "这里应该用〈麻木〉。“忘记”指不记得，主语应是人，不能说手“忘记”了。"}, {"text": "他的信心忘记了，所以不想再努力。", "explanation": "这里应该用〈失去〉。“忘记”指没记得，不用于信心消失。"}, {"text": "我的钥匙忘记了，只好请人开门。", "explanation": "这里应该用〈丢〉。“忘记”指没记得要做的事，不用于东西遗失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忘记", "is_correct": true, "explanation": "正确：没记得要锁门，可以填入空格。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱锁门”说不通，句子语义不通。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”的对象是纸类等薄物，不能撕“锁门”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：锁门不能被吃，句子语义不通。"}], "explanations": {"忘记": "正确：没记得要锁门，可以填入空格。", "唱": "语义：“唱锁门”说不通，句子语义不通。", "撕": "搭配：“撕”的对象是纸类等薄物，不能撕“锁门”。", "吃": "语义：锁门不能被吃，句子语义不通。"}, "sentence_index": 6, "correct_answer": "忘记"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杯子忘记了，我们只好用碗。", "explanation": "这里应该用〈打碎〉。“忘记”指不记得，不能用于杯子破碎。"}, {"text": "他的护照忘记了，只好回国重办。", "explanation": "这里应该用〈丢〉。“忘记”不用于证件遗失。"}, {"text": "他的爱好忘记了，整天不开心。", "explanation": "这里应该用〈失去〉。“忘记”指没记得，不用于爱好消失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天忘记着锁门了。", "corrected_sentence": "我昨天忘记锁门了。", "error_description": "体标错误：“忘记”后接动作时不用“着”，应说「忘记锁门了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这件事忘记。", "corrected_sentence": "我把这件事忘记了。", "error_description": "把字句：动词后要带“了”等成分，应说「我把这件事忘记了」，不能说「我把这件事忘记」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
