INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21875, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "唱歌就是用嘴巴发出好听的声音。", "primary_collocate": null, "pronunciation": "chàng", "ipa": "tʂʰɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "小鸟在树上唱，声音很好听。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱得很好听，大家都喜欢。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们站起来唱一首歌。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟高兴地唱着儿歌。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会唱这首中文歌吗？", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在朋友的生日会上唱过歌。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上洗澡时都唱几句。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐响起来，孩子们张开嘴巴唱。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请你唱一首，好不好？", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿在台上唱了一首歌。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "唱了", "label": "完成体"}, {"form": "唱着", "label": "持续体"}, {"form": "唱过", "label": "经历体"}, {"form": "唱唱", "label": "重叠"}, {"form": "唱歌", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用嘴发出好听的歌声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02d5ca48-c41f-404e-b8aa-feb7d9f3a2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21875, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "唱", "is_correct": true, "explanation": "正确答案：唱（第四声），意思是用嘴发出好听的歌声。"}, {"text": "长", "is_correct": false, "explanation": "cháng（第二声）与 chàng（第四声）声调不同，意思是长。"}, {"text": "场", "is_correct": false, "explanation": "chǎng（第三声）与 chàng（第四声）声调不同，意思是场地、场合。"}, {"text": "上", "is_correct": false, "explanation": "shàng 与 chàng 声母不同（sh 与 ch），意思是上。"}], "explanations": {"唱": "正确答案：唱（第四声），意思是用嘴发出好听的歌声。", "长": "cháng（第二声）与 chàng（第四声）声调不同，意思是长。", "场": "chǎng（第三声）与 chàng（第四声）声调不同，意思是场地、场合。", "上": "shàng 与 chàng 声母不同（sh 与 ch），意思是上。"}, "sentence_index": null, "correct_answer": "唱"}, "level_3": {"options": [{"text": "唱", "is_correct": true, "explanation": "正确：“唱”表示用嘴发出好听的声音，符合“声音很好听”的语境。"}, {"text": "吵", "is_correct": false, "explanation": "语义：“吵”指声音嘈杂，与“声音很好听”相矛盾。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”与“声音很好听”的描述相矛盾，句意不通。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”不能发出声音，与“声音很好听”搭配不通。"}], "explanations": {"唱": "正确：“唱”表示用嘴发出好听的声音，符合“声音很好听”的语境。", "吵": "语义：“吵”指声音嘈杂，与“声音很好听”相矛盾。", "哭": "语义：“哭”与“声音很好听”的描述相矛盾，句意不通。", "跳": "搭配：“跳”不能发出声音，与“声音很好听”搭配不通。"}, "sentence_index": 0, "correct_answer": "唱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟弟高兴地唱着玩具。", "explanation": "这里应该用〈摆弄〉。“唱”的对象只能是歌曲，不能用来表示摆弄玩具的动作。"}, {"text": "他在会议上唱了一页笔记，一直低着头。", "explanation": "这里应该用〈记〉。“唱”指按旋律演唱，不能用来表示记笔记，这里误用了。"}, {"text": "我在路边唱着石头，一块一块地装进了口袋。", "explanation": "这里应该用〈捡〉。“唱”的对象只能是歌曲，不能用来表示捡石头的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱", "is_correct": true, "explanation": "正确：“唱几句”表示唱几句歌词，符合“洗澡时”的日常语境。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不与“几句”搭配，“洗几句”说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不与“几句”搭配，“吃几句”说不通。"}, {"text": "扫", "is_correct": false, "explanation": "语义：“扫”指清扫，与“几句”所指的说或唱无关，句意不通。"}], "explanations": {"唱": "正确：“唱几句”表示唱几句歌词，符合“洗澡时”的日常语境。", "洗": "搭配：“洗”不与“几句”搭配，“洗几句”说不通。", "吃": "搭配：“吃”不与“几句”搭配，“吃几句”说不通。", "扫": "语义：“扫”指清扫，与“几句”所指的说或唱无关，句意不通。"}, "sentence_index": 6, "correct_answer": "唱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在讲台上唱了一段话。", "explanation": "这里应该用〈说〉。“唱”指按旋律演唱，不能用于一般的说话。"}, {"text": "这首歌唱干净了黑板。", "explanation": "这里应该用〈擦〉。“唱”只能用于歌曲，不能用来表示擦黑板，这里误用了。"}, {"text": "他在台上唱了一下午的讲座。", "explanation": "这里应该用〈作〉。“唱”只能用于歌曲，不能用来表示作讲座这种活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她终于唱了完这首歌。", "corrected_sentence": "她终于唱完了这首歌。", "error_description": "补语位置错误：结果补语“完”要紧跟动词，应说“唱完了”，不能说“唱了完”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们唱了过一首新歌，个个都很开心。", "corrected_sentence": "孩子们唱过一首新歌，个个都很开心。", "error_description": "体标错误：经历体“过”直接接在“唱”后，不能再加“了”。应说“唱过”，不能说“唱了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
