INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21886, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "线是细细长长的东西。", "primary_collocate": null, "pronunciation": "xiàn", "ipa": "ɕjɛn⁵¹", "syllable_count": 1, "sentences": [{"text": "我的衣服上有一根线。", "target_word": "线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这根线很长，也很细。", "target_word": "线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶用针和线补衣服。", "target_word": "线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小猫在玩一团线。", "target_word": "线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他剪断了手里的线。", "target_word": "线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请帮我把线穿进针里。", "target_word": "线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风筝飞得很高，线也很长。", "target_word": "线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上放着一卷线。", "target_word": "线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条线是用棉做的。", "target_word": "线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "线太细了，我看不清楚。", "target_word": "线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "团", "label": "量词"}, {"form": "線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "缝纫等用的细长的线状物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac50366-f88b-44b8-ba28-9c1798834e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21886, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "线", "is_correct": true, "explanation": "线 xiàn，指细细长长的线状物，正确。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是先后的“先”。"}, {"text": "显", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是“显示”。"}, {"text": "见", "is_correct": false, "explanation": "jiàn 与 xiàn 声母不同（j 与 x），意思是“看见”。"}, {"text": "向", "is_correct": false, "explanation": "xiàng 与 xiàn 韵母不同（-iang 与 -ian），意思是“方向”。"}], "explanations": {"线": "线 xiàn，指细细长长的线状物，正确。", "先": "xiān（第一声）与 xiàn（第四声）声调不同，意思是先后的“先”。", "显": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是“显示”。", "见": "jiàn 与 xiàn 声母不同（j 与 x），意思是“看见”。", "向": "xiàng 与 xiàn 韵母不同（-iang 与 -ian），意思是“方向”。"}, "sentence_index": null, "correct_answer": "线"}, "level_3": {"options": [{"text": "线", "is_correct": true, "explanation": "正确。“一根线”指细长的线，符合句意。"}, {"text": "扣子", "is_correct": false, "explanation": "搭配：“扣子”的量词是“颗”，不说“一根扣子”。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不会挂在衣服上，与“衣服上有”的句意不合。"}, {"text": "纸", "is_correct": false, "explanation": "搭配：“纸”的量词是“张”，不说“一根纸”。"}], "explanations": {"线": "正确。“一根线”指细长的线，符合句意。", "扣子": "搭配：“扣子”的量词是“颗”，不说“一根扣子”。", "太阳": "语义：太阳不会挂在衣服上，与“衣服上有”的句意不合。", "纸": "搭配：“纸”的量词是“张”，不说“一根纸”。"}, "sentence_index": 0, "correct_answer": "线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条地铁线每天都很挤。", "explanation": "这里的线指地铁路线，是另一个意思，不是“细细长长的东西”。"}, {"text": "姐姐买了一只线。", "explanation": "量词用错。「只」多用于动物、手等具体事物，线不用「只」。"}, {"text": "孩子们在操场上跳线。", "explanation": "这里应该用〈绳〉。跳的是绳，线太细，不能说“跳线”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21886, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "线", "is_correct": true, "explanation": "线 xiàn，指细细长长的线状物，正确。"}, {"text": "闲", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是“空闲”。"}, {"text": "咸", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是“咸味”。"}, {"text": "鲜", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是“新鲜”。"}, {"text": "建", "is_correct": false, "explanation": "jiàn 与 xiàn 声母不同（j 与 x），意思是“建设”。"}], "explanations": {"线": "线 xiàn，指细细长长的线状物，正确。", "闲": "xián（第二声）与 xiàn（第四声）声调不同，意思是“空闲”。", "咸": "xián（第二声）与 xiàn（第四声）声调不同，意思是“咸味”。", "鲜": "xiān（第一声）与 xiàn（第四声）声调不同，意思是“新鲜”。", "建": "jiàn 与 xiàn 声母不同（j 与 x），意思是“建设”。"}, "sentence_index": null, "correct_answer": "线"}, "level_3": {"options": [{"text": "线", "is_correct": true, "explanation": "正确。风筝上的线随风筝升高而拉长，符合句意。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不是风筝上的连接物，与“风筝飞得很高”无关。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：形容眼睛不说“很长”，与句子搭配不通。"}, {"text": "纽扣", "is_correct": false, "explanation": "语义：纽扣很小，说不上“很长”，无法与风筝线并列。"}], "explanations": {"线": "正确。风筝上的线随风筝升高而拉长，符合句意。", "树": "语义：树不是风筝上的连接物，与“风筝飞得很高”无关。", "眼睛": "搭配：形容眼睛不说“很长”，与句子搭配不通。", "纽扣": "语义：纽扣很小，说不上“很长”，无法与风筝线并列。"}, "sentence_index": 6, "correct_answer": "线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她腰间系着一条宽线子。", "explanation": "这里应该用〈带〉。线是细细长长的，不能说“宽线”；宽的东西叫“带”。"}, {"text": "拔河比赛用的线很结实。", "explanation": "这里应该用〈绳〉。拔河要用粗绳，线太细，不能用来拔河。"}, {"text": "奶奶买了一头线。", "explanation": "量词用错。“头”用于牛、猪等大型牲畜，线不用“头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "抽屉里有一个线，颜色是白的。", "corrected_sentence": "抽屉里有一团线，颜色是白的。", "error_description": "错误：“线”的量词用错。“个”不能用于线，应改为“团”（或“根”“卷”）。改为“一团线”即正确。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从抽屉里拿出了一根的线。", "corrected_sentence": "他从抽屉里拿出了一根线。", "error_description": "错误：数量短语后多加了“的”。“一根”后直接接名词，应说“一根线”，不说“一根的线”；原因：“一根线”已是完整的数量名结构，无需“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9898a07c-f445-423d-a684-27958610459f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
