INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21890, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "觉得就是心里想一个事情，或者有了一种感觉。", "primary_collocate": null, "pronunciation": "jué de", "ipa": "tɕɥɛ˧˥ tə", "syllable_count": 2, "sentences": [{"text": "我觉得今天的天气很好。", "target_word": "觉得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你觉得这件衣服怎么样？", "target_word": "觉得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他觉得汉字很难写。", "target_word": "觉得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不觉得累，还想再走走。", "target_word": "觉得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃了很多药，她觉得好一点了。", "target_word": "觉得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都觉得老师讲得很清楚。", "target_word": "觉得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈觉得我太瘦，让我多吃饭。", "target_word": "觉得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人在家，我觉得有点儿冷清。", "target_word": "觉得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你觉得我们坐什么车去好？", "target_word": "觉得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没觉得这个问题有多难。", "target_word": "觉得", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不觉得", "label": "否定形式"}, {"form": "没觉得", "label": "否定形式"}], "register": "口语", "sense_fingerprint": "心里有某种看法或感受（我觉得……）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ee3da4-4c99-4c2d-aaed-c51fb6a3dd04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "觉得", "is_correct": true, "explanation": "正确。“我觉得……”表示个人的看法或感受，与句意相符。"}, {"text": "宣布", "is_correct": false, "explanation": "语域：“宣布”是正式公开地发布，与表达个人感受的口语语境不符。"}, {"text": "后悔", "is_correct": false, "explanation": "语义：“后悔”表示对已做的事感到不满，不能用来表达对天气的看法。"}, {"text": "嫌", "is_correct": false, "explanation": "语义：“嫌”表示厌恶或不满，与“天气很好”的积极评价矛盾。"}], "explanations": {"觉得": "正确。“我觉得……”表示个人的看法或感受，与句意相符。", "宣布": "语域：“宣布”是正式公开地发布，与表达个人感受的口语语境不符。", "后悔": "语义：“后悔”表示对已做的事感到不满，不能用来表达对天气的看法。", "嫌": "语义：“嫌”表示厌恶或不满，与“天气很好”的积极评价矛盾。"}, "sentence_index": 0, "correct_answer": "觉得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他翻遍书架，终于觉得了一本旧字典。", "explanation": "这里应该用〈发现〉。觉得表示心里的看法或感受，不表示找到具体的东西；找到东西要用发现。"}, {"text": "我在窗口觉得了月亮。", "explanation": "这里应该用〈看见〉。觉得表示心里的感受，不能表示用眼睛看到具体事物。"}, {"text": "老师让我们把黑板上的题觉得下来。", "explanation": "这里应该用〈抄〉。觉得表示心里的感受，不表示把内容写下来；把黑板上的题抄下来要用抄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "觉得", "is_correct": true, "explanation": "正确。“妈妈觉得我太瘦”表示妈妈的看法，与后面让我多吃饭的关心相符。"}, {"text": "批准", "is_correct": false, "explanation": "配价：“批准”后面要接具体事项作宾语，不能直接接“我太瘦”这样的小句。"}, {"text": "尊敬", "is_correct": false, "explanation": "语义：“尊敬”表示敬重，与妈妈关心孩子身体、让我多吃饭的语境不符。"}, {"text": "统计", "is_correct": false, "explanation": "语义：“统计”指按数字计算，句子说的是母亲的看法，不是计数。"}], "explanations": {"觉得": "正确。“妈妈觉得我太瘦”表示妈妈的看法，与后面让我多吃饭的关心相符。", "批准": "配价：“批准”后面要接具体事项作宾语，不能直接接“我太瘦”这样的小句。", "尊敬": "语义：“尊敬”表示敬重，与妈妈关心孩子身体、让我多吃饭的语境不符。", "统计": "语义：“统计”指按数字计算，句子说的是母亲的看法，不是计数。"}, "sentence_index": 6, "correct_answer": "觉得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天觉得了一封信，很高兴。", "explanation": "这里应该用〈收到〉。觉得表示心里的感受或看法，不表示接到信件；收到信要用收到。"}, {"text": "事情的结果谁也没觉得到。", "explanation": "这里应该用〈预料〉。觉得表示心里的感受，不能表示事先估计到结果；事先估计要用预料。"}, {"text": "他觉得这件事的真相。", "explanation": "这里应该用〈知道〉。觉得表示看法或感受，不表示已经掌握某个信息；掌握信息要用知道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我觉得了这个方案不太合适。", "corrected_sentence": "我觉得这个方案不太合适。", "error_description": "助词错误：“觉得”是心理动词，后面不能加“了”，应说“我觉得这个方案不太合适”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把觉得这份报告写得不错。", "corrected_sentence": "我觉得这份报告写得不错。", "error_description": "助词错误：「把」字句中不能以心理动词「觉得」作谓语，应说「我觉得这份报告写得不错。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
