INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21894, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "麻烦", "is_correct": true, "explanation": "“麻烦”与“方便”相对，指做事费事、不省力。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”与“方便”没有反义关系，指人的智力高。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”指没有污物，与“方便”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”指心情愉快，与“方便”没有反义关系。"}], "correct_answer": "麻烦", "explanations": {"麻烦": "“麻烦”与“方便”相对，指做事费事、不省力。", "聪明": "“聪明”与“方便”没有反义关系，指人的智力高。", "干净": "“干净”指没有污物，与“方便”没有反义关系。", "高兴": "“高兴”指心情愉快，与“方便”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21894, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事情很容易，不麻烦。", "primary_collocate": null, "pronunciation": "fāng biàn", "ipa": "faŋ˥ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "住在地铁站旁边很方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买东西很方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机用起来很方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在方便接电话吗？", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近有超市，买菜很方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐出租车去机场比较方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路不太方便，我们走那条吧。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手机付钱真方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小包带着很方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校离家近，上学很方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "方便面", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事省力省事，条件合适，不麻烦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be5ee50c-f9af-43f9-b71d-60fc13a41298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方便", "is_correct": true, "explanation": "“方便”形容住的地方交通便利、省事，与“地铁站旁边”相符。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来说住的地方。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描写人或动物的体形，不能用来形容位置。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”是人的情绪，不能用来形容住在某处的情况。"}], "explanations": {"方便": "“方便”形容住的地方交通便利、省事，与“地铁站旁边”相符。", "聪明": "语义：“聪明”形容人的智力，不能用来说住的地方。", "胖": "体貌：“胖”描写人或动物的体形，不能用来形容位置。", "悲伤": "语义：“悲伤”是人的情绪，不能用来形容住在某处的情况。"}, "sentence_index": 0, "correct_answer": "方便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很方便，只要十块钱。", "explanation": "这里应该用〈便宜〉。方便说做事省事，不用来说价格，价格低要说便宜。"}, {"text": "他的身体很方便。", "explanation": "这里应该用〈健康〉。方便指做事省事，形容身体的状况要说健康。"}, {"text": "他的成绩很方便。", "explanation": "这里应该用〈优秀〉。方便指做事省事，成绩的好坏要说优秀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方便", "is_correct": true, "explanation": "“方便”表示这条路走起来不省事，与后半句“我们走那条吧”相符。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人说话风趣，不能用来形容道路。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描写人或动物的身形，不能用来形容道路。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的待人态度，不能用来形容道路。"}], "explanations": {"方便": "“方便”表示这条路走起来不省事，与后半句“我们走那条吧”相符。", "幽默": "语义：“幽默”形容人说话风趣，不能用来形容道路。", "瘦": "体貌：“瘦”描写人或动物的身形，不能用来形容道路。", "热情": "语义：“热情”形容人的待人态度，不能用来形容道路。"}, "sentence_index": 6, "correct_answer": "方便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的想法很方便。", "explanation": "这里应该用〈灵活〉。方便指做事省力省事，想法的变通要说灵活。"}, {"text": "这本书的内容很方便。", "explanation": "这里应该用〈丰富〉。方便指做事省事，内容的多少要说丰富。"}, {"text": "这种颜色很方便。", "explanation": "这里应该用〈好看〉。方便指做事省事，颜色的美丑要说好看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店晚上开门，对上班族被方便。", "corrected_sentence": "这家店晚上开门，对上班族很方便。", "error_description": "错误在于“方便”前用了“被”。“方便”是形容词，表示状态，不能用“被”；应说“对上班族很方便”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台新电脑用起来没方便。", "corrected_sentence": "这台新电脑用起来很方便。", "error_description": "错误在于用“没”否定形容词。“没方便”是错误的，形容词前不能直接用“没”；表示肯定时应说“很方便”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
