INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人或动物头部两侧用来听声音的器官。", "primary_collocate": null, "pronunciation": "ěr duo", "ipa": "ɚ˨˩˦ tuo", "syllable_count": 2, "sentences": [{"text": "猫的耳朵很小。", "target_word": "耳朵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他有两只大耳朵。", "target_word": "耳朵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我用耳朵听，不用眼睛看。", "target_word": "耳朵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "外面太吵，我把耳朵堵上了。", "target_word": "耳朵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音太大会伤害耳朵。", "target_word": "耳朵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗澡时水进了耳朵，我歪着头跳了几下。", "target_word": "耳朵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞的时候，我的耳朵有点儿难受，像堵住了一样。", "target_word": "耳朵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈轻轻地在我的耳朵旁边说了一句话。", "target_word": "耳朵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听不见的人可以用手语，不用耳朵也能交流。", "target_word": "耳朵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友的耳朵上戴着一对小耳环。", "target_word": "耳朵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只耳朵", "label": "量词"}, {"form": "一对耳朵", "label": "量词"}, {"form": "耳朵眼", "label": "复合"}], "register": "中性", "sense_fingerprint": "耳朵：用来听声音的身体部位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba7f1315-ce80-48ee-ae24-9d3dc8e5ede7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耳朵", "is_correct": true, "explanation": "正确：猫的耳朵很小，描述的是猫身体的部位和大小。"}, {"text": "翅膀", "is_correct": false, "explanation": "语义：猫没有翅膀，“猫的翅膀”与事实不符，句子不成立。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“很小”说的是大小，不能用来修饰“颜色”。"}, {"text": "轮子", "is_correct": false, "explanation": "语义：猫身上没有轮子，“猫的轮子很小”不符合常识。"}], "explanations": {"耳朵": "正确：猫的耳朵很小，描述的是猫身体的部位和大小。", "翅膀": "语义：猫没有翅膀，“猫的翅膀”与事实不符，句子不成立。", "颜色": "搭配：“很小”说的是大小，不能用来修饰“颜色”。", "轮子": "语义：猫身上没有轮子，“猫的轮子很小”不符合常识。"}, "sentence_index": 0, "correct_answer": "耳朵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用耳朵说话。", "explanation": "这里应该用〈嘴巴〉。说话要用嘴巴，耳朵只用来听。"}, {"text": "我用耳朵摸东西。", "explanation": "这里应该用〈手〉。摸东西要用手，耳朵只负责听声音。"}, {"text": "我用耳朵尝味道。", "explanation": "这里应该用〈舌头〉。尝味道要用舌头，耳朵不能用来尝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f53395cd-971c-4e30-814f-9bf16cb128ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耳朵", "is_correct": true, "explanation": "正确：飞机起飞时耳朵会难受，“像堵住了一样”正说的是耳朵的感觉。"}, {"text": "手指", "is_correct": false, "explanation": "语义：手指不会因为飞机起飞而“像堵住了一样”，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“难受”用于身体的感觉，“味道有点儿难受”搭配不当。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有身体感觉，“我的桌子有点儿难受”与前文不符。"}], "explanations": {"耳朵": "正确：飞机起飞时耳朵会难受，“像堵住了一样”正说的是耳朵的感觉。", "手指": "语义：手指不会因为飞机起飞而“像堵住了一样”，句意不通。", "味道": "搭配：“难受”用于身体的感觉，“味道有点儿难受”搭配不当。", "桌子": "语义：桌子没有身体感觉，“我的桌子有点儿难受”与前文不符。"}, "sentence_index": 6, "correct_answer": "耳朵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小朋友有两张耳朵。", "explanation": "这里应该用〈只〉。“张”用于平面的东西，耳朵不用“张”。"}, {"text": "小朋友有两片耳朵。", "explanation": "这里应该用〈只〉。“片”用于薄片状的东西，耳朵不用“片”。"}, {"text": "小朋友有两块耳朵。", "explanation": "这里应该用〈只〉。“块”用于块状的东西，耳朵不能用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f53395cd-971c-4e30-814f-9bf16cb128ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的两根耳朵都很灵。", "corrected_sentence": "我的两只耳朵都很灵。", "error_description": "量词错误：错误形式为“两根耳朵”，正确形式为“两只耳朵”。耳朵的量词是“只”，“根”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f53395cd-971c-4e30-814f-9bf16cb128ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的耳朵疼起去了，我去看看医生。", "corrected_sentence": "我的耳朵疼起来了，我去看看医生。", "error_description": "趋向补语错误：错误形式为“疼起去了”，正确形式为“疼起来了”。表示疼痛开始出现，要用“来”，不用“去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f53395cd-971c-4e30-814f-9bf16cb128ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
