INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21908, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西在什么地方，就是它待的那个点。", "primary_collocate": null, "pronunciation": "wèi zhì", "ipa": "weɪ˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这个位置没有人坐，你坐吧。", "target_word": "位置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你家的位置。", "target_word": "位置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机放在哪个位置了？你能帮我找找吗？", "target_word": "位置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在教室里的位置在最后一排。", "target_word": "位置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上，学校的位置很清楚。", "target_word": "位置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们换一下位置，好吗？我看不见黑板。", "target_word": "位置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，电影院在哪个位置？", "target_word": "位置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把椅子放回原来的位置。", "target_word": "位置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的位置很好，离地铁站很近。", "target_word": "位置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影开始了，他还在找自己的位置。", "target_word": "位置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个位置", "label": "量词"}, {"form": "位置图", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：人或物所在的地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb282ec0-1d20-4008-9f52-5b1110039fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21908, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "位置", "is_correct": true, "explanation": "位置：正确答案，指东西所在的地方。"}, {"text": "卫视", "is_correct": false, "explanation": "卫视（wèishì）与“位置”（wèizhì）第二个音节声母不同（sh 与 zh），意思是卫星电视台。"}, {"text": "未知", "is_correct": false, "explanation": "未知（wèizhī）与“位置”第二个音节声调不同（第一声与第四声），意思是不知道。"}, {"text": "为止", "is_correct": false, "explanation": "为止（wéizhǐ）与“位置”两个音节的声调都不同，意思是到……结束。"}, {"text": "内置", "is_correct": false, "explanation": "内置（nèizhì）与“位置”第一个音节声母不同（n 与 w），意思是装在内部。"}], "explanations": {"位置": "位置：正确答案，指东西所在的地方。", "卫视": "卫视（wèishì）与“位置”（wèizhì）第二个音节声母不同（sh 与 zh），意思是卫星电视台。", "未知": "未知（wèizhī）与“位置”第二个音节声调不同（第一声与第四声），意思是不知道。", "为止": "为止（wéizhǐ）与“位置”两个音节的声调都不同，意思是到……结束。", "内置": "内置（nèizhì）与“位置”第一个音节声母不同（n 与 w），意思是装在内部。"}, "sentence_index": null, "correct_answer": "位置"}, "level_3": {"options": [{"text": "位置", "is_correct": true, "explanation": "位置：指东西所在的地方，与“这个……没有人坐，你坐吧”相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”不是地点，不能被人坐，句意不通。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙不能被人坐，“没有人坐”的句意不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是地点，“没有人坐”无从谈起。"}], "explanations": {"位置": "位置：指东西所在的地方，与“这个……没有人坐，你坐吧”相符。", "价格": "语义：“价格”不是地点，不能被人坐，句意不通。", "墙": "语义：墙不能被人坐，“没有人坐”的句意不通。", "时间": "语义：“时间”不是地点，“没有人坐”无从谈起。"}, "sentence_index": 0, "correct_answer": "位置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们约定的位置是下午三点。", "explanation": "这里应该用〈时间〉。“位置”指空间中的地点，不指时刻，约定的时候要说时间。"}, {"text": "他的位置很好听。", "explanation": "这里应该用〈名字〉。“位置”指地点或岗位，不能用来形容好听，说人的称呼应用名字。"}, {"text": "他的位置很开朗。", "explanation": "这里应该用〈性格〉。“位置”指地点或岗位，不指性情，形容人的性格开朗应说性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "位置", "is_correct": true, "explanation": "位置：指人或物所在的地点，与“电影院在哪个……”的问法相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是地点，不能问电影院在哪个颜色。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是地点，不能问电影院在哪个声音。"}, {"text": "价钱", "is_correct": false, "explanation": "语义：“价钱”不是地点，不能问电影院在哪个价钱。"}], "explanations": {"位置": "位置：指人或物所在的地点，与“电影院在哪个……”的问法相符。", "颜色": "语义：“颜色”不是地点，不能问电影院在哪个颜色。", "声音": "语义：“声音”不是地点，不能问电影院在哪个声音。", "价钱": "语义：“价钱”不是地点，不能问电影院在哪个价钱。"}, "sentence_index": 6, "correct_answer": "位置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的位置很咸。", "explanation": "这里应该用〈味道〉。“位置”指地点或岗位，不指咸淡，形容咸淡的应说味道。"}, {"text": "这个乐器的位置很好听。", "explanation": "这里应该用〈声音〉。“位置”指地点或岗位，不能用来形容好听，形容乐器的音色应说声音。"}, {"text": "我们之间的位置很深。", "explanation": "这里应该用〈感情〉。“位置”指地点或岗位，不指情感的深浅，说关系深厚应用感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们换了一个离门口近位置。", "corrected_sentence": "我们换了一个离门口近的位置。", "error_description": "“离门口近”修饰“位置”，中间要用“的”连接，应说“离门口近的位置”，不能说“离门口近位置”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要为客人安排好了位置。", "corrected_sentence": "我们要为客人安排好位置。", "error_description": "“要”表示将来的打算，“安排好”之后又加“了”表示已经完成，前后矛盾。应说“我们要为客人安排好位置”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21910, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗糙", "is_correct": true, "explanation": "粗糙：与“精细”构成反义，指做工不细致，与“工作很精细”相反。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：形容场面喧嚷，与“精细”不构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线或颜色，与“精细”不构成反义。"}, {"text": "寒冷", "is_correct": false, "explanation": "寒冷：形容温度，与“精细”不构成反义。"}], "correct_answer": "粗糙", "explanations": {"粗糙": "粗糙：与“精细”构成反义，指做工不细致，与“工作很精细”相反。", "热闹": "热闹：形容场面喧嚷，与“精细”不构成反义。", "明亮": "明亮：形容光线或颜色，与“精细”不构成反义。", "寒冷": "寒冷：形容温度，与“精细”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
