INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21910, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很仔细，不粗糙。", "primary_collocate": null, "pronunciation": "jīng xì", "ipa": "tɕiŋ⁵⁵ ɕi⁵¹", "syllable_count": 2, "sentences": [{"text": "他做事很精细，从来不出错。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生检查得很精细。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他算账非常精细，一分钱都不差。", "target_word": "精细", "complexity_tier": "T3", "furigana": "tā suàn zhàng fēicháng jīngxì, yī fēn qián dōu bú chà", "sentence_source": "generated"}, {"text": "她的工作很精细，客人都很满意。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次检查不够精细，漏掉了几个问题。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李打扫得很精细，连窗角都擦干净了。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求大家把账目记得精细一点。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对每个数字都核对得很精细。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂对产品的检查非常精细。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心思精细，别人没看到的她都发现了。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精細", "label": "繁体"}, {"form": "精细化", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事仔细、不粗糙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15509b16-687f-4575-9b2c-b1c6ed693810') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精细", "is_correct": true, "explanation": "精细：形容做事仔细、不出错，与“从来不出错”相符。"}, {"text": "马虎", "is_correct": false, "explanation": "语义：“马虎”形容做事不认真，与“从来不出错”相矛盾。"}, {"text": "草率", "is_correct": false, "explanation": "语义：“草率”形容做事随便，与“从来不出错”相矛盾。"}, {"text": "懒散", "is_correct": false, "explanation": "搭配：“懒散”形容人的作风，与“做事……从来不出错”的做事态度不搭。"}], "explanations": {"精细": "精细：形容做事仔细、不出错，与“从来不出错”相符。", "马虎": "语义：“马虎”形容做事不认真，与“从来不出错”相矛盾。", "草率": "语义：“草率”形容做事随便，与“从来不出错”相矛盾。", "懒散": "搭配：“懒散”形容人的作风，与“做事……从来不出错”的做事态度不搭。"}, "sentence_index": 0, "correct_answer": "精细"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个西瓜很精细。", "explanation": "这里应该用〈甜〉。精细形容做事仔细，西瓜的味道要用“甜”。"}, {"text": "这只鸟的叫声很精细。", "explanation": "这里应该用〈清脆〉。精细形容做事仔细，声音清亮要用“清脆”。"}, {"text": "这场雨下得很精细。", "explanation": "这里应该用〈细〉。精细形容做事仔细，形容雨点细密要用“细”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精细", "is_correct": true, "explanation": "精细：要求把账目记得仔细，与经理的要求相符。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：“慷慨”形容待人大方，与记账的仔细程度无关。"}, {"text": "大胆", "is_correct": false, "explanation": "语义：“大胆”形容勇敢敢做，不能说把账目记得大胆一点。"}, {"text": "潦草", "is_correct": false, "explanation": "搭配：“潦草”形容字迹随便，与经理要求的记账方式相反。"}], "explanations": {"精细": "精细：要求把账目记得仔细，与经理的要求相符。", "慷慨": "语义：“慷慨”形容待人大方，与记账的仔细程度无关。", "大胆": "语义：“大胆”形容勇敢敢做，不能说把账目记得大胆一点。", "潦草": "搭配：“潦草”形容字迹随便，与经理要求的记账方式相反。"}, "sentence_index": 6, "correct_answer": "精细"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人今天很精细。", "explanation": "这里应该用〈精神〉。精细形容做事仔细，形容人的气色和状态要用“精神”。"}, {"text": "这台机器的声音很精细。", "explanation": "这里应该用〈响亮〉。精细形容做事仔细，形容声音要用“响亮”。"}, {"text": "这条路的宽度很精细。", "explanation": "这里不能用〈精细〉。精细形容做事仔细，形容宽度要用“宽”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他核对账目核对很精细。", "corrected_sentence": "他核对账目核对得很精细。", "error_description": "程度补语必须带“得”：应说“核对得很精细”，漏掉“得”则不能说“核对很精细”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他比以前精细着许多。", "corrected_sentence": "他比以前精细了许多。", "error_description": "体标错误：表示变化的应用“了”，不能用“着”。应说“精细了许多”，不说“精细着许多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
