INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21914, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情或音乐中，有规律、有快慢的变化。", "primary_collocate": null, "pronunciation": "jié zòu", "ipa": "tɕjɛ˧˥ tsou˥˩", "syllable_count": 2, "sentences": [{"text": "这首歌的节奏很快，听了想跳舞。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鼓声的节奏越来越慢。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跟着音乐的节奏拍手。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步时呼吸要有节奏。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段舞蹈节奏分明，很好学。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗读起来很有节奏。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师打着节拍，帮学生找到节奏。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "划船的人要保持同样的节奏。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的节奏很慢，大家听得清楚。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨点打在窗上，发出有节奏的声音。", "target_word": "节奏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "節奏", "label": "繁体"}, {"form": "节奏感", "label": "复合"}], "register": "中性", "sense_fingerprint": "音乐或动作中有规律的快慢强弱变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35b9a7f4-0ff9-4ffe-8c7b-041a5c756a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21914, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "节奏", "is_correct": true, "explanation": "正确。节奏（jié zòu）指音乐或事情中有规律的快慢变化。"}, {"text": "结构", "is_correct": false, "explanation": "结构（jié gòu）与节奏（jié zòu）第二个音节声母不同（g 与 z），意思是事物各部分的组织和构造。"}, {"text": "间奏", "is_correct": false, "explanation": "间奏（jiān zòu）与节奏（jié zòu）第一个音节韵母和声调不同，意思是乐曲中间的器乐段落。"}, {"text": "接走", "is_correct": false, "explanation": "接走（jiē zǒu）与节奏（jié zòu）两个音节的声调都不同，意思是把人接去别处。"}, {"text": "协奏", "is_correct": false, "explanation": "协奏（xié zòu）与节奏（jié zòu）第一个音节声母不同（x 与 j），意思是几种乐器协同演奏。"}], "explanations": {"节奏": "正确。节奏（jié zòu）指音乐或事情中有规律的快慢变化。", "结构": "结构（jié gòu）与节奏（jié zòu）第二个音节声母不同（g 与 z），意思是事物各部分的组织和构造。", "间奏": "间奏（jiān zòu）与节奏（jié zòu）第一个音节韵母和声调不同，意思是乐曲中间的器乐段落。", "接走": "接走（jiē zǒu）与节奏（jié zòu）两个音节的声调都不同，意思是把人接去别处。", "协奏": "协奏（xié zòu）与节奏（jié zòu）第一个音节声母不同（x 与 j），意思是几种乐器协同演奏。"}, "sentence_index": null, "correct_answer": "节奏"}, "level_3": {"options": [{"text": "节奏", "is_correct": true, "explanation": "正确。“节奏很快，听了想跳舞”说的是音乐中有规律的快慢变化。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能有快慢，“颜色很快”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指金额，不能像节奏一样有快慢，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不能快慢，句子说不通。"}], "explanations": {"节奏": "正确。“节奏很快，听了想跳舞”说的是音乐中有规律的快慢变化。", "颜色": "语义：颜色不能有快慢，“颜色很快”说不通。", "价格": "语义：“价格”指金额，不能像节奏一样有快慢，句意不通。", "体重": "语义：体重不能快慢，句子说不通。"}, "sentence_index": 0, "correct_answer": "节奏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "列车的节奏每小时三百公里。", "explanation": "这里应该用〈速度〉。速度可以用“每小时三百公里”计量；节奏指有规律的快慢变化，不能这样计量。"}, {"text": "这首歌的节奏很高。", "explanation": "这里应该用〈音调〉。音调指声音的高低，可以说“很高”；节奏指快慢变化，不能说“很高”。"}, {"text": "他的节奏是三十七度。", "explanation": "这里应该用〈体温〉。体温以度数计量；节奏指有规律的快慢变化，不能用温度来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da741986-cdb5-45e2-9005-670934ead580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节奏", "is_correct": true, "explanation": "正确。老师打着节拍，帮学生找到的是有规律的快慢变化，即节奏。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“打着节拍”的语境指向节奏，与钥匙无关，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“找到”通常不搭配“空气”，空气随处可得，不说“找到”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：打着节拍说的是快慢变化，与“温度”无关，句子说不通。"}], "explanations": {"节奏": "正确。老师打着节拍，帮学生找到的是有规律的快慢变化，即节奏。", "钥匙": "语义：“打着节拍”的语境指向节奏，与钥匙无关，句意不通。", "空气": "搭配：“找到”通常不搭配“空气”，空气随处可得，不说“找到”。", "温度": "语义：打着节拍说的是快慢变化，与“温度”无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "节奏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯的节奏很亮。", "explanation": "这里应该用〈亮度〉。亮度描述光的明暗，可以说“很亮”；节奏是有规律的快慢变化，不能说“很亮”。"}, {"text": "这块石头的节奏很硬。", "explanation": "这里应该用〈硬度〉。硬度描述物体的软硬，可以说“很硬”；节奏不能用来形容软硬。"}, {"text": "这个音箱的节奏很大。", "explanation": "这里应该用〈音量〉。音量指声音的大小，可以说“很大”；节奏指快慢变化，不能说“很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da741986-cdb5-45e2-9005-670934ead580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段音乐地节奏很轻快。", "corrected_sentence": "这段音乐的节奏很轻快。", "error_description": "结构助词误用：修饰名词“节奏”的定语“这段音乐”后应用“的”，不能用“地”。“音乐地节奏”错误，应为“音乐的节奏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da741986-cdb5-45e2-9005-670934ead580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段旋律有一节奏，适合跳舞。", "corrected_sentence": "这段旋律有一种节奏，适合跳舞。", "error_description": "量词缺失：“节奏”前的“一”后需接量词，应说“一种节奏”，不能直接说“一节奏”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da741986-cdb5-45e2-9005-670934ead580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
