INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "线谱是画了五条线的格子，用来写音乐。", "primary_collocate": null, "pronunciation": "xiàn pǔ", "ipa": "ɕjɛn˥˩ pʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "线谱上有五条线。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我一张线谱。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把小歌写在线谱上了。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多空白线谱，可以自己写歌。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看不懂线谱，所以不会唱这首歌。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用铅笔在纸上画了一张线谱。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "线谱里的小黑点是音符。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把音符放在线谱的第二条线上。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要写音乐，先要准备一张线谱。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了新的线谱，想自己写音乐。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "五线谱", "label": "复合"}, {"form": "张", "label": "量词"}], "register": "中性", "sense_fingerprint": "画了五条线、用来写音乐的格子：画线谱、写在线谱上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fe133c6-f46f-4dd8-8cd9-aa5b409f83b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "线谱", "is_correct": true, "explanation": "正确。线谱是画了五条线的格子，所以“上有五条线”指它。"}, {"text": "米饭", "is_correct": false, "explanation": "语义：米饭是食物，上面不会画五条线。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“声音”看不见，不能说“声音上有……”这样的线条。"}, {"text": "汤", "is_correct": false, "explanation": "语义：汤是液体，不能在上面画出五条线。"}], "explanations": {"线谱": "正确。线谱是画了五条线的格子，所以“上有五条线”指它。", "米饭": "语义：米饭是食物，上面不会画五条线。", "声音": "搭配：“声音”看不见，不能说“声音上有……”这样的线条。", "汤": "语义：汤是液体，不能在上面画出五条线。"}, "sentence_index": 0, "correct_answer": "线谱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一把线谱，准备学钢琴。", "explanation": "这里应该用〈张〉。线谱是纸质格子，量词用“张”；“把”用于椅子、刀等，不能用于线谱。"}, {"text": "他照着线谱炒了一盘菜。", "explanation": "这里应该用〈食谱〉。线谱是画了五条线的格子，用来写音乐，不能照着做菜；做菜要照食谱。"}, {"text": "他拿着线谱，很快找到了车站。", "explanation": "这里应该用〈地图〉。线谱是画了五条线的格子，用来写音乐，不标路线；找路要用地图。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b54dd72-865d-4f34-9ec1-efd1ea93ba10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "线谱", "is_correct": true, "explanation": "正确。线谱是画了五条线的格子，音符写在格子里，所以“里的小黑点是音符”指它。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空里的小黑点是星星或飞鸟，不是音符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕里的小黑点是巧克力或果干，与音符无关。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发上没有音符，“是音符”不成立。"}], "explanations": {"线谱": "正确。线谱是画了五条线的格子，音符写在格子里，所以“里的小黑点是音符”指它。", "天空": "语义：天空里的小黑点是星星或飞鸟，不是音符。", "蛋糕": "语义：蛋糕里的小黑点是巧克力或果干，与音符无关。", "沙发": "语义：沙发上没有音符，“是音符”不成立。"}, "sentence_index": 6, "correct_answer": "线谱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她撑着线谱，走在大太阳下。", "explanation": "这里应该用〈遮阳伞〉。线谱是画了五条线的格子，用来写音乐，不能用来挡太阳；挡太阳要用遮阳伞。"}, {"text": "她翻开线谱，找朋友的号码。", "explanation": "这里应该用〈电话簿〉。线谱是画了五条线的格子，不记录号码。"}, {"text": "她每天弹线谱，弹得很好。", "explanation": "这里应该用〈钢琴〉。线谱是用来写音符的格子，不能用来弹奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b54dd72-865d-4f34-9ec1-efd1ea93ba10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟线谱带回了家。", "corrected_sentence": "弟弟把线谱带回了家。", "error_description": "错误：缺少处置介词“把”。“带回”要带受事“线谱”，处置式应说“把线谱带回……”，不能直接说“线谱带回……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b54dd72-865d-4f34-9ec1-efd1ea93ba10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她画好了一把线谱。", "corrected_sentence": "她画好了线谱。", "error_description": "错误：多加了量词“把”。“画好了”后直接接宾语“线谱”即可；“把”用于椅子、刀等，不能修饰线谱。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b54dd72-865d-4f34-9ec1-efd1ea93ba10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
