INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21922, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物外部的样子或样式（与内容相对）。", "primary_collocate": null, "pronunciation": "xíng shì", "ipa": "ɕiŋ˧˥ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "这两本书的形式看起来很像，但内容不同。", "target_word": "形式", "complexity_tier": "T3", "furigana": "zhè liǎng běn shū de xíng shì kàn qǐ lái hěn xiàng, dàn nèi róng bù tóng。", "sentence_source": "generated"}, {"text": "这家店的面包做成了不同的形式，有大的，也有小的。", "target_word": "形式", "complexity_tier": "T3", "furigana": "zhè jiā diàn de miàn bāo zuò chéng le bù tóng de xíng shì, yǒu dà de, yě yǒu xiǎo de。", "sentence_source": "generated"}, {"text": "这几座房子的形式不一样，有的高，有的矮。", "target_word": "形式", "complexity_tier": "T3", "furigana": "zhè jǐ zuò fáng zi de xíng shì bù yí yàng, yǒu de gāo, yǒu de ǎi。", "sentence_source": "generated"}, {"text": "这种糖果有很多形式，有的是圆的，有的是长条的。", "target_word": "形式", "complexity_tier": "T3", "furigana": "zhè zhǒng táng guǒ yǒu hěn duō xíng shì, yǒu de shì yuán de, yǒu de shì cháng tiáo de。", "sentence_source": "generated"}, {"text": "这两件衣服的形式不同，一件领子大，一件领子小。", "target_word": "形式", "complexity_tier": "T3", "furigana": "zhè liǎng jiàn yī fu de xíng shì bù tóng, yí jiàn lǐng zi dà, yí jiàn lǐng zi xiǎo。", "sentence_source": "generated"}, {"text": "他把照片做成了小本子的形式。", "target_word": "形式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具有两种形式，可以拆开，也可以合起来。", "target_word": "形式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几张桌子的形式一样，只是颜色不同。", "target_word": "形式", "complexity_tier": "T3", "furigana": "zhè jǐ zhāng zhuō zi de xíng shì yí yàng, zhǐ shì yán sè bù tóng。", "sentence_source": "generated"}, {"text": "你先看看这张表的形式，再照着填。", "target_word": "形式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "礼物的形式不重要，心意最重要。", "target_word": "形式", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种形式", "label": "量词"}, {"form": "形式主义", "label": "复合"}], "register": "中性", "sense_fingerprint": "形式：东西外表的样子、样式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba7f1315-ce80-48ee-ae24-9d3dc8e5ede7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21922, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "形式", "is_correct": true, "explanation": "正确：形式读 xíng shì，指东西外表的样子、样式。"}, {"text": "情势", "is_correct": false, "explanation": "声母不同：情势读 qíng shì，q 与 x 不同，意思是情况和局势。"}, {"text": "行驶", "is_correct": false, "explanation": "声调不同：行驶读 xíng shǐ，第二个音节是第三声，意思是车船等移动。"}, {"text": "姓氏", "is_correct": false, "explanation": "声调不同：姓氏读 xìng shì，第一个音节是第四声，意思是姓。"}], "explanations": {"形式": "正确：形式读 xíng shì，指东西外表的样子、样式。", "情势": "声母不同：情势读 qíng shì，q 与 x 不同，意思是情况和局势。", "行驶": "声调不同：行驶读 xíng shǐ，第二个音节是第三声，意思是车船等移动。", "姓氏": "声调不同：姓氏读 xìng shì，第一个音节是第四声，意思是姓。"}, "sentence_index": null, "correct_answer": "形式"}, "level_3": {"options": [{"text": "形式", "is_correct": true, "explanation": "正确：这两本书的形式指外表的样子，看起来很像，与后文“内容不同”相合。"}, {"text": "内容", "is_correct": false, "explanation": "语义：前句已说“内容不同”，不能再说“内容看起来很像”，句意自相矛盾。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味要用鼻子闻，不能用“看起来”来判断，句子不通。"}, {"text": "作者", "is_correct": false, "explanation": "语义：作者是写书的人，不是书的外表，说“作者看起来很像”不成立。"}], "explanations": {"形式": "正确：这两本书的形式指外表的样子，看起来很像，与后文“内容不同”相合。", "内容": "语义：前句已说“内容不同”，不能再说“内容看起来很像”，句意自相矛盾。", "气味": "语义：气味要用鼻子闻，不能用“看起来”来判断，句子不通。", "作者": "语义：作者是写书的人，不是书的外表，说“作者看起来很像”不成立。"}, "sentence_index": 0, "correct_answer": "形式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种糖果有两只形式，有的是圆的，有的是长条的。", "explanation": "这里应该用〈种〉。形式的量词是“种”，“只”用于动物，不能修饰形式。"}, {"text": "这种糖果有两根形式，有的是圆的，有的是长条的。", "explanation": "这里应该用〈种〉。“根”用于细长的东西，形式不用“根”。"}, {"text": "这种糖果有两张形式，有的是圆的，有的是长条的。", "explanation": "这里应该用〈种〉。“张”用于平面的东西，形式不用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f53395cd-971c-4e30-814f-9bf16cb128ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21922, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "形式", "is_correct": true, "explanation": "正确：形式读 xíng shì，指东西外表的样子、样式。"}, {"text": "幸事", "is_correct": false, "explanation": "声调不同：幸事读 xìng shì，第一个音节是第四声，意思是令人高兴的事。"}, {"text": "行使", "is_correct": false, "explanation": "声调不同：行使读 xíng shǐ，第二个音节是第三声，意思是运用权力。"}, {"text": "形制", "is_correct": false, "explanation": "声母不同：形制读 xíng zhì，第二个音节声母是 zh，意思是器物或建筑的形式和规制。"}], "explanations": {"形式": "正确：形式读 xíng shì，指东西外表的样子、样式。", "幸事": "声调不同：幸事读 xìng shì，第一个音节是第四声，意思是令人高兴的事。", "行使": "声调不同：行使读 xíng shǐ，第二个音节是第三声，意思是运用权力。", "形制": "声母不同：形制读 xíng zhì，第二个音节声母是 zh，意思是器物或建筑的形式和规制。"}, "sentence_index": null, "correct_answer": "形式"}, "level_3": {"options": [{"text": "形式", "is_correct": true, "explanation": "正确：玩具有两种形式，指结构上的样式，可以拆开、合起来，与后文相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能拆开，也不能合起来，与后文“可以拆开，也可以合起来”不符。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”指食物或气息，玩具不说“两种味道”，搭配不当。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能拆开再合起来，与后文“可以拆开，也可以合起来”不符。"}], "explanations": {"形式": "正确：玩具有两种形式，指结构上的样式，可以拆开、合起来，与后文相符。", "颜色": "语义：颜色不能拆开，也不能合起来，与后文“可以拆开，也可以合起来”不符。", "味道": "搭配：“味道”指食物或气息，玩具不说“两种味道”，搭配不当。", "声音": "语义：声音不能拆开再合起来，与后文“可以拆开，也可以合起来”不符。"}, "sentence_index": 6, "correct_answer": "形式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "眼下的形式很严峻。", "explanation": "这里应该用〈形势〉。“严峻”形容局势，形式指东西外在的样子，二者读音相同，容易混淆。"}, {"text": "这块布的形式很软。", "explanation": "这里应该用〈质地〉。“软”形容质地，形式指东西外在的样子，不能用来描述软硬。"}, {"text": "这碗汤的形式很甜。", "explanation": "这里应该用〈味道〉。“甜”形容味道，形式指东西外在的样子，不能用来描述甜淡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f53395cd-971c-4e30-814f-9bf16cb128ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这盒点心有三只形式，有的圆，有的方。", "corrected_sentence": "这盒点心有三种形式，有的圆，有的方。", "error_description": "量词错误：错误形式为“三只形式”，正确形式为“三种形式”。“只”用于动物，形式应该用“种”来计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f53395cd-971c-4e30-814f-9bf16cb128ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的面包有不同地形式，大的和小的都有。", "corrected_sentence": "这家店的面包有不同的形式，大的和小的都有。", "error_description": "结构助词错误：错误形式为“不同地形式”，正确形式为“不同的形式”。“不同”修饰名词“形式”，要用“的”，不用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f53395cd-971c-4e30-814f-9bf16cb128ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
