INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21934, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "大家都可以用的。", "primary_collocate": null, "pronunciation": "tōng yòng", "ipa": "tʰʊŋ˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种螺丝规格统一，各种机器都通用。", "target_word": "通用", "complexity_tier": "T3", "furigana": "zhè zhǒng luósi guīgé tǒngyī, gèzhǒng jīqì dōu tōngyòng", "sentence_source": "generated"}, {"text": "这个房间的门卡大家通用。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套书全班同学通用，不用每人买一本。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们两个人的充电器是通用的。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种雨衣男女通用，大小也合适。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "办公室里的打印机大家通用。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张公园年票家人之间能通用吗？", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套标准教材全校通用。", "target_word": "通用", "complexity_tier": "T3", "furigana": "zhè tào biāozhǔn jiàocái quánxiào tōngyòng", "sentence_source": "generated"}, {"text": "这些工具在家里是大家通用的。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个账号我们一家人通用。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "通用型", "label": "复合"}], "register": "中性", "sense_fingerprint": "通用·东西不分人，大家都可以拿来用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d86f571-e8f9-490c-a880-a6de728f335c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21934, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通用", "is_correct": true, "explanation": "通用：tōng yòng，意思是大家都可以用。"}, {"text": "同用", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，同用指一起使用，不是「大家都可以用」。"}, {"text": "动用", "is_correct": false, "explanation": "dòng（第四声）与 tōng（第一声）声母和声调都不同，动用指调动使用，如动用资金。"}, {"text": "中用", "is_correct": false, "explanation": "zhōng（第一声）与 tōng（第一声）声母不同（zh 与 t），中用指有用、能用，多用于口语。"}], "explanations": {"通用": "通用：tōng yòng，意思是大家都可以用。", "同用": "tóng（第二声）与 tōng（第一声）声调不同，同用指一起使用，不是「大家都可以用」。", "动用": "dòng（第四声）与 tōng（第一声）声母和声调都不同，动用指调动使用，如动用资金。", "中用": "zhōng（第一声）与 tōng（第一声）声母不同（zh 与 t），中用指有用、能用，多用于口语。"}, "sentence_index": null, "correct_answer": "通用"}, "level_3": {"options": [{"text": "通用", "is_correct": true, "explanation": "通用：螺丝规格统一，各种机器都能用，符合句意。"}, {"text": "专用", "is_correct": false, "explanation": "语义：「专用」与「通用」意思相反，「各种机器都专用」与「各种」的意思矛盾。"}, {"text": "通晓", "is_correct": false, "explanation": "搭配：「通晓」指人懂得某种知识，不能用来形容机器。"}, {"text": "通顺", "is_correct": false, "explanation": "搭配：「通顺」形容文字或语句，不能说螺丝或机器「通顺」。"}], "explanations": {"通用": "通用：螺丝规格统一，各种机器都能用，符合句意。", "专用": "语义：「专用」与「通用」意思相反，「各种机器都专用」与「各种」的意思矛盾。", "通晓": "搭配：「通晓」指人懂得某种知识，不能用来形容机器。", "通顺": "搭配：「通顺」形容文字或语句，不能说螺丝或机器「通顺」。"}, "sentence_index": 0, "correct_answer": "通用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种现象在学生中很通用。", "explanation": "这里应该用〈普遍〉。通用指东西大家都可以用，说现象的范围广要用普遍。"}, {"text": "我们俩有很多通用的爱好。", "explanation": "这里应该用〈共同〉。通用指东西大家都能用，两个人共有的爱好要用共同。"}, {"text": "这种错误在新手中很通用。", "explanation": "这里应该用〈常见〉。通用不用来说错误的多少，描述错误常见要用常见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21934, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "通用", "is_correct": true, "explanation": "通用：tōng yòng，意思是大家都可以用。"}, {"text": "通融", "is_correct": false, "explanation": "róng（第二声）与 yòng（第四声）声母与声调都不同，通融指灵活变通。"}, {"text": "投用", "is_correct": false, "explanation": "tóu（第二声）与 tōng（第一声）声母相同，韵母与声调不同，投用指投入使用。"}, {"text": "中庸", "is_correct": false, "explanation": "zhōng（第一声）与 tōng 声母不同（zh 与 t），yōng 与 yòng 声调不同，中庸指不偏不倚。"}], "explanations": {"通用": "通用：tōng yòng，意思是大家都可以用。", "通融": "róng（第二声）与 yòng（第四声）声母与声调都不同，通融指灵活变通。", "投用": "tóu（第二声）与 tōng（第一声）声母相同，韵母与声调不同，投用指投入使用。", "中庸": "zhōng（第一声）与 tōng 声母不同（zh 与 t），yōng 与 yòng 声调不同，中庸指不偏不倚。"}, "sentence_index": null, "correct_answer": "通用"}, "level_3": {"options": [{"text": "通用", "is_correct": true, "explanation": "通用：这张年票家人之间可以共同使用，符合句意。"}, {"text": "独立", "is_correct": false, "explanation": "语义：「独立」指不依赖他人，与「家人之间能……吗」的询问不搭，句子说不通。"}, {"text": "专属", "is_correct": false, "explanation": "配价：「专属」后一般要接「于」引出对象，单独用在「能……吗」中结构不完整。"}, {"text": "私有", "is_correct": false, "explanation": "语义：「私有」指归个人所有，与「公园年票」的公共性质矛盾。"}], "explanations": {"通用": "通用：这张年票家人之间可以共同使用，符合句意。", "独立": "语义：「独立」指不依赖他人，与「家人之间能……吗」的询问不搭，句子说不通。", "专属": "配价：「专属」后一般要接「于」引出对象，单独用在「能……吗」中结构不完整。", "私有": "语义：「私有」指归个人所有，与「公园年票」的公共性质矛盾。"}, "sentence_index": 6, "correct_answer": "通用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章写得很通用，连小孩都能看懂。", "explanation": "这里应该用〈通俗〉。通用指大家都能用，说文章容易懂要用「通俗」。"}, {"text": "这把牙刷是我个人通用的。", "explanation": "这里应该用〈专用〉。「通用」指大家都能用，只归个人使用的牙刷要用「专用」。"}, {"text": "这块私人土地是通用的。", "explanation": "这里应该用〈私有〉。「通用」指大家都可以用，私人土地只归一家或一个人所有，要用「私有」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款软件在各种手机上都被通用。", "corrected_sentence": "这款软件在各种手机上都通用。", "error_description": "错误：“通用”是形容词，不能用“被”引出被动；“都被通用”不成立，正确应为“在各种手机上都通用”，去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这款数据线把各种品牌的手机上都能通用。", "corrected_sentence": "这款数据线在各种品牌的手机上都能通用。", "error_description": "错误：“把”的宾语应是被处置的人或事物，这里“把各种品牌的手机上”以地点作宾语，不成立；应改为“在各种品牌的手机上都能通用”，用“在”引出适用范围。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
