INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21936, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "古时候用来写音乐的一种字，比如“工”和“尺”。", "primary_collocate": null, "pronunciation": "gōng chě", "ipa": "kʊŋ˥ ʈʂʰɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这些字是工尺，不是普通的汉字。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷小时候学过工尺。", "target_word": "工尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的人用工尺写歌。", "target_word": "工尺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书上有“上”“尺”“工”，这些都是工尺。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们怎么读工尺。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那张旧纸上写满了工尺。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古人记音用工尺，现在大多用音符。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他正在练习唱工尺，声音很好听。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本古书里的工尺，我一个也看不懂。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果你想唱古歌，就要先认识工尺。", "target_word": "工尺", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "工尺谱", "label": "复合"}], "register": "书面", "sense_fingerprint": "古时候用来写音乐的字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fe133c6-f46f-4dd8-8cd9-aa5b409f83b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21936, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工尺", "is_correct": true, "explanation": "正确：“这些字是工尺”指它们是古时用来记音乐的字。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字是计数的符号，工尺不是数字，「这些字是数字」不通。"}, {"text": "笔画", "is_correct": false, "explanation": "语义：笔画是构成字的笔道，不等于字本身，与“这些字是”不符。"}, {"text": "玩意", "is_correct": false, "explanation": "语域：“玩意”是口语说法，与书面化的句子不相称。"}], "explanations": {"工尺": "正确：“这些字是工尺”指它们是古时用来记音乐的字。", "数字": "语义：数字是计数的符号，工尺不是数字，「这些字是数字」不通。", "笔画": "语义：笔画是构成字的笔道，不等于字本身，与“这些字是”不符。", "玩意": "语域：“玩意”是口语说法，与书面化的句子不相称。"}, "sentence_index": 0, "correct_answer": "工尺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用工尺量了量桌子的长度。", "explanation": "语义：这里把“工尺”当成了〈尺〉（量长度的器具），但工尺指古时用来写音乐的字，不能用来量东西。"}, {"text": "桌上放着一位工尺。", "explanation": "量词：「位」用于人，工尺是记音的字，不能用「位」来数。"}, {"text": "他正在吃工尺。", "explanation": "语义：这里把“工尺”当成了〈食物〉来吃，但工尺是古时用来写音乐的字，不是食物，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b54dd72-865d-4f34-9ec1-efd1ea93ba10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工尺", "is_correct": true, "explanation": "正确：「古人记音用工尺」指古时用工尺这种字记音。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是演奏工具，不是记音的字，「记音用乐器」不通。"}, {"text": "扑克", "is_correct": false, "explanation": "语义：扑克是纸牌，与记音无关，句子不通。"}, {"text": "货色", "is_correct": false, "explanation": "语域：“货色”是口语贬义词，与这句书面叙述不相称。"}], "explanations": {"工尺": "正确：「古人记音用工尺」指古时用工尺这种字记音。", "乐器": "语义：乐器是演奏工具，不是记音的字，「记音用乐器」不通。", "扑克": "语义：扑克是纸牌，与记音无关，句子不通。", "货色": "语域：“货色”是口语贬义词，与这句书面叙述不相称。"}, "sentence_index": 6, "correct_answer": "工尺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在工尺上班，很辛苦。", "explanation": "语义：这里把“工尺”当成了〈单位〉（工作的场所），但工尺是古时用来写音乐的字，不指工作的地方。"}, {"text": "工尺是我的同事，人很和气。", "explanation": "语义：这里把“工尺”当成了〈朋友〉一类的人，但工尺是古时用来写音乐的字，不指人。"}, {"text": "他的工尺每月拿五千元。", "explanation": "语义：工尺指记音的字，不指工资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b54dd72-865d-4f34-9ec1-efd1ea93ba10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "纸上写着几座工尺。", "corrected_sentence": "纸上写着几行工尺。", "error_description": "错误：「几座工尺」；正确：「几行工尺」。「座」用于山、楼房等大型固定物，不能用来数写满字的纸；数文字的行列要用「行」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b54dd72-865d-4f34-9ec1-efd1ea93ba10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于看了懂工尺。", "corrected_sentence": "他终于看懂了工尺。", "error_description": "错误：“看了懂”；正确：“看懂了”。结果补语“懂”应紧跟动词“看”，“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b54dd72-865d-4f34-9ec1-efd1ea93ba10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
