INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21940, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用汉字表示古琴弹奏方法的符号。", "primary_collocate": null, "pronunciation": "jiǎn zì pǔ", "ipa": "tɕjɛn˨˩˦ tsz̩˥˩ pʰu˨˩˦", "syllable_count": 3, "sentences": [{"text": "减字谱是古琴的谱子。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古琴老师给我一张减字谱。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张减字谱上有很多汉字。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学会看减字谱。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弹古琴时，我看着减字谱。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减字谱告诉我用哪个手指。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首古琴曲的减字谱在书里。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减字谱看起来像小小的汉字。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都练习看减字谱。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会读古琴的减字谱吗？", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张减字谱", "label": "量词"}, {"form": "減字譜", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用汉字写成的古琴谱符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba7f1315-ce80-48ee-ae24-9d3dc8e5ede7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减字谱", "is_correct": true, "explanation": "减字谱是专为古琴设计的谱子，句意通顺。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器本身，不是谱子，“钢琴是古琴的谱子”说不通。"}, {"text": "手指", "is_correct": false, "explanation": "语义：手指不是谱子，放在“古琴的”后面句意不通。"}, {"text": "琴弦", "is_correct": false, "explanation": "语义：琴弦是古琴上的弦，不是谱子，“琴弦是古琴的谱子”句意不通。"}], "explanations": {"减字谱": "减字谱是专为古琴设计的谱子，句意通顺。", "钢琴": "语义：钢琴是乐器本身，不是谱子，“钢琴是古琴的谱子”说不通。", "手指": "语义：手指不是谱子，放在“古琴的”后面句意不通。", "琴弦": "语义：琴弦是古琴上的弦，不是谱子，“琴弦是古琴的谱子”句意不通。"}, "sentence_index": 0, "correct_answer": "减字谱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "减字谱用工、尺、上等字标音高，学唱的人很多。", "explanation": "这里应该用〈工尺谱〉。工尺谱用工、尺、上等字记音高；减字谱用汉字部件组成的符号指示古琴的弹奏方法，不用这些字。"}, {"text": "减字谱用五条线记录音高，初学者照着就能唱。", "explanation": "这里应该用〈五线谱〉。五线谱用五条线和音符记录音高；减字谱不用线，而是指示弦位和指法。"}, {"text": "减字谱是一种乐器，靠吹奏发声。", "explanation": "这里应该用〈古琴〉。古琴靠手指弹拨发声；减字谱是古琴的记谱符号，本身不发声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f53395cd-971c-4e30-814f-9bf16cb128ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减字谱", "is_correct": true, "explanation": "“这首古琴曲的”后面接它的记谱，减字谱在书里，句意通顺。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“这首古琴曲的”后面应接与这首曲子相关的记谱或曲名，“手机”不属于这首曲子。"}, {"text": "烤鸭", "is_correct": false, "explanation": "语义：烤鸭是食物，不是曲子的记录，句意不通。"}, {"text": "高铁", "is_correct": false, "explanation": "语义：高铁是交通工具，与古琴曲的记录无关，句意不通。"}], "explanations": {"减字谱": "“这首古琴曲的”后面接它的记谱，减字谱在书里，句意通顺。", "手机": "搭配：“这首古琴曲的”后面应接与这首曲子相关的记谱或曲名，“手机”不属于这首曲子。", "烤鸭": "语义：烤鸭是食物，不是曲子的记录，句意不通。", "高铁": "语义：高铁是交通工具，与古琴曲的记录无关，句意不通。"}, "sentence_index": 6, "correct_answer": "减字谱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "减字谱上标着每个音的音高，照着就能唱。", "explanation": "这里应该用〈乐谱〉。乐谱泛指标明音高的谱子；减字谱不标音高，只指示弦位和指法。"}, {"text": "减字谱用数字1到7标出音高，学起来很简单。", "explanation": "这里应该用〈简谱〉。简谱用数字1到7标音高；减字谱用汉字部件指示弦位和指法，不标数字音高。"}, {"text": "我把这张减字谱放进播放器，听它的声音。", "explanation": "这里把减字谱当成了录音。减字谱是记谱符号，本身不发声，也不能直接播放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f53395cd-971c-4e30-814f-9bf16cb128ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看懂着减字谱。", "corrected_sentence": "他看懂了减字谱。", "error_description": "体貌错误：“看懂”是结果补语，不能与“着”连用；表示动作已完成要用“了”，应说“他看懂了减字谱”，不能说“他看懂着减字谱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f53395cd-971c-4e30-814f-9bf16cb128ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我减字谱看完了。", "corrected_sentence": "我把减字谱看完了。", "error_description": "把字句缺少“把”：宾语“减字谱”前要用“把”引出，应说“我把减字谱看完了”，不能省去“把”说“我减字谱看完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f53395cd-971c-4e30-814f-9bf16cb128ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
