INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21942, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21942, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种最小的声音单位，能改变词语的意思。", "primary_collocate": null, "pronunciation": "yīn wèi", "ipa": "in˥ wei˥˩", "syllable_count": 2, "sentences": [{"text": "每种语言都有自己的音位。", "target_word": "音位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“爸”和“怕”开头的音位不同。", "target_word": "音位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音位不同，词的意思也不同。", "target_word": "音位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个音位我总是发不好。", "target_word": "音位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日语的音位比汉语的少。", "target_word": "音位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道这个词里有几个音位。", "target_word": "音位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友先学会简单的音位。", "target_word": "音位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换掉一个音位，“米”就变成别的词了。", "target_word": "音位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听写时，我常常分不清相近的音位。", "target_word": "音位", "complexity_tier": "T3", "furigana": "tīng xiě shí, wǒ cháng cháng fēn bu qīng xiāng jìn de yīn wèi.", "sentence_source": "generated"}, {"text": "外国人学汉语，常分不清有些音位。", "target_word": "音位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "音位学", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "能改变词义的最小声音单位（通俗说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f95e5d-4e87-424f-8121-0527036d276a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21942, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音位", "is_correct": true, "explanation": "正确：“音位”是语言的基本单位，与“每种语言都有自己的”相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是人的身体状况，不属于语言。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高形容人或物的外形，不能用于语言。"}, {"text": "体重", "is_correct": false, "explanation": "语义：语言没有体重，“每种语言都有自己的体重”句子无法成立。"}], "explanations": {"音位": "正确：“音位”是语言的基本单位，与“每种语言都有自己的”相符。", "体温": "语义：体温是人的身体状况，不属于语言。", "身高": "体貌：身高形容人或物的外形，不能用于语言。", "体重": "语义：语言没有体重，“每种语言都有自己的体重”句子无法成立。"}, "sentence_index": 0, "correct_answer": "音位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这句话是一个音位。", "explanation": "这里应该用〈句子〉。这句话是一个句子；音位是最小的语音单位，不能说整句话是一个音位。"}, {"text": "这个音位有两个意思。", "explanation": "这里应该用〈词〉。音位本身不表示意义，只能区别意义；有意思的是词。"}, {"text": "他说话的音位很大。", "explanation": "这里应该用〈音量〉。说话声音的大小要说“音量”，音位指能区别意义的语音单位，没有大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音位", "is_correct": true, "explanation": "正确：“学会简单的音位”指学习语言的基本语音单位，符合句意。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“学会”搭配知识或技能，不能学会“礼物”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“简单的温度”不是可以学会的内容，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”不是可以学会的内容，句意不通。"}], "explanations": {"音位": "正确：“学会简单的音位”指学习语言的基本语音单位，符合句意。", "礼物": "搭配：“学会”搭配知识或技能，不能学会“礼物”。", "温度": "语义：“简单的温度”不是可以学会的内容，句意不通。", "价格": "语义：“价格”不是可以学会的内容，句意不通。"}, "sentence_index": 6, "correct_answer": "音位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“爸”是一个音位。", "explanation": "这里应该用〈音节〉。“爸”由两个音位组成，整体是一个音节，不能说是一个音位。"}, {"text": "这个音位在桌子上。", "explanation": "这里应该用〈书〉。书可以放在桌子上；音位是抽象的语音单位，不是具体的东西，不能放在桌子上。"}, {"text": "这个音位有四画。", "explanation": "这里应该用〈字〉。音位没有笔画，有笔画、可以书写的是字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汉语有几十把音位。", "corrected_sentence": "汉语有几十个音位。", "error_description": "“音位”的量词应为“个”，不能用“把”。“把”用于有柄或可握住的东西，抽象单位用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这些音位们都记住了。", "corrected_sentence": "他把这些音位都记住了。", "error_description": "“们”只用于指人，“音位”是抽象的语音单位，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
