INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21948, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "仔细看或想，来知道更多东西。", "primary_collocate": null, "pronunciation": "yán jiū", "ipa": "jɛn˧˥ tɕjoʊ˥", "syllable_count": 2, "sentences": [{"text": "医生每天都在研究这种药的作用。", "target_word": "研究", "complexity_tier": "T3", "furigana": "yī shēng měi tiān dōu zài yán jiū zhè zhǒng yào de zuò yòng", "sentence_source": "generated"}, {"text": "我们正在研究这个问题。", "target_word": "研究", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师研究了很多年中国历史。", "target_word": "研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想研究怎么让小孩爱读书。", "target_word": "研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事我要回家研究一下。", "target_word": "研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们研究过这种鱼的生活。", "target_word": "研究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在研究新的办法。", "target_word": "研究", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥爱研究电脑，常常研究到半夜。", "target_word": "研究", "complexity_tier": "T3", "furigana": "gē ge ài yán jiū diàn nǎo, cháng cháng yán jiū dào bàn yè", "sentence_source": "generated"}, {"text": "我们先研究地图，再决定怎么走。", "target_word": "研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家研究着明天的计划。", "target_word": "研究", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "研究了", "label": "完成体"}, {"form": "研究过", "label": "经历体"}, {"form": "研究着", "label": "持续体"}, {"form": "研究生", "label": "复合词"}, {"form": "研究所", "label": "复合词"}], "register": "中性", "sense_fingerprint": "认真调查思考某个事物，想弄清楚它", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ee3da4-4c99-4c2d-aaed-c51fb6a3dd04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究", "is_correct": true, "explanation": "正确。“研究”指仔细琢磨、探求，与“每天都在……这种药的作用”相符。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：“生产”指制造东西，“作用”不能被生产，应说“产生作用”。"}, {"text": "分配", "is_correct": false, "explanation": "语义：“分配”指按份额分派，与弄清药的作用无关。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”指不再坚持，与“每天都在”进行的工作不符，句意说不通。"}], "explanations": {"研究": "正确。“研究”指仔细琢磨、探求，与“每天都在……这种药的作用”相符。", "生产": "搭配：“生产”指制造东西，“作用”不能被生产，应说“产生作用”。", "分配": "语义：“分配”指按份额分派，与弄清药的作用无关。", "放弃": "语义：“放弃”指不再坚持，与“每天都在”进行的工作不符，句意说不通。"}, "sentence_index": 0, "correct_answer": "研究"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每天研究教室，很辛苦。", "explanation": "这里应该用〈打扫〉。研究指仔细琢磨问题，不能用于具体的清扫动作；清扫教室要用打扫。"}, {"text": "妈妈每天研究生病的弟弟，帮他擦身换衣服。", "explanation": "这里应该用〈照顾〉。研究指仔细琢磨问题，不表示照料病人；帮病人擦身、换衣要用照顾。"}, {"text": "他把窗户研究得很干净。", "explanation": "这里应该用〈擦〉。研究不能使物体变干净，擦窗户要用擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究", "is_correct": true, "explanation": "正确。“研究”指仔细探求，与“在……新的办法”相符。"}, {"text": "丢掉", "is_correct": false, "explanation": "语义：“丢掉”指失去，与“在……新的办法”的动作相反，句意说不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”一般接衣服、鞋帽，不能与“办法”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”一般接食物或药物，“办法”不能被吃。"}], "explanations": {"研究": "正确。“研究”指仔细探求，与“在……新的办法”相符。", "丢掉": "语义：“丢掉”指失去，与“在……新的办法”的动作相反，句意说不通。", "穿": "搭配：“穿”一般接衣服、鞋帽，不能与“办法”搭配。", "吃": "搭配：“吃”一般接食物或药物，“办法”不能被吃。"}, "sentence_index": 6, "correct_answer": "研究"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在食堂研究了一大碗面，吃得很饱。", "explanation": "这里应该用〈吃〉。研究指仔细看或想，不表示吃东西；吃面、吃饭要用吃。"}, {"text": "她每天研究校服去上学。", "explanation": "这里应该用〈穿〉。研究不能表示把衣服穿在身上，穿校服要用穿。"}, {"text": "他去超市研究了三斤苹果，付了钱就走了。", "explanation": "这里应该用〈买〉。研究指仔细看或想，不表示付钱购买；买苹果要用买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们研究很清楚，大家都明白了。", "corrected_sentence": "他们研究得很清楚，大家都明白了。", "error_description": "补语标记错误：“研究”后接描述结果的补语要用“得”，应说“研究得很清楚”，不能省略“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们研究过过这个方法。", "corrected_sentence": "我们研究过这个方法。", "error_description": "体标错误：经历体“过”只用一次，应说“研究过这个方法”，不能重复“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21950, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "误解", "is_correct": true, "explanation": "“误解”指理解错了意思或想法，与“理解”构成反义。"}, {"text": "批评", "is_correct": false, "explanation": "“批评”指指出缺点和错误，与“理解”没有反义关系。"}, {"text": "欢迎", "is_correct": false, "explanation": "“欢迎”表示乐于接受，与“理解”没有反义关系。"}, {"text": "保护", "is_correct": false, "explanation": "“保护”指护卫使其不受伤害，与“理解”没有反义关系。"}], "correct_answer": "误解", "explanations": {"误解": "“误解”指理解错了意思或想法，与“理解”构成反义。", "批评": "“批评”指指出缺点和错误，与“理解”没有反义关系。", "欢迎": "“欢迎”表示乐于接受，与“理解”没有反义关系。", "保护": "“保护”指护卫使其不受伤害，与“理解”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21950, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "误解", "is_correct": true, "explanation": "“误解”指理解错了句子的意思，与“理解”构成反义。"}, {"text": "帮助", "is_correct": false, "explanation": "“帮助”指给予支持或协助，与“理解”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指共同商议问题，与“理解”没有反义关系。"}, {"text": "欣赏", "is_correct": false, "explanation": "“欣赏”指觉得美好而喜爱，与“理解”没有反义关系。"}], "correct_answer": "误解", "explanations": {"误解": "“误解”指理解错了句子的意思，与“理解”构成反义。", "帮助": "“帮助”指给予支持或协助，与“理解”没有反义关系。", "讨论": "“讨论”指共同商议问题，与“理解”没有反义关系。", "欣赏": "“欣赏”指觉得美好而喜爱，与“理解”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21950, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "知道一件事是什么意思，比如你听懂妈妈在说什么。", "primary_collocate": null, "pronunciation": "lǐ jiě", "ipa": "li˨˩˦ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师说得很慢，我能理解。", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的专业术语太多，我看了半天也没理解。", "target_word": "理解", "complexity_tier": "T3", "furigana": "zhè piān wénzhāng de zhuānyè shùyǔ tài duō, wǒ kànle bàntiān yě méi lǐjiě", "sentence_source": "generated"}, {"text": "他不太理解妈妈的话。", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我理解你为什么生气。", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题很难理解。", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都理解了他的意思。", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还不理解大人的工作。", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用图表解释了病情，我终于理解了。", "target_word": "理解", "complexity_tier": "T3", "furigana": "yīshēng yòng túbiǎo jiěshìle bìngqíng, wǒ zhōngyú lǐjiě le", "sentence_source": "generated"}, {"text": "我很难理解他的想法。", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你理解这个句子的意思吗？", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "理解了", "label": "体标"}, {"form": "理解过", "label": "体标"}], "register": "中性", "sense_fingerprint": "明白某事的意思或某人的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be5ee50c-f9af-43f9-b71d-60fc13a41298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21950, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "理解", "is_correct": true, "explanation": "正确答案。理解 lǐ jiě，意思是明白意思或想法。"}, {"text": "礼节", "is_correct": false, "explanation": "jié（第二声）与 jiě（第三声）声调不同，意思是礼节。"}, {"text": "历届", "is_correct": false, "explanation": "lì jiè 两个音节的声调都与 lǐ jiě 不同，意思是历次届别。"}, {"text": "你姐", "is_correct": false, "explanation": "nǐ 与 lǐ 声母不同（n 与 l），声调相同，意思是你的姐姐。"}], "explanations": {"理解": "正确答案。理解 lǐ jiě，意思是明白意思或想法。", "礼节": "jié（第二声）与 jiě（第三声）声调不同，意思是礼节。", "历届": "lì jiè 两个音节的声调都与 lǐ jiě 不同，意思是历次届别。", "你姐": "nǐ 与 lǐ 声母不同（n 与 l），声调相同，意思是你的姐姐。"}, "sentence_index": null, "correct_answer": "理解"}, "level_3": {"options": [{"text": "理解", "is_correct": true, "explanation": "“理解”指明白对方的意思，与“老师说得很慢”“我能”相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，与“老师说得很慢”的语境不合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与听讲的语境无关，“我能游泳”接在句末句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”需要带具体的受事宾语，“我能修理”后面没有对象，句意也不通。"}], "explanations": {"理解": "“理解”指明白对方的意思，与“老师说得很慢”“我能”相符。", "拒绝": "语义：“拒绝”表示不接受，与“老师说得很慢”的语境不合。", "游泳": "语义：“游泳”与听讲的语境无关，“我能游泳”接在句末句意不通。", "修理": "配价：“修理”需要带具体的受事宾语，“我能修理”后面没有对象，句意也不通。"}, "sentence_index": 0, "correct_answer": "理解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我理解他的电话号码。", "explanation": "这里应该用〈知道〉。理解侧重明白意思或想法，电话号码这类具体信息要说知道。"}, {"text": "工人正在理解那座房子。", "explanation": "这里应该用〈修理〉。理解用于意思、想法，修理用于房屋、机器等实物。"}, {"text": "妈妈每天理解全家的饭。", "explanation": "这里应该用〈煮〉。理解不能作用于食物，做饭要说煮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理解", "is_correct": true, "explanation": "“理解”指明白句中的意思或道理，与“孩子还不”“大人的工作”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃大人的工作”。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：“生产”的宾语应是产品，工作不能被生产。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是咬合的动作，与“不理解”的意思毫不相关。"}], "explanations": {"理解": "“理解”指明白句中的意思或道理，与“孩子还不”“大人的工作”相符。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃大人的工作”。", "生产": "搭配：“生产”的宾语应是产品，工作不能被生产。", "咬": "语义：“咬”是咬合的动作，与“不理解”的意思毫不相关。"}, "sentence_index": 6, "correct_answer": "理解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天理解房间。", "explanation": "这里应该用〈打扫〉。理解用于意思或想法，清理房间要说打扫。"}, {"text": "我的胃能理解食物。", "explanation": "这里应该用〈消化〉。理解用于意思、想法，食物要说消化。"}, {"text": "我每天理解花。", "explanation": "这里应该用〈浇〉。理解不能用于植物，给花供水要说浇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子理解了很慢。", "corrected_sentence": "这个孩子理解得很慢。", "error_description": "错误在于“了”与程度补语“很慢”不能同用。“理解”后接程度补语要用“得”，应说“理解得很慢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈终于理解了过孩子的心情。", "corrected_sentence": "妈妈终于理解了孩子的心情。", "error_description": "错误在于“了”和“过”不能叠用于同一动词。“终于”表示动作达成，应只用“了”，应说“妈妈终于理解了孩子的心情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
