INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21964, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "音乐创作就是做一首新歌或新曲子。", "primary_collocate": null, "pronunciation": "yīn yuè chuàng zuò", "ipa": "in˥ ɥe˥˩ ʈʂʰuɑŋ˥˩ tsuo˥˩", "syllable_count": 4, "sentences": [{"text": "周末他在家里忙着音乐创作。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐创作就是写出新的歌。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友想学音乐创作。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐创作让她每天都很开心。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的音乐创作很成功。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学生也可以尝试音乐创作。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐创作前，他先想好了歌名。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手机软件学习音乐创作。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的第一次音乐创作是一首生日歌。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到雨声，他有了音乐创作的想法。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "音樂創作", "label": "繁体"}, {"form": "音乐创作人", "label": "复合"}], "register": "中性", "sense_fingerprint": "写出新歌或新曲子（通俗说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f95e5d-4e87-424f-8121-0527036d276a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21964, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音乐创作", "is_correct": true, "explanation": "“忙着”后面可以接一件要做的事，“音乐创作”是可以动手去做的活动，符合句意。"}, {"text": "钢琴", "is_correct": false, "explanation": "配价：“忙着”要求后接动作，钢琴是乐器，不能直接作“忙”的对象。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被人“忙着”去做，句意不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海是自然景观，不能让人“忙着”去做。"}], "explanations": {"音乐创作": "“忙着”后面可以接一件要做的事，“音乐创作”是可以动手去做的活动，符合句意。", "钢琴": "配价：“忙着”要求后接动作，钢琴是乐器，不能直接作“忙”的对象。", "天气": "语义：天气不能被人“忙着”去做，句意不通。", "大海": "语义：大海是自然景观，不能让人“忙着”去做。"}, "sentence_index": 0, "correct_answer": "音乐创作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位出色的音乐创作。", "explanation": "这里应该用〈音乐创作人〉。音乐创作指写歌的活动，指做这件事的人要用“音乐创作人”。"}, {"text": "他花了三年时间音乐创作这篇论文。", "explanation": "这里应该用〈撰写〉。音乐创作指写歌、作曲的活动，写论文要用“撰写”，不能用“音乐创作”。"}, {"text": "她每天在画布上进行音乐创作。", "explanation": "这里应该用〈绘画创作〉。在画布上完成的是绘画，音乐创作只限于音乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音乐创作", "is_correct": true, "explanation": "“音乐创作前”指写歌之前的时间，后文“先想好了歌名”与之相符。"}, {"text": "包子", "is_correct": false, "explanation": "语义：“包子前”不能表示一件事之前的时间，与“先想好了歌名”也无关。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：“友谊”不是可作时间参照的事件，也不指位置，与“先想好了歌名”无关，句意不通。"}, {"text": "勇气", "is_correct": false, "explanation": "语义：“勇气”不是可作时间参照的事件，也不指位置，句意不通。"}], "explanations": {"音乐创作": "“音乐创作前”指写歌之前的时间，后文“先想好了歌名”与之相符。", "包子": "语义：“包子前”不能表示一件事之前的时间，与“先想好了歌名”也无关。", "友谊": "语义：“友谊”不是可作时间参照的事件，也不指位置，与“先想好了歌名”无关，句意不通。", "勇气": "语义：“勇气”不是可作时间参照的事件，也不指位置，句意不通。"}, "sentence_index": 6, "correct_answer": "音乐创作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上在操场上音乐创作十圈，然后回家吃早饭。", "explanation": "这里应该用〈跑〉。音乐创作指写歌，绕操场跑十圈要用“跑”，不能用于体育锻炼。"}, {"text": "这位老师每周音乐创作两次课，每次一小时。", "explanation": "这里应该用〈讲课〉。音乐创作指写歌，不是讲课，给学生讲课要用“讲课”。"}, {"text": "妈妈在厨房里音乐创作午饭，很快就做好了。", "explanation": "这里应该用〈烹饪〉。音乐创作的对象是音乐，不能用于做饭，做饭要用“烹饪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把音乐创作用了一周。", "corrected_sentence": "这次音乐创作用了一周。", "error_description": "量词错误：“把”用于有柄的物品，“音乐创作”指一次写歌的过程，应该用量词“次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她去年做过音乐创作过。", "corrected_sentence": "她去年做过音乐创作。", "error_description": "时态错误：“做过”已经带了表示经历的“过”，“音乐创作”后面不能再加“过”，应说“她去年做过音乐创作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
