INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21966, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用语言或动作说出自己的想法。", "primary_collocate": null, "pronunciation": "biǎo dá", "ipa": "pjɑʊ˨˩˦ ta˧˥", "syllable_count": 2, "sentences": [{"text": "他不会用英语表达自己的想法。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子常用哭来表达不高兴。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想对你表达我的谢意。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用一首歌表达了对妈妈的爱。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不会说中文，只好用手势表达。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时，大家都要表达自己的意见。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很少表达自己的感情。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词很难用中文表达清楚。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师希望学生用简单的话表达看法。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "画家用颜色表达心里的感受。", "target_word": "表达", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "表达了", "label": "完成体"}, {"form": "表达过", "label": "经历体"}, {"form": "表达能力", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用语言或动作说出想法感情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93f1010e-ee55-4e33-9cf5-8af6804f420b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表达", "is_correct": true, "explanation": "正确：“表达”指用语言说出自己的想法，与句意相符。"}, {"text": "分泌", "is_correct": false, "explanation": "搭配：“分泌”的宾语是汗液、激素等物质，不能说分泌想法。"}, {"text": "冲洗", "is_correct": false, "explanation": "搭配：“冲洗”用于照片、杯子等，不能说冲洗想法。"}, {"text": "发射", "is_correct": false, "explanation": "语义：“发射”指射出物体或信号，与用英语说出想法无关。"}], "explanations": {"表达": "正确：“表达”指用语言说出自己的想法，与句意相符。", "分泌": "搭配：“分泌”的宾语是汗液、激素等物质，不能说分泌想法。", "冲洗": "搭配：“冲洗”用于照片、杯子等，不能说冲洗想法。", "发射": "语义：“发射”指射出物体或信号，与用英语说出想法无关。"}, "sentence_index": 0, "correct_answer": "表达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的进步表达在成绩上。", "explanation": "这里应该用〈表现〉。表达指用语言或动作说出想法、感情，进步体现在成绩上，应说表现。"}, {"text": "仪表盘表达了油量。", "explanation": "这里应该用〈显示〉。表达说的是想法或感情，油量是数值，仪表盘显示油量应说显示。"}, {"text": "这个秤能表达十斤的重量。", "explanation": "这里应该用〈称〉。表达指说出想法或感情，重量应当用秤来称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表达", "is_correct": true, "explanation": "正确：句中说的是说出自己的感情，符合“表达”的意思。"}, {"text": "运输", "is_correct": false, "explanation": "语义：“运输”指搬运货物，不能用于说出感情。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：“粉刷”的对象是墙面等，不能说粉刷感情。"}, {"text": "扫描", "is_correct": false, "explanation": "语义：“扫描”指用仪器读取图像或信息，与说出感情无关。"}], "explanations": {"表达": "正确：句中说的是说出自己的感情，符合“表达”的意思。", "运输": "语义：“运输”指搬运货物，不能用于说出感情。", "粉刷": "搭配：“粉刷”的对象是墙面等，不能说粉刷感情。", "扫描": "语义：“扫描”指用仪器读取图像或信息，与说出感情无关。"}, "sentence_index": 6, "correct_answer": "表达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会计表达了每天的收入。", "explanation": "这里应该用〈计算〉。表达指说出想法或感情，收入这类数字需要计算，不能说表达。"}, {"text": "这台机器能表达三百度的温度。", "explanation": "这里应该用〈测量〉。表达指说出想法或感情，温度要用仪器测量。"}, {"text": "工程师表达了城市的地图。", "explanation": "这里应该用〈绘制〉。表达指说出想法或感情，地图应说绘制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很会表达了自己的感受。", "corrected_sentence": "她很会表达自己的感受。", "error_description": "错误形式是“很会表达了”，正确形式是“很会表达”。“很会”表示习惯性的能力，不能与表示完成的“了”同用，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从不表达过不满。", "corrected_sentence": "她从没表达过不满。", "error_description": "错误形式是“从不……过”，正确形式是“从没……过”。“从不”表示习惯性的否定，不能与表示经历的“过”同用；经历的否定应说“从没……过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21970, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "肤浅", "is_correct": true, "explanation": "正确。“深刻”与“肤浅”是反义词，指触及本质与停留在表面相对。"}, {"text": "平坦", "is_correct": false, "explanation": "与“深刻”没有反义关系，只是同为形容词。"}, {"text": "明亮", "is_correct": false, "explanation": "与“深刻”没有反义关系，只是同为形容词。"}, {"text": "湿润", "is_correct": false, "explanation": "与“深刻”没有反义关系，只是同为形容词。"}], "correct_answer": "肤浅", "explanations": {"肤浅": "正确。“深刻”与“肤浅”是反义词，指触及本质与停留在表面相对。", "平坦": "与“深刻”没有反义关系，只是同为形容词。", "明亮": "与“深刻”没有反义关系，只是同为形容词。", "湿润": "与“深刻”没有反义关系，只是同为形容词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
