INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21970, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（印象、道理、认识等）触及本质，给人很深的感受。", "primary_collocate": null, "pronunciation": "shēn kè", "ipa": "ʂən˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这次旅行给我留下了深刻的印象。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的意义很深刻，值得想一想。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个问题的理解非常深刻。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话让我印象深刻。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次失败的教训太深刻了，我再也不会忘。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写得很深刻，读完让人想很久。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了一个深刻的道理，大家都点头。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影对生活的看法很深刻。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过这件事，我对朋友的意义有了更深刻的认识。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话不多，但是每句都很深刻。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深刻地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "形容词，指印象、道理、认识等触及本质、给人很深的感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1a16da-10f9-4386-9fa4-b1d4f0773c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21970, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深刻", "is_correct": true, "explanation": "正确。“留下了深刻的印象”是常用说法，指印象很深、触及本质。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”描述形状，不能用来形容印象的深浅。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，印象不能是咸的，句子不通。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：“印象”一般不跟“湿”搭配，“湿的印象”不是习惯说法。"}], "explanations": {"深刻": "正确。“留下了深刻的印象”是常用说法，指印象很深、触及本质。", "圆": "语义：“圆”描述形状，不能用来形容印象的深浅。", "咸": "语义：“咸”形容味道，印象不能是咸的，句子不通。", "湿": "搭配：“印象”一般不跟“湿”搭配，“湿的印象”不是习惯说法。"}, "sentence_index": 0, "correct_answer": "深刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生说他的病情很深刻。", "explanation": "这里应该用〈严重〉。“深刻”用于印象、道理，形容病情这类情况要用“严重”。"}, {"text": "这所学校有深刻的教学基础。", "explanation": "这里应该用〈深厚〉。“深刻”指触及本质、给人很深的感受，“基础”要用“深厚”。"}, {"text": "这座山非常深刻，爬起来很累。", "explanation": "这里应该用〈高〉。“深刻”用于印象、道理，形容山的高低要用“高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21970, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深刻", "is_correct": true, "explanation": "正确。“一个深刻的道理”是常见说法，指道理让人感觉很有深度。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：“雪白”形容颜色，道理没有颜色，句子不通。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音，不能用来修饰道理。"}, {"text": "软绵绵", "is_correct": false, "explanation": "搭配：“软绵绵”形容质地或状态，“道理”不能这样形容。"}], "explanations": {"深刻": "正确。“一个深刻的道理”是常见说法，指道理让人感觉很有深度。", "雪白": "语义：“雪白”形容颜色，道理没有颜色，句子不通。", "响亮": "语义：“响亮”形容声音，不能用来修饰道理。", "软绵绵": "搭配：“软绵绵”形容质地或状态，“道理”不能这样形容。"}, "sentence_index": 6, "correct_answer": "深刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他心里有一种深刻的负担。", "explanation": "这里应该用〈沉重〉。“深刻”用于印象、道理，负担、压力这类感受要用“沉重”。"}, {"text": "他的声音很深刻，大家都听得清楚。", "explanation": "这里应该用〈深沉〉。“深刻”用于道理、印象，声音、性格要用“深沉”。"}, {"text": "我们等了一段深刻的时间。", "explanation": "这里应该用〈漫长〉。“深刻”不用来形容时间的长短，形容时间要用“漫长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书的道理是深刻，值得反复读。", "corrected_sentence": "这本书的道理很深刻，值得反复读。", "error_description": "形容词“深刻”作谓语时前面要加程度副词“很”，应说“很深刻”；用“是”接形容词、不带“的”，不符合汉语习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次讨论让我对环境问题有了更深刻得认识。", "corrected_sentence": "这次讨论让我对环境问题有了更深刻的认识。", "error_description": "修饰名词“认识”时，形容词后应用结构助词“的”，说“更深刻的认识”；“得”用于补语，这里用“得”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
