INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21974, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电脑里用的程序。", "primary_collocate": null, "pronunciation": "ruǎn jiàn", "ipa": "ʐwan˨˩˦ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我的电脑里有很多软件。", "target_word": "软件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件可以帮你学英语。", "target_word": "软件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先下载这个软件。", "target_word": "软件", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个软件太旧了，要更新。", "target_word": "软件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他会用这个软件做视频。", "target_word": "软件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机上的软件越来越多。", "target_word": "软件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件免费，也很好用。", "target_word": "软件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们用新软件画画。", "target_word": "软件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "软件坏了，电脑打不开。", "target_word": "软件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件能把中文翻译成英文。", "target_word": "软件", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "款", "label": "量词"}, {"form": "软件公司", "label": "复合"}], "register": "中性", "sense_fingerprint": "在电脑或手机上运行的程序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa75729c-4fdb-4353-ab48-5298e7732270') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21974, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "软件", "is_correct": true, "explanation": "正确：软件（ruǎn jiàn），电脑里用的程序。"}, {"text": "远见", "is_correct": false, "explanation": "远见（yuǎn jiàn），指对未来的看法。ruǎn 与 yuǎn 声母不同（r 与 y），意思不是程序。"}, {"text": "软线", "is_correct": false, "explanation": "软线（ruǎn xiàn），指柔软的电线。jiàn 与 xiàn 声母不同（j 与 x），意思不同。"}, {"text": "选件", "is_correct": false, "explanation": "选件（xuǎn jiàn），指可以挑选的配件。ruǎn 与 xuǎn 声母不同（r 与 x），意思是配件。"}], "explanations": {"软件": "正确：软件（ruǎn jiàn），电脑里用的程序。", "远见": "远见（yuǎn jiàn），指对未来的看法。ruǎn 与 yuǎn 声母不同（r 与 y），意思不是程序。", "软线": "软线（ruǎn xiàn），指柔软的电线。jiàn 与 xiàn 声母不同（j 与 x），意思不同。", "选件": "选件（xuǎn jiàn），指可以挑选的配件。ruǎn 与 xuǎn 声母不同（r 与 x），意思是配件。"}, "sentence_index": null, "correct_answer": "软件"}, "level_3": {"options": [{"text": "软件", "is_correct": true, "explanation": "正确：“我的电脑里有很多软件”，软件就是电脑里的程序。"}, {"text": "水果", "is_correct": false, "explanation": "语义：电脑里不会有水果，句子不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“很多”不修饰“价格”，电脑里也不会有价格。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不能放在电脑里，与语境不符。"}], "explanations": {"软件": "正确：“我的电脑里有很多软件”，软件就是电脑里的程序。", "水果": "语义：电脑里不会有水果，句子不通。", "价格": "搭配：“很多”不修饰“价格”，电脑里也不会有价格。", "饼干": "语义：饼干不能放在电脑里，与语境不符。"}, "sentence_index": 0, "correct_answer": "软件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每天要喝一杯软件。", "explanation": "这里不是软件的用法：这里把软件当成了饮料，软件是电脑里用的程序，不能喝。"}, {"text": "这首歌的软件很好听。", "explanation": "这里应该用〈旋律〉。软件指电脑程序，不能指歌曲本身。"}, {"text": "这个晚会的软件很精彩。", "explanation": "这里应该用〈节目〉。晚会上表演的是节目，软件是电脑里用的程序，不能用来指表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "软件", "is_correct": true, "explanation": "正确：“这个软件免费，也很好用”，软件可以免费且好用。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“好用”只用于物品，不能用来形容老师。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能说“免费，也很好用”。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是可以“使用”的东西，与语境不符。"}], "explanations": {"软件": "正确：“这个软件免费，也很好用”，软件可以免费且好用。", "老师": "搭配：“好用”只用于物品，不能用来形容老师。", "蛋糕": "语义：蛋糕是食物，不能说“免费，也很好用”。", "面包": "语义：面包是食物，不是可以“使用”的东西，与语境不符。"}, "sentence_index": 6, "correct_answer": "软件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的软件很漂亮。", "explanation": "这里应该用〈款式〉。软件指电脑里用的程序，不能用来形容衣服的样子。"}, {"text": "这位作家的软件很感人。", "explanation": "这里应该用〈作品〉。感人的是作品，软件是电脑里用的程序，不能用来指作家写的东西。"}, {"text": "这部电影的软件演得很好。", "explanation": "这里应该用〈演员〉。演得好的是演员，软件是电脑里用的程序，不能表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台软件适合初学者使用。", "corrected_sentence": "这款软件适合初学者使用。", "error_description": "量词错误：“软件”应用量词“款”或“个”，“台”用于机器，应说“这款软件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司以前吃过软件。", "corrected_sentence": "我们公司以前买过软件。", "error_description": "搭配错误：“吃”的对象不能是软件，应说“买过软件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
