INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "越过河流、山脉、国界等，从一边到达另一边。", "primary_collocate": null, "pronunciation": "kuà yuè", "ipa": "kʰua⁵¹ ɥe⁵¹", "syllable_count": 2, "sentences": [{"text": "这座桥跨越了一条大河。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机跨越大海,飞到了另一个国家。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们跨越山河来看我。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跨越了那条小河，走到了对岸。", "target_word": "跨越", "complexity_tier": "T3", "furigana": "tā kuà yuè le nà tiáo xiǎo hé, zǒu dào le duì àn.", "sentence_source": "generated"}, {"text": "这条铁路跨越了三个省。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跨越千山万水,回到了家乡。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车跨越国界,开往北京。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座长桥跨越了整个海湾。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条高速公路跨越了整个山区。", "target_word": "跨越", "complexity_tier": "T3", "furigana": "zhè tiáo gāo sù gōng lù kuà yuè le zhěng gè shān qū.", "sentence_source": "generated"}, {"text": "他想跨越这片沙漠,去找朋友。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跨越了", "label": "体标"}, {"form": "跨越过", "label": "体标"}], "register": "中性", "sense_fingerprint": "越过某地到达另一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fef3691-c05f-4979-b766-4af9a742d3ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跨越", "is_correct": true, "explanation": "“跨越”指从河的一边到另一边，“这座桥跨越了一条大河”成立。"}, {"text": "渡", "is_correct": false, "explanation": "语义：“渡”是乘船摆渡，桥不能“渡”河。"}, {"text": "环绕", "is_correct": false, "explanation": "语义：“环绕”是围着转，桥不是围着河转。"}, {"text": "挖掘", "is_correct": false, "explanation": "语义：“挖掘”是挖土，桥不能挖掘河流，句意不通。"}], "explanations": {"跨越": "“跨越”指从河的一边到另一边，“这座桥跨越了一条大河”成立。", "渡": "语义：“渡”是乘船摆渡，桥不能“渡”河。", "环绕": "语义：“环绕”是围着转，桥不是围着河转。", "挖掘": "语义：“挖掘”是挖土，桥不能挖掘河流，句意不通。"}, "sentence_index": 0, "correct_answer": "跨越"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跨越了所有同学，考了第一名。", "explanation": "这里应该用〈超越〉。超过别人用“超越”；“跨越”指从一端到另一端，不能用来比较名次。"}, {"text": "今年的产量跨越了去年。", "explanation": "这里应该用〈超过〉。数量比较用“超过”；“跨越”指空间上从一边到另一边。"}, {"text": "他跨越了一碗饭。", "explanation": "这里应该用〈吃〉。吃饭要用“吃”；“跨越”不能接食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跨越", "is_correct": true, "explanation": "“跨越”指越过国界这样的界限，“火车跨越国界，开往北京”成立。"}, {"text": "守卫", "is_correct": false, "explanation": "语义：“守卫”是防守保护，火车不守卫国界，句意不通。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”的对象是道路、桥梁，不说“修国界”。"}, {"text": "划定", "is_correct": false, "explanation": "语义：“划定”是划出界限，火车不能划定国界。"}], "explanations": {"跨越": "“跨越”指越过国界这样的界限，“火车跨越国界，开往北京”成立。", "守卫": "语义：“守卫”是防守保护，火车不守卫国界，句意不通。", "修": "搭配：“修”的对象是道路、桥梁，不说“修国界”。", "划定": "语义：“划定”是划出界限，火车不能划定国界。"}, "sentence_index": 6, "correct_answer": "跨越"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她跨越了一双新鞋。", "explanation": "这里应该用〈穿〉。穿鞋要用“穿”；“跨越”不能接鞋子。"}, {"text": "他跨越了一杯茶。", "explanation": "这里应该用〈喝〉。喝茶要用“喝”；“跨越”指从一边越到另一边，不能接饮品。"}, {"text": "他跨越了一个秘密。", "explanation": "这里应该用〈发现〉。发现秘密用“发现”；“跨越”指越过空间或界限，不能用于秘密。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跨越了到对岸。", "corrected_sentence": "他跨越到了对岸。", "error_description": "错误：“了”放在了“到”的前面。正确应为“跨越到了对岸”，结果补语“到”后面才接“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跨越很快，一下子就到了对岸。", "corrected_sentence": "他跨越得很快，一下子就到了对岸。", "error_description": "错误：“跨越”后漏了“得”。带状态补语时要用“得”连接，正确应为“跨越得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
