INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21980, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一段时间。", "primary_collocate": null, "pronunciation": "shí qī", "ipa": "ʂɨ³⁵ tɕʰi⁵⁵", "syllable_count": 2, "sentences": [{"text": "考试时期，图书馆里人很多。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个时期公司特别忙。", "target_word": "时期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天是游泳的好时期。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个时期的水果最便宜。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一年中这个时期最冷。", "target_word": "时期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "毕业前的时期，大家都很忙。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那一时期他住在上海。", "target_word": "时期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春节时期，火车票很难买。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在这个时期学会了开车。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个时期是旅游旺季，酒店很贵。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "泛指一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84ffd41-c5c9-458e-937c-7ea4003810ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21980, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时期", "is_correct": true, "explanation": "正确答案，指一段时间，与听到的音相符。"}, {"text": "食器", "is_correct": false, "explanation": "声调不同：第二音节 qì（第四声）与 qī（第一声），意思是饮食用具。"}, {"text": "时机", "is_correct": false, "explanation": "第二音节声母不同：jī 与 qī，意思是合适的机会。"}, {"text": "时区", "is_correct": false, "explanation": "第二音节韵母不同：qū（ü）与 qī（i），意思是时区。"}], "explanations": {"时期": "正确答案，指一段时间，与听到的音相符。", "食器": "声调不同：第二音节 qì（第四声）与 qī（第一声），意思是饮食用具。", "时机": "第二音节声母不同：jī 与 qī，意思是合适的机会。", "时区": "第二音节韵母不同：qū（ü）与 qī（i），意思是时区。"}, "sentence_index": null, "correct_answer": "时期"}, "level_3": {"options": [{"text": "时期", "is_correct": true, "explanation": "语义与搭配都正确：“考试时期”指考试这段时间，与“图书馆里人很多”相符。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”指坐的地方，不指一段时间，“考试座位”与句意不符。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”指考试结果，不指时间段，句子不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“考试”不能与“年龄”组成词组，“考试年龄”不成立。"}], "explanations": {"时期": "语义与搭配都正确：“考试时期”指考试这段时间，与“图书馆里人很多”相符。", "座位": "语义：“座位”指坐的地方，不指一段时间，“考试座位”与句意不符。", "成绩": "语义：“成绩”指考试结果，不指时间段，句子不通。", "年龄": "搭配：“考试”不能与“年龄”组成词组，“考试年龄”不成立。"}, "sentence_index": 0, "correct_answer": "时期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑完这段路只用了三分钟的时期。", "explanation": "这里应该用〈时间〉。时期指一段时间，具体的时长（三分钟）要用“时间”。"}, {"text": "现在是八点整的时期了，大家快进去。", "explanation": "这里应该用〈时刻〉。八点整指具体的时间点，时期指一段时间，不能用来指某一时刻。"}, {"text": "做饭的时期别进厨房。", "explanation": "这里应该用〈时候〉。表示某件事发生的时点用“时候”，时期指较长的一段时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4659c7f3-0c52-4d58-a112-0ffe99cd90b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21980, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时期", "is_correct": true, "explanation": "正确答案，指一段时间，与听到的音相符。"}, {"text": "食器", "is_correct": false, "explanation": "声调不同：第二音节 qì（第四声）与 qī（第一声），意思是饮食用具。"}, {"text": "时气", "is_correct": false, "explanation": "声调不同：第二音节 qì（第四声）与 qī（第一声），意思是时令气候，或指流行病。"}, {"text": "石器", "is_correct": false, "explanation": "声调不同：qì（第四声）与 qī（第一声），意思是石制的工具。"}], "explanations": {"时期": "正确答案，指一段时间，与听到的音相符。", "食器": "声调不同：第二音节 qì（第四声）与 qī（第一声），意思是饮食用具。", "时气": "声调不同：第二音节 qì（第四声）与 qī（第一声），意思是时令气候，或指流行病。", "石器": "声调不同：qì（第四声）与 qī（第一声），意思是石制的工具。"}, "sentence_index": null, "correct_answer": "时期"}, "level_3": {"options": [{"text": "时期", "is_correct": true, "explanation": "语义正确：“那一时期”指那段时间，与后句“住在上海”相符。"}, {"text": "职业", "is_correct": false, "explanation": "语义：“职业”不指一段时间，“那一职业他住在上海”句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不指时间，“那一颜色”与句子无法连贯。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“那一”通常修饰时段，不能接“天气”组成可接受的说法。"}], "explanations": {"时期": "语义正确：“那一时期”指那段时间，与后句“住在上海”相符。", "职业": "语义：“职业”不指一段时间，“那一职业他住在上海”句意不通。", "颜色": "语义：“颜色”不指时间，“那一颜色”与句子无法连贯。", "天气": "搭配：“那一”通常修饰时段，不能接“天气”组成可接受的说法。"}, "sentence_index": 6, "correct_answer": "时期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的时期定在三月十五号。", "explanation": "这里应该用〈日期〉。定在具体某一天要用“日期”，时期指一段时间，不能这样指定某一天。"}, {"text": "他的时期比我大五岁。", "explanation": "这里应该用〈年龄〉。比较人的岁数要用“年龄”，时期指一段时间，不能用来比较岁数。"}, {"text": "明天的时期很满。", "explanation": "这里应该用〈日程〉。“明天的日程很满”指安排的事情多，时期指一段时间，不能说时期很满。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4659c7f3-0c52-4d58-a112-0ffe99cd90b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在那个时期的学会了游泳。", "corrected_sentence": "他在那个时期学会了游泳。", "error_description": "“的”误插在介词结构“在那个时期”与动词“学会”之间，破坏了“在……学会”的结构，应删去“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4659c7f3-0c52-4d58-a112-0ffe99cd90b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只时期酒店的房价很高。", "corrected_sentence": "这段时期酒店的房价很高。", "error_description": "量词错误：“只”用于动物或成对的物件，时期应搭配“段”，应改为“这段时期”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4659c7f3-0c52-4d58-a112-0ffe99cd90b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
