INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21982, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很远很远的古代，很久很久以前。", "primary_collocate": null, "pronunciation": "yuǎn gǔ", "ipa": "ɥæn˨˩˦ ku˨˩˦", "syllable_count": 2, "sentences": [{"text": "远古的人住在树上，靠采集和狩猎为生。", "target_word": "远古", "complexity_tier": "T3", "furigana": "yuǎn gǔ de rén zhù zài shù shàng, kào cǎi jí hé shòu liè wéi shēng", "sentence_source": "generated"}, {"text": "这个故事发生在远古的草原上。", "target_word": "远古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷讲了一个远古的故事。", "target_word": "远古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远古的夜晚，人们靠火取暖。", "target_word": "远古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们喜欢听远古的传说。", "target_word": "远古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远古的海边住着一群渔民。", "target_word": "远古", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画画的是远古的生活。", "target_word": "远古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在远古，人们还不会写字。", "target_word": "远古", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们在山洞里看到了远古的画。", "target_word": "远古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远古的冬天特别冷，人们要生火。", "target_word": "远古", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "遠古", "label": "繁体"}, {"form": "远古时代", "label": "复合"}], "register": "书面", "sense_fingerprint": "很久很久以前的古代，常用于故事、传说的口吻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e003bea1-9a51-40cb-91ca-bdd0a7fd19d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远古", "is_correct": true, "explanation": "作定语修饰“人”，指很久很久以前的古代，与“住在树上，靠采集和狩猎为生”相符。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市里的人不会住在树上靠狩猎为生，与句中的生活方式矛盾。"}, {"text": "电子", "is_correct": false, "explanation": "搭配：“电子”不指时代，不能修饰“人”来表示所处的时期。"}, {"text": "老古董", "is_correct": false, "explanation": "语域：“老古董”是口语且带贬义，与故事的叙述口吻不合。"}], "explanations": {"远古": "作定语修饰“人”，指很久很久以前的古代，与“住在树上，靠采集和狩猎为生”相符。", "城市": "语义：城市里的人不会住在树上靠狩猎为生，与句中的生活方式矛盾。", "电子": "搭配：“电子”不指时代，不能修饰“人”来表示所处的时期。", "老古董": "语域：“老古董”是口语且带贬义，与故事的叙述口吻不合。"}, "sentence_index": 0, "correct_answer": "远古"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "远古的这座房子刚装修好。", "explanation": "这里应该用〈新〉。远古指很久以前的时代，不能修饰刚装修好的房子，应说〈新〉。"}, {"text": "我们下个月在远古结婚。", "explanation": "这里应该用〈将来〉。远古指很久以前，不能指即将到来的时间，应说〈将来〉。"}, {"text": "我的远古过得很开心。", "explanation": "这里应该用〈童年〉。远古指遥远的古代，不能用来指个人的一段时期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远古", "is_correct": true, "explanation": "作定语修饰“生活”，指很久很久以前的时代，与“这幅画画的是……”的内容相符。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“电影”不指时代，不能用来修饰“生活”表示时期。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“电脑”不指时代，不能修饰“生活”表示所处的时期。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“石头”没有生活可画，“石头的生活”不成话。"}], "explanations": {"远古": "作定语修饰“生活”，指很久很久以前的时代，与“这幅画画的是……”的内容相符。", "电影": "搭配：“电影”不指时代，不能用来修饰“生活”表示时期。", "电脑": "搭配：“电脑”不指时代，不能修饰“生活”表示所处的时期。", "石头": "搭配：“石头”没有生活可画，“石头的生活”不成话。"}, "sentence_index": 6, "correct_answer": "远古"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她远古就考上了大学。", "explanation": "这里应该用〈去年〉。远古指很久很久以前，表示近期的时间应说〈去年〉。"}, {"text": "这次比赛是远古举行的。", "explanation": "这里应该用〈上周〉。远古指遥远的古代，不能用来说最近举行的比赛，应说〈上周〉。"}, {"text": "今天是远古。", "explanation": "这里应该用〈星期五〉。远古指很久以前的时代，不能用来说今天是什么时候，应说〈星期五〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远古的草原上很远古。", "corrected_sentence": "远古的草原上很热闹。", "error_description": "错误：“远古”是名词，不能作“很”的谓语；应把谓语改为形容词“热闹”，写作“远古的草原上很热闹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "远古时间的人们很勤劳。", "corrected_sentence": "远古时代的人们很勤劳。", "error_description": "错误：“时间”指时长，不能说“远古时间”表示时代；应说“远古时代”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
