INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21992, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "眼睛看到东西的能力。", "primary_collocate": null, "pronunciation": "shì jué", "ipa": "ʂɻ̩⁵¹ tɕɥe³⁵", "syllable_count": 2, "sentences": [{"text": "人的视觉很重要。", "target_word": "视觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的视觉有问题,看不清黑板。", "target_word": "视觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫在晚上的视觉比人好。", "target_word": "视觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼睛受伤后,他的视觉变差了。", "target_word": "视觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的视觉常常不如年轻人。", "target_word": "视觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说她的视觉很正常。", "target_word": "视觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟的视觉非常好,能看到很远的东西。", "target_word": "视觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听觉和视觉都是我们了解世界的方法。", "target_word": "视觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间看手机会影响视觉。", "target_word": "视觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盲人没有视觉,但听觉很好。", "target_word": "视觉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "视觉艺术", "label": "复合"}], "register": "中性", "sense_fingerprint": "眼睛看见事物的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fef3691-c05f-4979-b766-4af9a742d3ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "视觉", "is_correct": true, "explanation": "视觉是眼睛看到东西的能力，“人的视觉很重要”成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不属于人的属性，不能说“人的天气”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”属于商品，不能说“人的价格”。"}, {"text": "库存", "is_correct": false, "explanation": "语义：库存指货物的存量，不能用来说人。"}], "explanations": {"视觉": "视觉是眼睛看到东西的能力，“人的视觉很重要”成立。", "天气": "语义：天气是自然现象，不属于人的属性，不能说“人的天气”。", "价格": "搭配：“价格”属于商品，不能说“人的价格”。", "库存": "语义：库存指货物的存量，不能用来说人。"}, "sentence_index": 0, "correct_answer": "视觉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生检查以后说，他的视觉是一点五。", "explanation": "这里应该用〈视力〉。视力可以用数值表示，如“一点五”；视觉指眼睛看东西的能力，不能说有几。"}, {"text": "这座山的视觉很好，站在山顶能看见整个城市。", "explanation": "这里应该用〈视野〉。视野指能看到的范围，形容山或场地的开阔要用“视野”；视觉是人或动物的感觉能力，不能用来形容山。"}, {"text": "他的视觉一直落在窗外的那棵树上。", "explanation": "这里应该用〈视线〉。“落在……上”搭配视线（眼睛望去的方向）；视觉是能力，不能“落在”某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视觉", "is_correct": true, "explanation": "视觉指眼睛看东西的能力，“能看到很远的东西”与之相符。"}, {"text": "听觉", "is_correct": false, "explanation": "语义：听觉是听声音的能力，与“能看到很远的东西”不符。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”说正常、偏高，不能说“非常好”。"}, {"text": "外形", "is_correct": false, "explanation": "体貌：“外形”指外观样子，与看到远处东西的能力无关。"}], "explanations": {"视觉": "视觉指眼睛看东西的能力，“能看到很远的东西”与之相符。", "听觉": "语义：听觉是听声音的能力，与“能看到很远的东西”不符。", "体温": "搭配：“体温”说正常、偏高，不能说“非常好”。", "外形": "体貌：“外形”指外观样子，与看到远处东西的能力无关。"}, "sentence_index": 6, "correct_answer": "视觉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "从老师的视觉看，这道题并不难。", "explanation": "这里应该用〈视角〉。“从……的视角”指观察问题的角度；视觉是眼睛看东西的能力，不指角度。"}, {"text": "他对这个计划的视觉很不错。", "explanation": "这里应该用〈感觉〉。对事物的主观感受用“感觉”；视觉是感官能力，不能用来评价一个计划。"}, {"text": "他的视觉很有道理。", "explanation": "这里应该用〈观点〉。“有道理”评价的是观点或说法；视觉是感官能力，不能评价是否有道理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他地视觉很好。", "corrected_sentence": "他的视觉很好。", "error_description": "错误：修饰名词“视觉”时应用“的”，不用“地”。“地”用于修饰动词或形容词。正确应为“他的视觉很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校这学期新开了一门视觉地艺术课。", "corrected_sentence": "学校这学期新开了一门视觉艺术课。", "error_description": "错误：复合词“视觉艺术”中间不能插入“地”。“地”用于修饰动词或形容词，“视觉”和“艺术”之间不需要任何助词。正确应为“视觉艺术课”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
