INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22018, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在东西上画个符号，让别人知道这是什么。", "primary_collocate": null, "pronunciation": "biāo jì", "ipa": "pjɑʊ˥˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "请你把这些箱子都标记一下。", "target_word": "标记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用红笔标记了自己的书。", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们标记出不懂的词。", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在地图上标记了回家的路。", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在每件衣服上标记了名字。", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先标记好杯子，再放进盒子。", "target_word": "标记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用蓝色的笔标记重点。", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人在树上标记要砍的地方。", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她给每个瓶子标记了日期。", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了不拿错伞，我标记了我的伞。", "target_word": "标记", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "标记了", "label": "体标"}, {"form": "标记着", "label": "体标"}, {"form": "标记过", "label": "体标"}, {"form": "標記", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在东西上画符号，让别人知道它是什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41a26d44-7f98-4c49-b04a-5d6ade43eede') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22018, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "标记", "is_correct": true, "explanation": "正确：标记（biāo jì），指在东西上做符号。"}, {"text": "标价", "is_correct": false, "explanation": "jià（第四声）与 jì（第四声）韵母不同，意思是价格。"}, {"text": "边际", "is_correct": false, "explanation": "biān 与 biāo 只有韵母不同，意思是边缘、界限。"}, {"text": "标界", "is_correct": false, "explanation": "jiè（第四声）与 jì（第四声）韵母不同，意思是划定界限。"}], "explanations": {"标记": "正确：标记（biāo jì），指在东西上做符号。", "标价": "jià（第四声）与 jì（第四声）韵母不同，意思是价格。", "边际": "biān 与 biāo 只有韵母不同，意思是边缘、界限。", "标界": "jiè（第四声）与 jì（第四声）韵母不同，意思是划定界限。"}, "sentence_index": null, "correct_answer": "标记"}, "level_3": {"options": [{"text": "标记", "is_correct": true, "explanation": "正确：此处指在箱子上做记号，便于辨认。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」指发出歌声，不能用于在箱子上做记号。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：「演奏」的对象是乐曲或乐器，不能与「箱子」搭配。"}, {"text": "朗读", "is_correct": false, "explanation": "语义：「朗读」指出声读文字，与箱子无关。"}], "explanations": {"标记": "正确：此处指在箱子上做记号，便于辨认。", "唱": "语义：「唱」指发出歌声，不能用于在箱子上做记号。", "演奏": "搭配：「演奏」的对象是乐曲或乐器，不能与「箱子」搭配。", "朗读": "语义：「朗读」指出声读文字，与箱子无关。"}, "sentence_index": 0, "correct_answer": "标记"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用相机标记了回家的路。", "explanation": "这里应该用〈拍摄〉。标记是在东西上画符号，不能用相机拍摄。"}, {"text": "他把地图上的字标记掉了。", "explanation": "这里应该用〈擦〉。标记是做记号，不表示把字去掉。"}, {"text": "他把这首歌标记得很好听。", "explanation": "这里应该用〈演唱〉。标记是在东西上做记号，不能用来形容歌曲好不好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4b651-7f3a-41ec-8236-07e431ba2109') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标记", "is_correct": true, "explanation": "正确：此处指用笔在重点上做记号。"}, {"text": "弹", "is_correct": false, "explanation": "搭配：「弹」多用于乐器或弹性物体，不能对「重点」做这个动作。"}, {"text": "吹", "is_correct": false, "explanation": "语义：「吹」指用气流推动，用笔不能「吹」重点。"}, {"text": "哼", "is_correct": false, "explanation": "语义：「哼」指轻声发声，与用笔做记号的动作不符。"}], "explanations": {"标记": "正确：此处指用笔在重点上做记号。", "弹": "搭配：「弹」多用于乐器或弹性物体，不能对「重点」做这个动作。", "吹": "语义：「吹」指用气流推动，用笔不能「吹」重点。", "哼": "语义：「哼」指轻声发声，与用笔做记号的动作不符。"}, "sentence_index": 6, "correct_answer": "标记"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把衣服标记干净了。", "explanation": "这里应该用〈洗〉。标记是做记号，不表示把衣服弄干净。"}, {"text": "老师标记完了今天的课。", "explanation": "这里应该用〈讲〉。标记是做记号，不表示讲授课程。"}, {"text": "他把桌子标记到了客厅。", "explanation": "这里应该用〈搬〉。标记是做记号，不表示移动物体的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4b651-7f3a-41ec-8236-07e431ba2109') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这些书都标记了好了。", "corrected_sentence": "我把这些书都标记好了。", "error_description": "「了」用多了：结果补语「好」之后只用一个「了」，应说「标记好了」，不能在「标记」后面又加「了」，说成「标记了好了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4b651-7f3a-41ec-8236-07e431ba2109') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他标记过过这条路。", "corrected_sentence": "他标记过这条路。", "error_description": "体貌标记重复：「过」只用一次，紧跟动词，应说「标记过这条路」，不能说「标记过过这条路」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4b651-7f3a-41ec-8236-07e431ba2109') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
