INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22020, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旋律就是一首歌里好听的声音，一个接一个地连起来。", "primary_collocate": null, "pronunciation": "xuán lǜ", "ipa": "ɕɥɛn˧˥ ly˥˩", "syllable_count": 2, "sentences": [{"text": "这首歌的旋律很好听，我天天都听。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这个旋律，每天都要听。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用口琴吹出了一段旋律。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个旋律我很熟，但是忘了歌名。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跟着旋律拍手。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里响起了熟悉的旋律。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的旋律简单，歌词也容易记。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很喜欢唱歌，常常自己写旋律。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他闭着眼睛听那段旋律。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个旋律太快了，我跟不上。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段旋律", "label": "量词"}, {"form": "主旋律", "label": "复合"}], "register": "中性", "sense_fingerprint": "一首歌里一个接一个连起来的好听声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41a26d44-7f98-4c49-b04a-5d6ade43eede') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22020, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旋律", "is_correct": true, "explanation": "正确：一首歌里好听的声音连成的线条。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」指钱数，不能用来形容歌的声音好听。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」指人或物的重量，与歌曲无关。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：「温度」不能与「好听」搭配。"}], "explanations": {"旋律": "正确：一首歌里好听的声音连成的线条。", "价格": "语义：「价格」指钱数，不能用来形容歌的声音好听。", "体重": "语义：「体重」指人或物的重量，与歌曲无关。", "温度": "搭配：「温度」不能与「好听」搭配。"}, "sentence_index": 0, "correct_answer": "旋律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这首歌的旋律，我很熟。", "explanation": "这里应该用〈歌手〉。旋律指一串音符，不指演唱的人。"}, {"text": "他的旋律很瘦，唱歌很好听。", "explanation": "这里应该用〈身材〉。旋律不能形容人的胖瘦，「旋律很瘦」不成立。"}, {"text": "这个旋律有二十页，我要慢慢看。", "explanation": "这里应该用〈乐谱〉。旋律指一串音符，不能用来计算页数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4b651-7f3a-41ec-8236-07e431ba2109') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旋律", "is_correct": true, "explanation": "正确：这首歌的音乐线条简单，容易记。"}, {"text": "作者", "is_correct": false, "explanation": "语义：「作者」指写作的人，不能用「简单」描述。"}, {"text": "地点", "is_correct": false, "explanation": "语义：「地点」指位置，与歌曲是否简单无关。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「颜色」不能用「简单」来形容歌曲。"}], "explanations": {"旋律": "正确：这首歌的音乐线条简单，容易记。", "作者": "语义：「作者」指写作的人，不能用「简单」描述。", "地点": "语义：「地点」指位置，与歌曲是否简单无关。", "颜色": "搭配：「颜色」不能用「简单」来形容歌曲。"}, "sentence_index": 6, "correct_answer": "旋律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的旋律很快。", "explanation": "这里应该用〈车速〉。旋律指音乐中的主线，不能形容车的速度。"}, {"text": "我的旋律很高，今天要去看医生。", "explanation": "这里应该用〈体温〉。旋律不指人身体的温度。"}, {"text": "这个旋律太小了，我看不清。", "explanation": "这里应该用〈字体〉。旋律不指文字的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4b651-7f3a-41ec-8236-07e431ba2109') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把这本旋律听熟了。", "corrected_sentence": "我已经把这段旋律听熟了。", "error_description": "量词错误：「旋律」应用量词「段」，「本」用于书册，不能修饰旋律。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4b651-7f3a-41ec-8236-07e431ba2109') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段很慢旋律让我想睡觉。", "corrected_sentence": "这段很慢的旋律让我想睡觉。", "error_description": "定语缺「的」：形容词带「很」作定语时要加「的」，应说「很慢的旋律」，不能说「很慢旋律」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4b651-7f3a-41ec-8236-07e431ba2109') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
