INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22022, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "意思是往某个方向去。", "primary_collocate": null, "pronunciation": "zǒu xiàng", "ipa": "tsou˨˩˦ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他慢慢走向门口。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩走向妈妈，笑着说话。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师走向黑板，写下了一个字。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起走向车站。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看见朋友，就走向朋友打招呼。", "target_word": "走向", "complexity_tier": "T3", "furigana": "tā kànjiàn péngyou jiù zǒuxiàng péngyou dǎ zhāohu", "sentence_source": "generated"}, {"text": "她把花放下，走向窗边。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗慢慢走向它的主人。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走向台前，拿起了话筒。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们高兴地走向学校。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走过马路，走向对面的商店。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "走向了", "label": "体标"}, {"form": "走向过", "label": "体标"}], "register": "中性", "sense_fingerprint": "迈步朝着某个地点或某个人走去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41a26d44-7f98-4c49-b04a-5d6ade43eede') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22022, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "走向", "is_correct": true, "explanation": "正确答案。走向 zǒu xiàng，指朝某个方向移动。"}, {"text": "奏响", "is_correct": false, "explanation": "zòu xiǎng（第四声、第三声）与 zǒu xiàng（第三声、第四声）声调不同，意思是演奏出响亮的声音。"}, {"text": "造像", "is_correct": false, "explanation": "zào（第四声）与 zǒu（第三声）韵母不同（ao 与 ou），意思是雕造的人像或佛像。"}, {"text": "走线", "is_correct": false, "explanation": "xiàn 与 xiàng 韵尾不同（n 与 ng），走线意思是布设线路。"}, {"text": "首相", "is_correct": false, "explanation": "shǒu 与 zǒu 只有声母不同（sh 与 z），xiàng 相同，意思是国家的行政首长。"}], "explanations": {"走向": "正确答案。走向 zǒu xiàng，指朝某个方向移动。", "奏响": "zòu xiǎng（第四声、第三声）与 zǒu xiàng（第三声、第四声）声调不同，意思是演奏出响亮的声音。", "造像": "zào（第四声）与 zǒu（第三声）韵母不同（ao 与 ou），意思是雕造的人像或佛像。", "走线": "xiàn 与 xiàng 韵尾不同（n 与 ng），走线意思是布设线路。", "首相": "shǒu 与 zǒu 只有声母不同（sh 与 z），xiàng 相同，意思是国家的行政首长。"}, "sentence_index": null, "correct_answer": "走向"}, "level_3": {"options": [{"text": "走向", "is_correct": true, "explanation": "正确答案。“走向门口”表示朝门口走去，与“慢慢”的动作相符。"}, {"text": "冲向", "is_correct": false, "explanation": "语义：“慢慢”与“冲”的动作速度相矛盾。"}, {"text": "进入", "is_correct": false, "explanation": "搭配：“进入”多接房间或场所，门口不是可以进入的空间。"}, {"text": "打开", "is_correct": false, "explanation": "配价：“打开”的宾语是“门”，不说“打开门口”。"}], "explanations": {"走向": "正确答案。“走向门口”表示朝门口走去，与“慢慢”的动作相符。", "冲向": "语义：“慢慢”与“冲”的动作速度相矛盾。", "进入": "搭配：“进入”多接房间或场所，门口不是可以进入的空间。", "打开": "配价：“打开”的宾语是“门”，不说“打开门口”。"}, "sentence_index": 0, "correct_answer": "走向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "箭头走向东方。", "explanation": "这里应该用〈指向〉。箭头指示方向用指向，走向是人或动物迈步前往某处，箭头不会走。"}, {"text": "小鸟走向天空。", "explanation": "这里应该用〈飞向〉。鸟在空中移动用飞，不用走。"}, {"text": "这扇窗户走向南。", "explanation": "这里应该用〈朝〉。窗户面对的方向用朝，走向是迈步前往某处的动作，窗户不会走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4b651-7f3a-41ec-8236-07e431ba2109') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走向", "is_correct": true, "explanation": "正确答案。“慢慢走向它的主人”表示小狗朝主人移动。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象多是动物或婴儿，不说喂主人。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”的对象是物品，不能修理一个人。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，与主人不相关。"}], "explanations": {"走向": "正确答案。“慢慢走向它的主人”表示小狗朝主人移动。", "喂": "搭配：“喂”的对象多是动物或婴儿，不说喂主人。", "修": "语义：“修”的对象是物品，不能修理一个人。", "煮": "语义：“煮”的对象是食物，与主人不相关。"}, "sentence_index": 6, "correct_answer": "走向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小鱼儿快快走向大海。", "explanation": "这里应该用〈游向〉。鱼在水中移动用游，不用走。"}, {"text": "石头走向山下。", "explanation": "这里应该用〈滚〉。石头没有腿，不能走，滚向低处用滚。"}, {"text": "小蛇悄悄走向草丛。", "explanation": "这里应该用〈爬向〉。蛇没有腿，移动用爬，不用走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4b651-7f3a-41ec-8236-07e431ba2109') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一步一步走向到大门。", "corrected_sentence": "他一步一步走向大门。", "error_description": "补语错误：“走向”已经表示朝某处走去，后面不能再加“到”，应为“走向大门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4b651-7f3a-41ec-8236-07e431ba2109') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小猫轻轻把窗边走向。", "corrected_sentence": "小猫轻轻走向了窗边。", "error_description": "把字句错误：“走向”是不及物动词，不能用“把”字引出受事宾语“窗边”，应说“走向了窗边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4b651-7f3a-41ec-8236-07e431ba2109') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
