INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22026, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "老师一边说，一边用手比画，把方法教给学生。", "primary_collocate": null, "pronunciation": "kǒu chuán xīn shòu", "ipa": "kʰoʊ˨˩˦ ʈʂʰwan˧˥ ɕin˥ ʂoʊ˥˩", "syllable_count": 4, "sentences": [{"text": "师父口传心授，徒弟认真地学。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一边讲一边比画，口传心授。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把刺绣的方法口传心授给孙女。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他口传心授，教会了学生拉二胡。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅在厨房里口传心授做菜的方法。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老艺人口传心授，把绝活教给徒弟。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有课本，老师只能口传心授。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟着奶奶学剪纸，奶奶口传心授。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练在球场上口传心授投篮技巧。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老木匠口传心授，一点一点教他。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "口傳心授", "label": "繁体"}], "register": "书面", "sense_fingerprint": "老师边说边比画，把方法教给学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a705c23-47ff-42bb-8ecb-59edb28e7400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22026, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口传心授", "is_correct": true, "explanation": "正确。指师傅边说边示范地传授，与“徒弟认真地学”相呼应。"}, {"text": "闭门自学", "is_correct": false, "explanation": "语义：“闭门自学”指无人指导，与“师父”的施教角色矛盾。"}, {"text": "默写", "is_correct": false, "explanation": "配价：“默写”需要宾语（默写什么），此处“师父默写”缺少宾语。"}, {"text": "大肆宣扬", "is_correct": false, "explanation": "语域：“大肆宣扬”带贬义，与平实的师徒教学叙述不符。"}], "explanations": {"口传心授": "正确。指师傅边说边示范地传授，与“徒弟认真地学”相呼应。", "闭门自学": "语义：“闭门自学”指无人指导，与“师父”的施教角色矛盾。", "默写": "配价：“默写”需要宾语（默写什么），此处“师父默写”缺少宾语。", "大肆宣扬": "语域：“大肆宣扬”带贬义，与平实的师徒教学叙述不符。"}, "sentence_index": 0, "correct_answer": "口传心授"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把方法口传心授在纸上，让大家传阅。", "explanation": "这里应该用〈写下〉。口传心授强调口头讲解与示范，不能写在纸上，与书面记录相反。"}, {"text": "他口传心授，把整本书都读完了。", "explanation": "这里应该用〈阅读〉。口传心授指老师边说边比画地教给学生，不能用来形容自己读书。"}, {"text": "他口传心授，教我做人要诚实。", "explanation": "这里应该用〈言传身教〉。口传心授用于技艺或学问，讲做人的道理要用言传身教。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb4f971-78ed-4ab7-9f61-d50234244499') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口传心授", "is_correct": true, "explanation": "正确。与“没有课本”相呼应，说明只能靠口头和心领的方式教。"}, {"text": "照本宣科", "is_correct": false, "explanation": "语义：“照本宣科”依赖课本，与“没有课本”矛盾。"}, {"text": "复印课本", "is_correct": false, "explanation": "语义：既然没有课本，就无法“复印课本”，前后矛盾。"}, {"text": "翻阅", "is_correct": false, "explanation": "配价：“翻阅”需要宾语（翻阅什么），此处“老师只能翻阅”缺少宾语。"}], "explanations": {"口传心授": "正确。与“没有课本”相呼应，说明只能靠口头和心领的方式教。", "照本宣科": "语义：“照本宣科”依赖课本，与“没有课本”矛盾。", "复印课本": "语义：既然没有课本，就无法“复印课本”，前后矛盾。", "翻阅": "配价：“翻阅”需要宾语（翻阅什么），此处“老师只能翻阅”缺少宾语。"}, "sentence_index": 6, "correct_answer": "口传心授"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没有老师，靠口传心授学会了木工。", "explanation": "这里应该用〈自学〉。没有老师施教却说“口传心授”，前后矛盾。"}, {"text": "他口传心授，终于做出了一把好椅子。", "explanation": "这里应该用〈反复试验〉。口传心授指老师边讲边比画地教给学生，不能用来形容自己动手做成事情。"}, {"text": "老木匠一边干活，一边口传心授，却一句话也没说。", "explanation": "这里应该用〈示范〉。口传心授要求边讲边比画，一句话也不说则只是无言示范。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb4f971-78ed-4ab7-9f61-d50234244499') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "师父一边说一边比划，被招式口传心授给徒弟。", "corrected_sentence": "师父一边说一边比划，把招式口传心授给徒弟。", "error_description": "“被”误用：此处施事是“师父”，应用“把”引出被处置的“招式”，不能用“被”。正确写法是“把招式口传心授给徒弟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb4f971-78ed-4ab7-9f61-d50234244499') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "师傅口传心授地很细，我们都学会了。", "corrected_sentence": "师傅口传心授得很细，我们都学会了。", "error_description": "“地”误用：“口传心授”后接补语“很细”时，补语前应用“得”而非“地”，正确说法是“口传心授得很细”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb4f971-78ed-4ab7-9f61-d50234244499') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
