INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22028, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "事情从一种样子变成另一种样子。", "primary_collocate": null, "pronunciation": "zhuǎn zhé", "ipa": "ʈʂwan˨˩ ʈʂɤ˧˥", "syllable_count": 2, "sentences": [{"text": "事情在这时突然转折了。", "target_word": "转折", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "故事到这里转折，主角离开了家乡。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的情况转折得很快。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "形势本来很稳，后来忽然转折了。", "target_word": "转折", "complexity_tier": "T3", "furigana": "xíng shì běn lái hěn wěn, hòu lái hū rán zhuǎn zhé le.", "sentence_source": "generated"}, {"text": "这件事转折得太快，我还没明白。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影前半部很平静，后来剧情转折了。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情到了第三天才转折，大家都松了口气。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一切都在那封信到来以后转折了。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情没有转折，我们只好再等。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也没想到，事情会这样转折。", "target_word": "转折", "complexity_tier": "T3", "furigana": "shéi yě méi xiǎng dào, shì qíng huì zhè yàng zhuǎn zhé.", "sentence_source": "generated"}], "morphological_forms": [{"form": "转折了", "label": "体标"}, {"form": "转折过", "label": "体标"}], "register": "书面", "sense_fingerprint": "动词：事情的发展忽然变成另一种样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a705c23-47ff-42bb-8ecb-59edb28e7400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转折", "is_correct": true, "explanation": "正确。动词，指事情突然变成另一种样子，与“突然”相呼应。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“事情”不会生病，主语与动词不合，语义不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“事情”不能睡觉，语义不通。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”不能以“事情”为主语，二者搭配不当。"}], "explanations": {"转折": "正确。动词，指事情突然变成另一种样子，与“突然”相呼应。", "生病": "语义：“事情”不会生病，主语与动词不合，语义不通。", "睡觉": "语义：“事情”不能睡觉，语义不通。", "散步": "搭配：“散步”不能以“事情”为主语，二者搭配不当。"}, "sentence_index": 0, "correct_answer": "转折"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这门语言经过长期转折，词汇已经大不相同。", "explanation": "这里应该用〈演变〉。转折指突然的变化，长期逐渐的变化要用演变。"}, {"text": "她的脚踝忽然转折了，疼得站不起来。", "explanation": "这里应该用〈扭伤〉。转折指事情的发展转到另一方面，脚踝受伤要用扭伤。"}, {"text": "情况渐渐转折，她的心情也慢慢好了起来。", "explanation": "这里应该用〈好转〉。转折指突然的变化，情况逐渐变好要用好转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb4f971-78ed-4ab7-9f61-d50234244499') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转折", "is_correct": true, "explanation": "正确。指事情在第三天才发生改变，与“大家都松了口气”的结果相呼应。"}, {"text": "出错", "is_correct": false, "explanation": "语义：“出错”与“大家都松了口气”的好结果相矛盾。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“事情”不能发芽，二者搭配不当。"}, {"text": "晕倒", "is_correct": false, "explanation": "语义：“事情”不会晕倒，主语与动作不合。"}], "explanations": {"转折": "正确。指事情在第三天才发生改变，与“大家都松了口气”的结果相呼应。", "出错": "语义：“出错”与“大家都松了口气”的好结果相矛盾。", "发芽": "搭配：“事情”不能发芽，二者搭配不当。", "晕倒": "语义：“事情”不会晕倒，主语与动作不合。"}, "sentence_index": 6, "correct_answer": "转折"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脾气忽然转折了，变得很温和。", "explanation": "这里应该用〈转变〉。转折指事情的发展改变，性格脾气的变化要用转变。"}, {"text": "四季按固定的顺序转折。", "explanation": "这里应该用〈循环〉。转折指突然的变化，有规律的往复要用循环。"}, {"text": "金属在高温下转折了。", "explanation": "这里应该用〈变形〉。转折指事情从一种样子变成另一种样子，金属受热弯曲要用变形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb4f971-78ed-4ab7-9f61-d50234244499') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "局势在谈判后忽然转折地很快。", "corrected_sentence": "局势在谈判后忽然转折得很快。", "error_description": "助词错误：补语前应用“得”而非“地”，“转折地很快”应改为“转折得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb4f971-78ed-4ab7-9f61-d50234244499') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部电影的剧情转折地很巧妙。", "corrected_sentence": "这部电影的剧情转折得很巧妙。", "error_description": "助词错误：补语前应用“得”而非“地”，“转折地很巧妙”不成立，应为“转折得很巧妙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb4f971-78ed-4ab7-9f61-d50234244499') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
