INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22032, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "从……开始", "primary_collocate": null, "pronunciation": "shǐ zì", "ipa": "ʂɻ̩˨˩ tsɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这家老店的生意始自八十年前。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种习俗始自农村。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的研究始自一次偶然的发现。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大雪始自昨天夜里。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马拉松比赛始自古希腊的一个故事。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的修建始自春天。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的故事始自一个小村子。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的合作始自三年前。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条公路始自北京，通向海边。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对画画的爱好始自童年。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "动词：从某个起点开始", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a705c23-47ff-42bb-8ecb-59edb28e7400') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22032, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "始自", "is_correct": true, "explanation": "正确答案。始自表示从某个时间或地点开始。"}, {"text": "十字", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，十字意思是十字形、交叉。"}, {"text": "柿子", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，后一音节轻声，意思是柿子。"}, {"text": "狮子", "is_correct": false, "explanation": "shī（第一声）与 shǐ（第三声）声调不同，意思是狮子。"}, {"text": "石子", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，后一音节轻声，意思是小石头。"}], "explanations": {"始自": "正确答案。始自表示从某个时间或地点开始。", "十字": "shí（第二声）与 shǐ（第三声）声调不同，十字意思是十字形、交叉。", "柿子": "shì（第四声）与 shǐ（第三声）声调不同，后一音节轻声，意思是柿子。", "狮子": "shī（第一声）与 shǐ（第三声）声调不同，意思是狮子。", "石子": "shí（第二声）与 shǐ（第三声）声调不同，后一音节轻声，意思是小石头。"}, "sentence_index": null, "correct_answer": "始自"}, "level_3": {"options": [{"text": "始自", "is_correct": true, "explanation": "正确。“始自”说明生意从八十年前开始，与句中的起点义相符。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”表示中断，与“八十年前”所说的起点相反。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”接的是建筑、设施，不能接“生意”作主语。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”接的是书刊、作品，不能接“生意”作主语。"}], "explanations": {"始自": "正确。“始自”说明生意从八十年前开始，与句中的起点义相符。", "停止": "语义：“停止”表示中断，与“八十年前”所说的起点相反。", "拆除": "搭配：“拆除”接的是建筑、设施，不能接“生意”作主语。", "出版": "搭配：“出版”接的是书刊、作品，不能接“生意”作主语。"}, "sentence_index": 0, "correct_answer": "始自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位画家始自法国。", "explanation": "这里应该用〈来自〉。始自多指事物的起点，人的来处、籍贯要用来自。"}, {"text": "这句诗始自《静夜思》。", "explanation": "这里应该用〈出自〉。引文、作品的出处要用出自，始自指事物的起点。"}, {"text": "他们明天始自放假。", "explanation": "这里应该用〈开始〉。始自后面要接时间、地点等起点，不能直接接“放假”这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb4f971-78ed-4ab7-9f61-d50234244499') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22032, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "始自", "is_correct": true, "explanation": "正确答案。始自表示从某个时间或地点开始。"}, {"text": "十字", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，后一音节同为 zì，意思是十字形、交叉。"}, {"text": "柿子", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，后一音节轻声，意思是柿子。"}, {"text": "虱子", "is_correct": false, "explanation": "shī（第一声）与 shǐ（第三声）声调不同，后一音节轻声，意思是虱子。"}, {"text": "尺子", "is_correct": false, "explanation": "chǐ（第三声）与 shǐ（第三声）声母不同（ch 与 sh），后一音节轻声，意思是尺子。"}], "explanations": {"始自": "正确答案。始自表示从某个时间或地点开始。", "十字": "shí（第二声）与 shǐ（第三声）声调不同，后一音节同为 zì，意思是十字形、交叉。", "柿子": "shì（第四声）与 shǐ（第三声）声调不同，后一音节轻声，意思是柿子。", "虱子": "shī（第一声）与 shǐ（第三声）声调不同，后一音节轻声，意思是虱子。", "尺子": "chǐ（第三声）与 shǐ（第三声）声母不同（ch 与 sh），后一音节轻声，意思是尺子。"}, "sentence_index": null, "correct_answer": "始自"}, "level_3": {"options": [{"text": "始自", "is_correct": true, "explanation": "正确。“始自”表示故事从一个小村子开始，与句中的起点义相符。"}, {"text": "消失", "is_correct": false, "explanation": "配价：“消失”是不及物动词，后面不能直接带“一个小村子”这样的宾语。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：“拍摄”接的是影像、画面，不能以“一个小村子”作宾语。"}, {"text": "编写", "is_correct": false, "explanation": "搭配：“编写”接的是程序、教材等，“一个小村子”不能被编写。"}], "explanations": {"始自": "正确。“始自”表示故事从一个小村子开始，与句中的起点义相符。", "消失": "配价：“消失”是不及物动词，后面不能直接带“一个小村子”这样的宾语。", "拍摄": "搭配：“拍摄”接的是影像、画面，不能以“一个小村子”作宾语。", "编写": "搭配：“编写”接的是程序、教材等，“一个小村子”不能被编写。"}, "sentence_index": 6, "correct_answer": "始自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的父亲始自农村。", "explanation": "这里应该用〈出身〉。说人的家庭或出身背景要用出身，始自只用于事物的起点。"}, {"text": "我们清晨始自去郊游。", "explanation": "这里应该用〈出发〉。人动身前往某地要说出发，始自不用来表示人的行程。"}, {"text": "这个孩子始自春天。", "explanation": "这里应该用〈出生〉。说人的出生时间要用出生，始自用于事物的起点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb4f971-78ed-4ab7-9f61-d50234244499') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段旅程从始自清晨五点，一直持续到午后。", "corrected_sentence": "这段旅程始自清晨五点，一直持续到午后。", "error_description": "“始自”本身已表示起点，前面不能再加“从”。正确写法是“这段旅程始自清晨五点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb4f971-78ed-4ab7-9f61-d50234244499') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划始自了去年春天，至今仍在进行。", "corrected_sentence": "这个计划始自去年春天，至今仍在进行。", "error_description": "“始自”后面不能直接加“了”。正确写法是“这个计划始自去年春天”，“始自”本身不带“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb4f971-78ed-4ab7-9f61-d50234244499') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
