INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22034, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西向上或向下移动。", "primary_collocate": null, "pronunciation": "shēng jiàng", "ipa": "ʂɤŋ˥ tɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "电梯的升降速度很快。", "target_word": "升降", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个小平台能自动升降。", "target_word": "升降", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "舞台中间的地板可以升降。", "target_word": "升降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他调整了椅子的升降，坐得更舒服。", "target_word": "升降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旗子的升降有固定的时间。", "target_word": "升降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船在水闸里随着水位升降。", "target_word": "升降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张桌子升降很方便，高矮都能调。", "target_word": "升降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车修理店里的车可以升降，工人修车更方便。", "target_word": "升降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店门口的玻璃电梯慢慢升降，客人都爱看。", "target_word": "升降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢看窗外吊车的升降。", "target_word": "升降", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "升降机", "label": "复合"}, {"form": "升降台", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西沿垂直方向向上或向下移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfd5ce0b-25db-4a50-9d7c-c2c7f75df794') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22034, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "升降", "is_correct": true, "explanation": "正确：「升降」指电梯上下移动，与「速度」相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」与电梯的运行无关，「电梯的颜色速度」句意不通。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：「面积」说平面的大小，不能和「速度」搭配。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」指气味或滋味，与电梯的速度不相关。"}], "explanations": {"升降": "正确：「升降」指电梯上下移动，与「速度」相符。", "颜色": "语义：「颜色」与电梯的运行无关，「电梯的颜色速度」句意不通。", "面积": "搭配：「面积」说平面的大小，不能和「速度」搭配。", "味道": "语义：「味道」指气味或滋味，与电梯的速度不相关。"}, "sentence_index": 0, "correct_answer": "升降"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公交车在路口升降。", "explanation": "这里应该用〈转弯〉。升降指上下移动，车辆改变行驶方向要用转弯。"}, {"text": "我们在公园升降。", "explanation": "这里应该用〈散步〉。升降指垂直上下移动，人在平地慢慢走要用散步。"}, {"text": "车辆绕行了湖边，又升降了湖边。", "explanation": "这里应该用〈绕行〉。升降是上下移动，沿湖边绕着走要用绕行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ecb297-d7dd-4b53-90b2-e9becbfbfd7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "升降", "is_correct": true, "explanation": "正确：「升降」指桌子高度的调节，与「很方便，高矮都能调」相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：桌子不会唱歌，与「很方便，高矮都能调」的语境不符。"}, {"text": "开花", "is_correct": false, "explanation": "语义：桌子不会开花，句意不通。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：「吹」不能用来说桌子的使用，与「高矮都能调」的语境不符。"}], "explanations": {"升降": "正确：「升降」指桌子高度的调节，与「很方便，高矮都能调」相符。", "唱歌": "语义：桌子不会唱歌，与「很方便，高矮都能调」的语境不符。", "开花": "语义：桌子不会开花，句意不通。", "吹": "搭配：「吹」不能用来说桌子的使用，与「高矮都能调」的语境不符。"}, "sentence_index": 6, "correct_answer": "升降"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们升降马路。", "explanation": "这里应该用〈横穿〉。升降只指上下移动，从马路一侧走到另一侧要用横穿。"}, {"text": "他在树下来回升降。", "explanation": "这里应该用〈走动〉。升降只指上下移动，人在地面来回走动要用走动，不能用升降。"}, {"text": "他们升降世界。", "explanation": "这里应该用〈环游〉。升降是上下移动，周游各地要用环游。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ecb297-d7dd-4b53-90b2-e9becbfbfd7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把椅子升降地很方便。", "corrected_sentence": "这把椅子升降很方便。", "error_description": "错误：「升降」后多出了「地」。「很方便」直接评价「升降」，中间不能加「地」，应为「升降很方便」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ecb297-d7dd-4b53-90b2-e9becbfbfd7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吊车升降了一个。", "corrected_sentence": "吊车升降了一次。", "error_description": "错误：「升降」作动量时用「次」，不能用「个」。正确应为「升降了一次」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ecb297-d7dd-4b53-90b2-e9becbfbfd7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
