INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22048, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "世纪是一百年的时间。", "primary_collocate": null, "pronunciation": "shì jì", "ipa": "ʂɻ̩˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "一百年就是一个世纪。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是十八世纪的故事。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们现在生活在二十一世纪。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个博物馆有半个世纪的历史。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上世纪的电话和现在的很不一样。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个世纪就是二百年。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老作家活了将近一个世纪。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二十世纪的第一年是哪一年？", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个世纪的世界会是什么样子？", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座教堂已经站了三个世纪。", "target_word": "世纪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个世纪", "label": "量词"}, {"form": "半个世纪", "label": "复合"}, {"form": "世紀", "label": "繁体"}], "register": "通用", "sense_fingerprint": "一百年的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c129f6d-1946-456e-a53b-85dab20cb751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22048, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "世纪", "is_correct": true, "explanation": "世纪（shìjì）是本题目标词，指一百年的时间。"}, {"text": "四季", "is_correct": false, "explanation": "四季（sìjì）与 shìjì 声母不同（s 与 sh），意思是一年的四个季节。"}, {"text": "时机", "is_correct": false, "explanation": "时机（shíjī）两个音节的声调都与 shìjì 不同，意思是合适的机会。"}, {"text": "诗集", "is_correct": false, "explanation": "诗集（shījí）两个音节的声调都与 shìjì 不同，意思是诗歌的汇编。"}], "explanations": {"世纪": "世纪（shìjì）是本题目标词，指一百年的时间。", "四季": "四季（sìjì）与 shìjì 声母不同（s 与 sh），意思是一年的四个季节。", "时机": "时机（shíjī）两个音节的声调都与 shìjì 不同，意思是合适的机会。", "诗集": "诗集（shījí）两个音节的声调都与 shìjì 不同，意思是诗歌的汇编。"}, "sentence_index": null, "correct_answer": "世纪"}, "level_3": {"options": [{"text": "世纪", "is_correct": true, "explanation": "世纪是一百年的时间，与“一百年就是一个”同义，符合句意。"}, {"text": "年", "is_correct": false, "explanation": "语义：“一个年”指一年，与“一百年”矛盾。"}, {"text": "小时", "is_correct": false, "explanation": "语义：“一个小时”远短于一百年，与“一百年就是一个”矛盾。"}, {"text": "大学", "is_correct": false, "explanation": "搭配：“大学”不能作时间单位，“一个大学”不成立。"}], "explanations": {"世纪": "世纪是一百年的时间，与“一百年就是一个”同义，符合句意。", "年": "语义：“一个年”指一年，与“一百年”矛盾。", "小时": "语义：“一个小时”远短于一百年，与“一百年就是一个”矛盾。", "大学": "搭配：“大学”不能作时间单位，“一个大学”不成立。"}, "sentence_index": 0, "correct_answer": "世纪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "八十世纪的电影很有名。", "explanation": "这里应该用〈年代〉。“八十年代”指十年，世纪是一百年，不能用“八十世纪”表示。"}, {"text": "学生世纪的生活很快乐。", "explanation": "这里应该用〈时期〉。世纪是固定的百年单位，学生阶段这样的时期要用时期。"}, {"text": "他一个世纪就吃完了午饭。", "explanation": "这里应该用〈一会儿〉。世纪是百年为单位，吃午饭的时间不能用世纪计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22048, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "世纪", "is_correct": true, "explanation": "世纪（shìjì）是本题目标词，指一百年的时间。"}, {"text": "实际", "is_correct": false, "explanation": "实际（shíjì）首音节声调与 shì 不同，意思是真实的情况。"}, {"text": "市集", "is_correct": false, "explanation": "市集（shìjí）末音节声调与 jì 不同，意思是集市。"}, {"text": "十几", "is_correct": false, "explanation": "十几（shíjǐ）两个音节的声调都与 shìjì 不同，意思是十多个。"}], "explanations": {"世纪": "世纪（shìjì）是本题目标词，指一百年的时间。", "实际": "实际（shíjì）首音节声调与 shì 不同，意思是真实的情况。", "市集": "市集（shìjí）末音节声调与 jì 不同，意思是集市。", "十几": "十几（shíjǐ）两个音节的声调都与 shìjì 不同，意思是十多个。"}, "sentence_index": null, "correct_answer": "世纪"}, "level_3": {"options": [{"text": "世纪", "is_correct": true, "explanation": "世纪是一百年，“活了将近一个世纪”表示接近一百年的寿命。"}, {"text": "季度", "is_correct": false, "explanation": "语义：“一个季度”只有三个月，与“活了将近”的长寿语境不合。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“一个星期”只有七天，远不足以指寿命。"}, {"text": "工龄", "is_correct": false, "explanation": "搭配：“活了”不能带“工龄”，工龄指工作的年限。"}], "explanations": {"世纪": "世纪是一百年，“活了将近一个世纪”表示接近一百年的寿命。", "季度": "语义：“一个季度”只有三个月，与“活了将近”的长寿语境不合。", "星期": "语义：“一个星期”只有七天，远不足以指寿命。", "工龄": "搭配：“活了”不能带“工龄”，工龄指工作的年限。"}, "sentence_index": 6, "correct_answer": "世纪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的世纪是四年。", "explanation": "这里应该用〈任期〉。世纪是一百年，不能用来指任职的四年期限。"}, {"text": "这个世纪有两个星期。", "explanation": "这里应该用〈假期〉。世纪是百年为单位，假期的长度不能用世纪表示。"}, {"text": "这盒牛奶的世纪是七天。", "explanation": "这里应该用〈保质期〉。世纪是百年为单位，食品的保质期不能用世纪表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三条世纪以前，这里还是森林。", "corrected_sentence": "三个世纪以前，这里还是森林。", "error_description": "量词错误：“世纪”前应用“个”，不能用“条”。正确说法是“三个世纪以前，这里还是森林”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市在上个的世纪发展很快。", "corrected_sentence": "这座城市在上个世纪发展很快。", "error_description": "修饰语错误：“上个”与“世纪”之间不能加“的”，应说“上个世纪”。正确说法是“这座城市在上个世纪发展很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
