INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22058, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把很多小东西按规律放好，变成一个大整体。", "primary_collocate": null, "pronunciation": "xì tǒng huà", "ipa": "ɕi˥˩ tʰʊŋ˨˩˦ xua˥˩", "syllable_count": 3, "sentences": [{"text": "老师帮我们把笔记系统化了。", "target_word": "系统化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这些资料系统化。", "target_word": "系统化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "知识要系统化，才容易记住。", "target_word": "系统化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把零散的想法系统化了。", "target_word": "系统化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想让管理系统化。", "target_word": "系统化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这些数据系统化，再交给我。", "target_word": "系统化", "complexity_tier": "T3", "furigana": "qǐng nǐ bǎ zhèxiē shùjù xìtǒnghuà, zài jiāo gěi wǒ.", "sentence_source": "generated"}, {"text": "复习时要把知识点系统化。", "target_word": "系统化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习语法最好系统化一点儿。", "target_word": "系统化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个图书馆的分类已经系统化了。", "target_word": "系统化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天花一个小时，把学习计划系统化。", "target_word": "系统化", "complexity_tier": "T3", "furigana": "tā měi tiān huā yí gè xiǎoshí, bǎ xuéxí jìhuà xìtǒnghuà.", "sentence_source": "generated"}], "morphological_forms": [{"form": "系统化了", "label": "体标（了）"}, {"form": "系統化", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把零散的东西按规律整理成有条理的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1880ae27-277a-4733-a3c1-9b641a61ba6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22058, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "系统化", "is_correct": true, "explanation": "正确：“系统化了”指把笔记整理得有条理，与“老师帮我们”的语境相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物，笔记不能煮，也与整理的意思不符。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”指弄破，老师帮我们撕笔记不符合整理的意思。"}, {"text": "冻", "is_correct": false, "explanation": "搭配：“冻”多用于食物、水等，不说“冻笔记”。"}], "explanations": {"系统化": "正确：“系统化了”指把笔记整理得有条理，与“老师帮我们”的语境相符。", "煮": "语义：“煮”是加热食物，笔记不能煮，也与整理的意思不符。", "撕": "语义：“撕”指弄破，老师帮我们撕笔记不符合整理的意思。", "冻": "搭配：“冻”多用于食物、水等，不说“冻笔记”。"}, "sentence_index": 0, "correct_answer": "系统化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把窗户系统化了。", "explanation": "这里应该用〈擦〉。系统化用于知识、想法、资料，不用于清洁窗户。"}, {"text": "他系统化好了一盘菜。", "explanation": "这里应该用〈炒〉。系统化指使内容有条理地组成整体，不用于烹饪；“炒好”才是正确说法。"}, {"text": "他系统化了那只小狗。", "explanation": "这里应该用〈训练〉。系统化用于知识、资料等内容，不用于动物；训练小狗要用〈训练〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "系统化", "is_correct": true, "explanation": "正确：“把知识点系统化”指使知识有条理，与复习的语境相符。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”是用刀斩断，知识点不能砍。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是用火加热食物，与复习无关。"}, {"text": "晒", "is_correct": false, "explanation": "搭配：“晒”多用于衣物、粮食等，不说“晒知识点”。"}], "explanations": {"系统化": "正确：“把知识点系统化”指使知识有条理，与复习的语境相符。", "砍": "语义：“砍”是用刀斩断，知识点不能砍。", "烤": "语义：“烤”是用火加热食物，与复习无关。", "晒": "搭配：“晒”多用于衣物、粮食等，不说“晒知识点”。"}, "sentence_index": 6, "correct_answer": "系统化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把自行车系统化了。", "explanation": "这里应该用〈修理〉。系统化用于内容、计划，不用于修理机器。"}, {"text": "他很快系统化地吃完了饭。", "explanation": "这里应该用〈狼吞虎咽〉之类的描述。系统化用于使内容有条理地组成整体，不用于吃饭这类日常动作。"}, {"text": "他一口气把整个西瓜系统化了。", "explanation": "这里应该用〈吃掉〉。系统化用于知识、计划等内容，不用于西瓜等食物；“吃掉”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想把这份资料系统化地。", "corrected_sentence": "我想把这份资料系统化。", "error_description": "错误：句末多出“地”。“地”是状语标记，只用于它所修饰的动词之前（如“系统化地整理”）；此句“地”之后没有动词，句子不完整。应去掉“地”，说“我想把这份资料系统化。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把学习计划把系统化了。", "corrected_sentence": "他把学习计划系统化了。", "error_description": "“把”字句只需一个“把”，“把学习计划”之后直接接“系统化”。原句多加了一个“把”，正确说法是“他把学习计划系统化了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
