INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22062, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一件事必须有的条件，没有它就不行。", "primary_collocate": null, "pronunciation": "bì yào tiáo jiàn", "ipa": "pi˥˩ jaʊ˥˩ tʰjaʊ˧˥ tɕjɛn˥˩", "syllable_count": 4, "sentences": [{"text": "有钱不是幸福的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会说中文是这份工作的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体好是长跑的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "带护照是出国的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耐心是学好汉字的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买票是进公园的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有车不是在这座城市生活的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作的必要条件是会开车。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好天气是比赛的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合格的成绩是上大学的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "充分必要条件", "label": "复合"}, {"form": "必要條件", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做一件事一定要有的条件，缺了就不行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1880ae27-277a-4733-a3c1-9b641a61ba6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22062, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必要条件", "is_correct": true, "explanation": "正确。“必要条件”指事情必须具备的条件，句中说钱不是幸福必须具备的条件。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与“幸福”之间没有条件关系，句子读不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”不能修饰“幸福”，不能说幸福的体温。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形外貌，不能用来说明幸福的条件。"}], "explanations": {"必要条件": "正确。“必要条件”指事情必须具备的条件，句中说钱不是幸福必须具备的条件。", "颜色": "语义：“颜色”与“幸福”之间没有条件关系，句子读不通。", "体温": "搭配：“体温”不能修饰“幸福”，不能说幸福的体温。", "身材": "体貌：“身材”指人的体形外貌，不能用来说明幸福的条件。"}, "sentence_index": 0, "correct_answer": "必要条件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把必要条件送给了朋友。", "explanation": "这里应该用〈礼物〉。“必要条件”指必须具备的前提，是抽象概念，不能当作物品送人。"}, {"text": "他家必要条件很好，能上私立学校。", "explanation": "这里应该用〈家境〉。“必要条件”指必须具备的前提，不指家庭经济状况。"}, {"text": "学习外语要打好必要条件。", "explanation": "这里应该用〈基础〉。“打好”后接“基础”，“必要条件”指必须具备的前提，不能说“打好必要条件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "必要条件", "is_correct": true, "explanation": "正确。“必要条件”指事情必须具备的条件，句中说有车不是在这座城市生活必须具备的条件。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”指一年中的时段，不能作为“生活”的条件，句子读不通。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：“墨水”是书写用的液体，与生活条件无关，句子读不通。"}, {"text": "胃口", "is_correct": false, "explanation": "搭配：“胃口”不能与“生活”构成领属关系，不能说生活的胃口。"}], "explanations": {"必要条件": "正确。“必要条件”指事情必须具备的条件，句中说有车不是在这座城市生活必须具备的条件。", "季节": "语义：“季节”指一年中的时段，不能作为“生活”的条件，句子读不通。", "墨水": "语义：“墨水”是书写用的液体，与生活条件无关，句子读不通。", "胃口": "搭配：“胃口”不能与“生活”构成领属关系，不能说生活的胃口。"}, "sentence_index": 6, "correct_answer": "必要条件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚买下了一个必要条件。", "explanation": "这里应该用〈商品〉。“买”的对象是具体商品，“必要条件”是抽象的前提，不是能买的东西。"}, {"text": "这次旅行的必要条件很有趣。", "explanation": "这里应该用〈活动〉。“有趣”用于形容活动、故事等，“必要条件”指必须具备的前提，不能说很有趣。"}, {"text": "他在墙上刷了一层必要条件。", "explanation": "这里应该用〈颜料〉。“刷”的对象是油漆、颜料等物质，“必要条件”是抽象的前提，不能刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "按时交作业是通过这门课的一把必要条件。", "corrected_sentence": "按时交作业是通过这门课的一个必要条件。", "error_description": "错误：量词“把”。应为“个”。“把”用于有柄的器具，“条件”是抽象概念，量词应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次面试必要条件是有英语证书。", "corrected_sentence": "这次面试的必要条件是有英语证书。", "error_description": "错误：“这次面试”与“必要条件”之间漏掉“的”。应为“这次面试的必要条件”，领属关系需要“的”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
