INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22068, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "小节就是很小的事情。", "primary_collocate": null, "pronunciation": "xiǎo jié", "ipa": "ɕjɑʊ̯˨˩ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "他是个不拘小节的人，从不生气。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对小节向来不放在心上，只看大局。", "target_word": "小节", "complexity_tier": "T3", "furigana": "xiǎo jié", "sentence_source": "generated"}, {"text": "别为小节争来争去，大事更重要。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王性格豪爽，不太在意生活中的小节。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小节上的分歧，我自己就能处理好。", "target_word": "小节", "complexity_tier": "T3", "furigana": "xiǎo jié", "sentence_source": "generated"}, {"text": "他只注意大事，常常忘了小节。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成功的人不会纠缠小节。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "何必为了小节这么生气？", "target_word": "小节", "complexity_tier": "T3", "furigana": "xiǎo jié", "sentence_source": "generated"}, {"text": "我们先谈大事，小节以后再说。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很大方，从不计较小节。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小節", "label": "繁体"}], "register": "书面", "sense_fingerprint": "很小的、不重要的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de0e16fe-f24e-4396-aacb-44762e195d23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22068, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小节", "is_correct": true, "explanation": "正确答案：小节（xiǎo jié），指很小的事情。"}, {"text": "小姐", "is_correct": false, "explanation": "jiě（第三声）与 jié（第二声）声调不同，“小姐”指年轻女子，意思不同。"}, {"text": "小鞋", "is_correct": false, "explanation": "xié 与 jié 声母不同（x 与 j），“小鞋”指（穿）小鞋，意思不同。"}, {"text": "小街", "is_correct": false, "explanation": "jiē（第一声）与 jié（第二声）声调不同，“小街”指小的街道。"}], "explanations": {"小节": "正确答案：小节（xiǎo jié），指很小的事情。", "小姐": "jiě（第三声）与 jié（第二声）声调不同，“小姐”指年轻女子，意思不同。", "小鞋": "xié 与 jié 声母不同（x 与 j），“小鞋”指（穿）小鞋，意思不同。", "小街": "jiē（第一声）与 jié（第二声）声调不同，“小街”指小的街道。"}, "sentence_index": null, "correct_answer": "小节"}, "level_3": {"options": [{"text": "小节", "is_correct": true, "explanation": "正确：“不拘小节”指不计较细小的事，与“从不生气”相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“不拘”的对象是规矩、细节等抽象的事情，“桌子”是具体物品，不能“不拘”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“不拘”修饰的是人的行事作风，“书包”是具体物品，搭配不成立。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“不拘”多接“形式、礼节、时间”等，不说“不拘脾气”。"}], "explanations": {"小节": "正确：“不拘小节”指不计较细小的事，与“从不生气”相符。", "桌子": "语义：“不拘”的对象是规矩、细节等抽象的事情，“桌子”是具体物品，不能“不拘”。", "书包": "语义：“不拘”修饰的是人的行事作风，“书包”是具体物品，搭配不成立。", "脾气": "搭配：“不拘”多接“形式、礼节、时间”等，不说“不拘脾气”。"}, "sentence_index": 0, "correct_answer": "小节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的小节坏了，所以停下来了。", "explanation": "这里应该用〈零件〉。小节指很小的事情，不指机器的部件。"}, {"text": "门口的小节松了，要拧紧。", "explanation": "这里应该用〈螺丝〉。小节不指螺丝这类具体器件，“松了”要说螺丝。"}, {"text": "老师在课后做了一个小节。", "explanation": "这里应该用〈小结〉。“小结”指对所讲内容的简短总结；“小节”指很小的事情，不能用来指总结。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小节", "is_correct": true, "explanation": "正确：“纠缠小节”指对细枝末节斤斤计较，与“成功的人”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：不能“纠缠”石头，句中说的是人对事情的态度。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“纠缠天气”不合常理，天气不是可以争辩的事情。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“纠缠”多接问题、小事，不说“纠缠味道”。"}], "explanations": {"小节": "正确：“纠缠小节”指对细枝末节斤斤计较，与“成功的人”相符。", "石头": "语义：不能“纠缠”石头，句中说的是人对事情的态度。", "天气": "语义：“纠缠天气”不合常理，天气不是可以争辩的事情。", "味道": "搭配：“纠缠”多接问题、小事，不说“纠缠味道”。"}, "sentence_index": 6, "correct_answer": "小节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批产品有一处小节，需要退回。", "explanation": "这里应该用〈缺陷〉。小节指很小的事情，不指产品的质量问题。"}, {"text": "这台设备出现了小节，无法启动。", "explanation": "这里应该用〈故障〉。小节不指设备的故障。"}, {"text": "这次测量有一点小节，结果不准。", "explanation": "这里应该用〈误差〉。小节不指测量中产生的误差。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "别为这只小节生气。", "corrected_sentence": "别为这点小节生气。", "error_description": "量词错误：“只”多用于动物，不能用于“小节”。正确应说“这点小节”，即“别为这点小节生气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她做事大方，从不小节放在心上。", "corrected_sentence": "她做事大方，从不把小节放在心上。", "error_description": "把字句错误：表示处置“小节”的“放在心上”要用“把”字句，应说“从不把小节放在心上”，漏掉“把”则句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
