INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22070, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西带进来。", "primary_collocate": null, "pronunciation": "yǐn rù", "ipa": "/in˨˩˦ ɻu˥˩/", "syllable_count": 2, "sentences": [{"text": "这家工厂去年引入了新机器。", "target_word": "引入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司从国外引入了一种新技术。", "target_word": "引入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们决定引入一套新的管理办法。", "target_word": "引入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把新品种引入了这个地区。", "target_word": "引入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果是从南美引入中国的。", "target_word": "引入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市最近引入了很多进口牛奶。", "target_word": "引入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院引入了先进的检查设备。", "target_word": "引入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把这个好办法引入公司。", "target_word": "引入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市引入过很多外国公司。", "target_word": "引入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校引入新系统以后，老师们都说方便。", "target_word": "引入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "引入了", "label": "体标：完成"}, {"form": "引入过", "label": "体标：经历"}], "register": "中性", "sense_fingerprint": "把外面的技术、设备、品种、制度等带进来使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa75729c-4fdb-4353-ab48-5298e7732270') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引入", "is_correct": true, "explanation": "正确：“引入了新机器”指把外部的设备带进来，搭配自然。"}, {"text": "驱逐", "is_correct": false, "explanation": "语义：“驱逐”的对象是人或动物，不能说驱逐新机器。"}, {"text": "吸引", "is_correct": false, "explanation": "配价：“吸引”要求能被吸引的对象，机器不能被吸引。"}, {"text": "消灭", "is_correct": false, "explanation": "语义：“消灭”指彻底毁灭，与“去年引入新机器”的语境相反。"}], "explanations": {"引入": "正确：“引入了新机器”指把外部的设备带进来，搭配自然。", "驱逐": "语义：“驱逐”的对象是人或动物，不能说驱逐新机器。", "吸引": "配价：“吸引”要求能被吸引的对象，机器不能被吸引。", "消灭": "语义：“消灭”指彻底毁灭，与“去年引入新机器”的语境相反。"}, "sentence_index": 0, "correct_answer": "引入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事引入了大家的不满。", "explanation": "这里应该用〈引起〉。引入指把外部的事物带进来，“不满”是引起的结果，不能被引入。"}, {"text": "他把朋友引入了经理。", "explanation": "这里应该用〈引荐〉。把人介绍给别人用“引荐”，“引入”用于技术、制度等外来事物。"}, {"text": "我们引入了一场大雨。", "explanation": "这里应该用〈下〉。下雨用“下”，“引入”只能用于把外部事物带进来，天气不能被引入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引入", "is_correct": true, "explanation": "正确：“医院引入了先进的检查设备”，指把先进设备带进医院。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动词，不能带“检查设备”作宾语。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”只用于车辆、船只等，不能用于检查设备。"}, {"text": "生育", "is_correct": false, "explanation": "语义：“生育”指生孩子，与医院引进设备无关。"}], "explanations": {"引入": "正确：“医院引入了先进的检查设备”，指把先进设备带进医院。", "咳嗽": "配价：“咳嗽”是不及物动词，不能带“检查设备”作宾语。", "驾驶": "搭配：“驾驶”只用于车辆、船只等，不能用于检查设备。", "生育": "语义：“生育”指生孩子，与医院引进设备无关。"}, "sentence_index": 6, "correct_answer": "引入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师引入学生去思考问题。", "explanation": "这里应该用〈引导〉。引入的对象是外来的事物，带领学生思考要用“引导”。"}, {"text": "他的话引入了我的眼泪。", "explanation": "这里应该用〈引出〉。引出指使某种反应出现，引入指把外部事物带进来。"}, {"text": "他把礼物引入了朋友。", "explanation": "这里应该用〈送〉。引入用于把外部事物带进某个系统或地区，不能用于把东西送给人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司被引入了一套新的管理制度。", "corrected_sentence": "这家公司引入了一套新的管理制度。", "error_description": "被动标记错误：“引入”的主语“这家公司”是施事，不能加“被”，应说“这家公司引入了一套新的管理制度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市引入过很多外国公司过。", "corrected_sentence": "这座城市引入过很多外国公司。", "error_description": "错误：句末多出“过”。“过”是体标，须紧接动词使用，不能接在名词“公司”之后放在句末；应删去句末的“过”，保留“引入过很多外国公司”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
