INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22072, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一天比一天，慢慢变化。", "primary_collocate": null, "pronunciation": "rì qū", "ipa": "ʐɨ˥˩ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "吃了几天药，他的身体日趋好转。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的记忆力日趋衰退。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着时间过去，两人的感情日趋深厚。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇的游客日趋增多。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年来，网络诈骗的手段日趋复杂。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛进入后半段，场上气氛日趋紧张。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天来了，夜晚日趋漫长。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过训练，她的口语日趋流利。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的绿地日趋减少。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大以后，性格日趋稳重。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日趨", "label": "繁体"}], "register": "书面", "sense_fingerprint": "副词：一天比一天地慢慢变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c970757-3a26-48dc-826e-19d56f34238d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日趋", "is_correct": true, "explanation": "正确：“日趋”表示身体一天天慢慢好转，符合句意。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多用于否定或经历，不能修饰“好转”这类变化。"}, {"text": "只好", "is_correct": false, "explanation": "搭配：“只好”需接行为选择，不能修饰“好转”。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”指由本人动手，不能修饰“身体好转”这类无人施为的变化。"}], "explanations": {"日趋": "正确：“日趋”表示身体一天天慢慢好转，符合句意。", "从来": "搭配：“从来”多用于否定或经历，不能修饰“好转”这类变化。", "只好": "搭配：“只好”需接行为选择，不能修饰“好转”。", "亲自": "搭配：“亲自”指由本人动手，不能修饰“身体好转”这类无人施为的变化。"}, "sentence_index": 0, "correct_answer": "日趋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他日趋打了一个喷嚏。", "explanation": "这里应该用〈突然〉。打喷嚏是一瞬间的动作，日趋只用于逐渐变化的过程，不能用于此。"}, {"text": "我接到电话，日趋出发了。", "explanation": "这里应该用〈马上〉。出发是一次性的动作，日趋只用于逐渐变化的过程。"}, {"text": "他日趋撞到了桌子。", "explanation": "这里应该用〈突然〉。撞到桌子是一瞬间的事，日趋只用于逐渐变化的过程，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38f8333b-0010-4ada-9ff4-55b9725ee229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日趋", "is_correct": true, "explanation": "正确：“日趋”表示夜晚一天天逐渐变长，与“冬天来了”呼应，符合句意。"}, {"text": "竟", "is_correct": false, "explanation": "语义：“竟”表示出乎意料，与“冬天来了”带来的渐进变化不合。"}, {"text": "一向", "is_correct": false, "explanation": "搭配：“一向”表示长期如此，不能用来修饰“漫长”这种渐进的变化过程。"}, {"text": "亲手", "is_correct": false, "explanation": "搭配：“亲手”指由人本人动手，不能修饰“夜晚漫长”这类变化。"}], "explanations": {"日趋": "正确：“日趋”表示夜晚一天天逐渐变长，与“冬天来了”呼应，符合句意。", "竟": "语义：“竟”表示出乎意料，与“冬天来了”带来的渐进变化不合。", "一向": "搭配：“一向”表示长期如此，不能用来修饰“漫长”这种渐进的变化过程。", "亲手": "搭配：“亲手”指由人本人动手，不能修饰“夜晚漫长”这类变化。"}, "sentence_index": 6, "correct_answer": "日趋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的姓名日趋是张伟。", "explanation": "这里应该用〈一直〉。日趋表示逐渐变化，姓名不会改变，表示始终不变应用“一直”。"}, {"text": "他日趋会来开会。", "explanation": "这里应该用〈有时〉。“有时”指不定期发生，与日趋的持续变化不能互换。"}, {"text": "我日趋会去图书馆。", "explanation": "这里应该用〈偶尔〉。“偶尔”表示不定期的行为，日趋只用于持续逐渐的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38f8333b-0010-4ada-9ff4-55b9725ee229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的生意日趋的兴旺。", "corrected_sentence": "这家店的生意日趋兴旺。", "error_description": "多余的“的”：“日趋”后直接接形容词，不加“的”，应说“日趋兴旺”，不能说“日趋的兴旺”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38f8333b-0010-4ada-9ff4-55b9725ee229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城市的绿化日趋很完善。", "corrected_sentence": "城市的绿化日趋完善。", "error_description": "程度副词错误：“日趋”后面不能再接程度副词“很”，应说“日趋完善”，不能说“日趋很完善”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38f8333b-0010-4ada-9ff4-55b9725ee229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
