INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22076, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "音乐中标在谱表开头、表示乐曲调性的升降号记号。", "primary_collocate": null, "pronunciation": "diào hào", "ipa": "tjɑʊ̯˥˩ xɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "谱子开头的调号告诉我们要弹哪些黑键。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小提琴谱和钢琴谱的调号写法不一样。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一看调号，就知道这是G大调。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张谱上有三个降号的调号。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在这里画一个新的调号。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在课上练习写调号。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首曲子的调号是什么？", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调号太多，初学者会觉得很难。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐老师在黑板上写了一个调号。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把调号抄错了，唱起来很奇怪。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "調號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "谱表开头表示调性的升降号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de0e16fe-f24e-4396-aacb-44762e195d23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22076, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调号", "is_correct": true, "explanation": "正确答案：调号（diào hào），音乐中表示音高范围的符号。"}, {"text": "调好", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，“调好”意为调整好，不是调号。"}, {"text": "跳号", "is_correct": false, "explanation": "d 与 t 声母不同，“跳号”指跳过编号，意思不同。"}, {"text": "叫号", "is_correct": false, "explanation": "d 与 j 声母不同，“叫号”指按号码叫人，意思不同。"}], "explanations": {"调号": "正确答案：调号（diào hào），音乐中表示音高范围的符号。", "调好": "hǎo（第三声）与 hào（第四声）声调不同，“调好”意为调整好，不是调号。", "跳号": "d 与 t 声母不同，“跳号”指跳过编号，意思不同。", "叫号": "d 与 j 声母不同，“叫号”指按号码叫人，意思不同。"}, "sentence_index": null, "correct_answer": "调号"}, "level_3": {"options": [{"text": "调号", "is_correct": true, "explanation": "正确：调号以升降号标明调性，告诉演奏者哪些音要升降，即“哪些黑键”。"}, {"text": "拍号", "is_correct": false, "explanation": "语义：拍号标明每小节的拍数，不标明哪些黑键。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：歌词是唱的文字，不指示按键。"}, {"text": "页码", "is_correct": false, "explanation": "搭配：“页码”与“告诉我们要弹哪些黑键”搭配不当，指示按键的是调号。"}], "explanations": {"调号": "正确：调号以升降号标明调性，告诉演奏者哪些音要升降，即“哪些黑键”。", "拍号": "语义：拍号标明每小节的拍数，不标明哪些黑键。", "歌词": "语义：歌词是唱的文字，不指示按键。", "页码": "搭配：“页码”与“告诉我们要弹哪些黑键”搭配不当，指示按键的是调号。"}, "sentence_index": 0, "correct_answer": "调号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个调号是四分音符。", "explanation": "这里应该用〈音符〉。调号标明乐曲的调性，“四分音符”说的是音符的时值。"}, {"text": "这首曲子的调号很优美。", "explanation": "这里应该用〈旋律〉。调号是标明调性的记号，不能用来形容曲子优美；“优美”说的是旋律。"}, {"text": "这首曲子的调号是四四拍。", "explanation": "这里应该用〈拍号〉。调号标明调性，四四拍说的是每小节的拍数，属于拍号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调号", "is_correct": true, "explanation": "正确：“这首曲子的调号是什么”问的是曲子的调性记号。"}, {"text": "温度", "is_correct": false, "explanation": "语义：曲子没有“温度”，句中问的是乐谱记号。"}, {"text": "重量", "is_correct": false, "explanation": "语义：曲子没有“重量”，这样问不合常理。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是人的身体特征，不适用于曲子。"}], "explanations": {"调号": "正确：“这首曲子的调号是什么”问的是曲子的调性记号。", "温度": "语义：曲子没有“温度”，句中问的是乐谱记号。", "重量": "语义：曲子没有“重量”，这样问不合常理。", "体重": "体貌：“体重”是人的身体特征，不适用于曲子。"}, "sentence_index": 6, "correct_answer": "调号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把调号唱错了，唱起来很奇怪。", "explanation": "这里应该用〈旋律〉。“唱”的对象是旋律，调号是乐谱上的记号，不能被唱。"}, {"text": "我把调号打错了，跟不上别人。", "explanation": "这里应该用〈节拍〉。“打”搭配节拍，调号不能被“打”。"}, {"text": "我把调号弹错了，唱起来很奇怪。", "explanation": "这里应该用〈和弦〉。“弹”搭配和弦、曲子，调号不能被“弹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看谱时总是先看一张调号。", "corrected_sentence": "我看谱时总是先看调号。", "error_description": "量词错误：“张”多用于纸张、桌子这类平面的东西，“调号”前不用量词。正确说法是“先看调号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把调号吃错了，所以谱子看起来很乱。", "corrected_sentence": "他把调号写错了，所以谱子看起来很乱。", "error_description": "搭配错误：“吃”不能用于调号，应说“写错”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9b79aa-e461-4336-9af6-2dace30b0c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
