INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22080, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一件事告诉别人。", "primary_collocate": null, "pronunciation": "chuán dá", "ipa": "tʂʰwan˧˥ ta˧˥", "syllable_count": 2, "sentences": [{"text": "请你把这个消息传达给大家。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理让我传达明天开会的通知。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王已经把校长的话传达给同学了。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了传达老师的要求。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会后，李主任向全体员工传达了会议内容。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会把你的话传达给他。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把我的问候传达给你爸爸。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长负责传达学校的通知。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的师傅把客人的话传达给了经理。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你先传达给组里的人。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传达了", "label": "完成体"}, {"form": "传达过", "label": "经历体"}, {"form": "传达室", "label": "复合"}, {"form": "傳達", "label": "繁体"}], "register": "中性", "sense_fingerprint": "传达：把通知、话语等一件具体的事转告给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ae535a-9ea1-4936-80af-cc9fd7df8a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22080, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传达", "is_correct": true, "explanation": "传达：把消息告诉大家，符合“把……给大家”的句式和语境。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”是不让人知道，与请对方把消息告诉大家的意思相矛盾。"}, {"text": "收藏", "is_correct": false, "explanation": "配价：“收藏”一般指保存物品或文件，不能用“收藏给大家”表示转告。"}, {"text": "查收", "is_correct": false, "explanation": "语域：“查收”是收件人接收的书面用语，不能用于由你转告大家。"}], "explanations": {"传达": "传达：把消息告诉大家，符合“把……给大家”的句式和语境。", "隐瞒": "语义：“隐瞒”是不让人知道，与请对方把消息告诉大家的意思相矛盾。", "收藏": "配价：“收藏”一般指保存物品或文件，不能用“收藏给大家”表示转告。", "查收": "语域：“查收”是收件人接收的书面用语，不能用于由你转告大家。"}, "sentence_index": 0, "correct_answer": "传达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把花传达给了妈妈。", "explanation": "这里应该用〈送〉。传达的对象是消息、意思，送花要用送。"}, {"text": "他用现金传达了房租。", "explanation": "这里应该用〈支付〉。传达是把消息告诉别人，不能用来表示付钱。"}, {"text": "妈妈在厨房传达了一锅粥。", "explanation": "这里应该用〈煮〉。传达只用于信息、意思，煮粥要用煮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传达", "is_correct": true, "explanation": "传达：把问候转告给对方的父亲，符合句子的语境。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“请把……给你爸爸”的请求相矛盾。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”指去掉信息或文件，不能用来表示把问候送给别人。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，问候不能用来购买，也不能这样送给别人。"}], "explanations": {"传达": "传达：把问候转告给对方的父亲，符合句子的语境。", "拒绝": "语义：“拒绝”与“请把……给你爸爸”的请求相矛盾。", "删除": "搭配：“删除”指去掉信息或文件，不能用来表示把问候送给别人。", "购买": "搭配：“购买”的对象是商品，问候不能用来购买，也不能这样送给别人。"}, "sentence_index": 6, "correct_answer": "传达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我传达了一件新衣服。", "explanation": "这里应该用〈缝〉。传达表示把信息告诉人，做衣服要用缝。"}, {"text": "孩子们在树下传达了一些苹果。", "explanation": "这里应该用〈摘〉。传达只用于信息、意思，摘苹果要用摘。"}, {"text": "他在纸上传达了一幅画。", "explanation": "这里应该用〈绘制〉。传达表示把消息告诉别人，不指作画，在纸上绘制图案要用绘制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你把会议的时间传达全班。", "corrected_sentence": "请你把会议的时间传达给全班。", "error_description": "错误：“传达全班”；正确：“传达给全班”。“传达”需要“给”引出接收者，缺少“给”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班长已经把通知传达了给我们。", "corrected_sentence": "班长已经把通知传达给了我们。", "error_description": "错误：“传达了给我们”；正确：“传达给了我们”。“了”应放在“给”之后，表示“传达给”这个动作已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
